function discoveryScopesForBranch(_stageIndex, _branchIndex, scopes) {
  const source = Array.isArray(scopes) ? scopes.filter(Boolean) : [];
  if (source.length <= 2) return source;

  const regionScope = source[0];
  const firstLocal = source[1];
  const remainingLocal = source.slice(2)
    .map((scope) =>
      String(scope || "")
        .replace(/^география:\s*/i, "")
        .trim()
    )
    .filter(Boolean);

  const result = [regionScope, firstLocal];
  if (remainingLocal.length) {
    result.push(
      `углублённые географические пробелы: ${remainingLocal.join("; ")}. Выполняй этот проход только как продолжение продуктивного локального поиска: пройди ВСЕ перечисленные территории пакетно, не повторяй уже найденные организации и не заменяй предмет ветки общим поиском.`
    );
  }
  return result;
}

function discoveryGeoExpansionWorthwhile(stats) {
  const value = stats || {};
  return (
    Number(value.a || 0) >= 1 ||
    Number(value.strongNew || 0) >= 2 ||
    (
      Number(value.qualityScore || 0) >= 5 &&
      Number(value.sourceFamilyNovelty || 0) >= 1
    )
  );
}

function discoverySourceFamilyNovelty(current, previous = {}) {
  return Object.keys(current || {}).filter(
    (family) =>
      Number(current?.[family] || 0) > 0 &&
      Number(previous?.[family] || 0) === 0
  ).length;
}

function adaptiveDiscoveryLowYieldThreshold(knownCount) {
  // Scale the saturation threshold with the amount already discovered.
  // Around 100 known organizations this is ~2, preserving current behavior,
  // while larger markets need a larger marginal gain to justify more scopes.
  return Math.max(1, Math.min(6, Math.ceil(Math.max(1, Number(knownCount || 0)) * 0.015)));
}

function adaptiveDiscoveryLowYieldStreak(scopeCount) {
  const count = Math.max(1, Number(scopeCount || 0));
  // With the normal 3-scope layout there is only one local result available
  // before deciding whether to spend on the third/deep scope. One weak local
  // scope is therefore enough to stop deeper geographic probing.
  if (count <= 3) return 1;
  return Math.max(2, Math.min(3, Math.ceil(count / 3)));
}

function discoveryKnownNames(result, limit = DISCOVERY_ALREADY_FOUND_LIMIT) {
  return foundOrganizationNames(result, limit);
}

function mergeKnownOrganizationNames(target, result) {
  const seen = new Set(target.map((name) => normalizeOrgKey(name)).filter(Boolean));
  for (const row of allResearchRows(result)) {
    const name = String(row?.["Организация"] || "").trim();
    const key = normalizeOrgKey(name);
    if (!name || !key || seen.has(key)) continue;
    seen.add(key);
    target.push(name);
  }
  if (target.length > DISCOVERY_ALREADY_FOUND_LIMIT) {
    target.splice(0, target.length - DISCOVERY_ALREADY_FOUND_LIMIT);
  }
}

function preliminaryDiscoveryGrade(row) {
  const values = [
    String(row?.["Основание"] || "").trim(),
    String(row?.["Техника/сегмент"] || "").trim()
  ];
  for (const value of values) {
    const match = value.match(/^\s*([ABC])(?:\s|[-—:])/i);
    if (match) return match[1].toUpperCase();
  }
  return "";
}

function discoveryYieldStats(result, knownNames = []) {
  const known = new Set((knownNames || []).map((x) => normalizeOrgKey(x)).filter(Boolean));
  const byOrg = new Map();
  const modelPreliminary = { A: 0, B: 0, C: 0, ungraded: 0 };

  for (const [sheet, rows] of [
    ["direct_buyers", result?.direct_buyers || []],
    ["intermediaries", result?.intermediaries || []],
    ["leasing", result?.leasing || []]
  ]) {
    for (const row of rows) {
      const key = normalizeOrgKey(row?.["Организация"]);
      if (!key || known.has(key)) continue;

      const modelGrade = preliminaryDiscoveryGrade(row);
      if (modelGrade) modelPreliminary[modelGrade]++;
      else modelPreliminary.ungraded++;

      // Do not let the discovery model's self-assigned A/B drive more paid
      // geography/recovery searches. Reuse the same deterministic evidence
      // policy that will be applied later in qualification.
      const decision = deterministicQualificationDecision({
        id: key,
        sheet,
        row
      });
      const grade = decision?.grade || "";
      const weight = grade === "A" ? 4 : grade === "B" ? 2 : grade === "C" ? 0.35 : 0.5;
      const previous = byOrg.get(key);
      if (!previous || weight > previous.weight) {
        byOrg.set(key, { grade, weight });
      }
    }
  }

  let a = 0, b = 0, c = 0, ungraded = 0, qualityScore = 0;
  for (const item of byOrg.values()) {
    qualityScore += item.weight;
    if (item.grade === "A") a++;
    else if (item.grade === "B") b++;
    else if (item.grade === "C") c++;
    else ungraded++;
  }

  return {
    newOrganizations: byOrg.size,
    a, b, c, ungraded,
    strongNew: a + b,
    qualityScore: Number(qualityScore.toFixed(2)),
    gradingBasis: "deterministic_evidence",
    modelPreliminary
  };
}

function discoveryQualityIsLow(stats) {
  if (Number(stats?.strongNew || 0) > 0) return false;
  return Number(stats?.qualityScore || 0) < 2;
}

function countNewOrganizationsAgainstKnown(result, knownNames) {
  return discoveryYieldStats(result, knownNames).newOrganizations;
}

