const DISCOVERY_CORE_PROMPT = `ЦЕЛЬ: найти максимум реальных организаций региона, которым потенциально нужна прицепная техника САТ из-за регулярной тяжёлой автологистики или целевого грузопотока.

ПРИОРИТЕТНЫЕ ЦЕЛЕВЫЕ ГРУЗЫ И ПРОЦЕССЫ:
зерно/масличные/корма; щебень/песок/ПГС/грунт/торф; строительные и промышленные сыпучие; щепа/опилки/кора/биомасса/пеллетное сырьё; отходы/вторсырьё/лом.
Это ПРИОРИТЕТНЫЙ, но НЕ ЗАКРЫТЫЙ список. Также ищи другие сыпучие, навалочные, гранулированные, порошкообразные, лёгкие объёмные и иные грузы, если для них подтверждена регулярная тяжёлая автомобильная перевозка и прицепная техника экономически рациональна. Оценивай физический процесс и логистику, а не только совпадение со словарём.

ПРИОРИТЕТНЫЕ ПРИЗНАКИ ТЕХНИКИ:
ТОНАР, KOGEL, KRONE, SCHMITZ, GRUNWALD, WIELTON и уже встречавшиеся типы/модели проверяй в первую очередь, потому что они дают высокий yield на текущих данных. Но любая другая марка, модель или тип прицепа/полуприцепа равноправно подтверждает релевантность, если конкретная техника надёжно привязана к организации.

КЛАССИФИКАЦИЯ:
A — только ПОЛОЖИТЕЛЬНЫЙ evidence-note, который сам по себе подтверждает роль организации и конкретную прицепную технику/событие: владение/эксплуатацию, конкретную закупку или лизинг, реальную завершённую сделку/ремонт в допустимой роли. Марка/модель, карточка товара, каталог услуги или слово «полуприцеп» без такого события не дают A.
B — конкретной прицепной техники или A-события нет, но есть минимум 2 независимых сильных сигнала: целевой или аналогичный физически релевантный груз/процесс + тяжёлая логистика/тягачи/парк/лизинг/контракт/CE-вакансии/обновление.
C — подтверждён релевантный груз/процесс/перевозка, но доказательств для A/B недостаточно.
Если evidence одновременно содержит отрицательную оговорку («не подтверждено», «не найдено», «нет оснований утверждать», «уровень B/C», «не собственник», «потенциально/экономически рационально»), такой note НЕ может быть основанием A.
Уровень укажи в начале "Основания".

ЛИСТЫ:
direct_buyers — конечные грузовладельцы, перевозчики и эксплуатанты;
intermediaries — сервисы/дилеры/экспедиторы и иные каналы без подтверждённой собственной эксплуатации;
leasing — лизинговые/финансовые организации.
Лизингополучатель-эксплуатант остаётся direct_buyers.

DISCOVERY-ПРАВИЛА:
- web_search обязателен; используй несколько формулировок и синонимов.
- Приоритетно используй проверенные высокоурожайные источники и формулировки текущей методики, но НЕ считай их обязательным закрытым чеклистом.
- Если приоритетные площадки/запросы дают мало новых организаций, переходи к региональным площадкам, официальным сайтам, отраслевым каталогам, торгам, закупкам, вакансиям, дилерам, сервисам, профессиональным публикациям и другим первичным/надёжным источникам.
- ГРАНИЦА ВЕТКИ ОБЯЗАТЕЛЬНА: расширяй источники, формулировки, синонимы и географию, но НЕ расширяй предмет текущей ветки до общего поиска по этапу или региону.
- Организацию возвращай из конкретной ветки только если есть явная причинная цепочка от темы ветки к этой организации. Если компания в целом релевантна САТ, но найдена лишь через общий поиск и не связана с текущей веткой, НЕ возвращай её в этом вызове — её должен найти профильный branch/этап.
- Не подменяй слабую выдачу ветки поиском карьеров, зерна, лизинга, перевозчиков, вакансий или иных общих категорий, если они не следуют непосредственно из темы ветки.
- Возвращай ВСЕ подтверждённые релевантные организации, а не top-N, но только внутри предметной границы текущего вызова.
- Ищи конкретные организации; от объявления, вакансии, тендера, проекта или сервиса переходи к фактической компании.
- ПАТТЕРН QUALITY SAMPLE ДЛЯ ВСЕХ ЭТАПОВ: начинай с уже известных высокоурожайных типов источников текущей ветки, но не считай их закрытым списком; если они насыщены, переходи к другим релевантным источникам той же темы.
- Всегда извлекай фактическую сторону события: владельца/продавца/работодателя/лизингополучателя/клиента сервиса/перевозчика/заказчика/победителя/оператора проекта/участника мероприятия — а не площадку, агрегатор, организатора или посредника.
- Если один источник открыл конкретную организацию, пакетно проверь соседние записи этого же владельца/клиента/проекта/договора и связанные публичные кейсы; не делай отдельный web_search на каждую мелкую деталь.
- Явно разделяй роли, если в источнике несколько сторон: собственник ≠ эксплуатант; лизингодатель ≠ лизингополучатель; заказчик ≠ перевозчик; сервис ≠ клиент; холдинг/УК ≠ конкретное юрлицо; организатор ≠ участник.
- Не останавливайся на крупнейших известных компаниях: ищи локальные ООО, ИП, КФХ/СПК и другие самостоятельные организации, если они соответствуют теме ветки. ИП считаются полноценными кандидатами.
- Не делай отдельные поиски ради ИНН, телефона, директора, email, сайта, холдинга, выручки или численности.
- Для каждой организации сохрани 1–3 уже найденных сильных URL и короткие evidence notes.
- ЭФФЕКТИВНОСТЬ WEB_SEARCH: сначала объединяй несколько близких формулировок/сущностей в широкие поисковые запросы и используй найденную выдачу пакетно. Не запускай отдельный web_search для каждой компании, если её идентичность и связь с веткой уже подтверждаются текущей выдачей.
- Для одного branch×scope используй НЕ БОЛЕЕ 4 содержательных web-search проходов. Пятый проход допустим только если предыдущий реально открыл минимум несколько новых организаций И новое семейство источников; иначе остановись. Не делай перефразированные повторы ради полноты.
- После получения 1–3 сильных URL на кандидата не трать дополнительные web_search на его enrichment: следующий поиск должен быть направлен на НОВЫЕ организации.
- Не выдумывай компании и факты.`;

function compactDiscoveryPrompt({
  region,
  stageIndex,
  branch,
  branchIndex,
  totalBranches,
  scope,
  extraContext = ""
}) {
  return `${DISCOVERY_CORE_PROMPT}

ЭТАП ${stageIndex + 1}: ${DISCOVERY_STAGE_HINTS[stageIndex] || ""}
ОГРАНИЧЕНИЯ ЭТАПА: ${DISCOVERY_STAGE_GUARDRAILS[stageIndex] || ""}
ВЕТКА ${branchIndex + 1}/${totalBranches}: ${branch}
РЕГИОН: ${region}
ГЕОГРАФИЯ: ${scope}
${extraContext ? `ДОПОЛНИТЕЛЬНЫЙ КОНТЕКСТ: ${extraContext}` : ""}

Проведи самостоятельный discovery-поиск именно по этой ветке и географии.
ТЕМА ВЕТКИ — ЖЁСТКАЯ ПРЕДМЕТНАЯ ГРАНИЦА. Можно свободно менять запросы, площадки, синонимы и локальную географию, но нельзя переходить к общему поиску релевантных компаний региона.
Каждый возвращённый кандидат должен иметь в evidence notes явную связь именно с темой этой ветки: источник/событие/услуга/документ → организация. Общая релевантность САТ без этой связи недостаточна.
Если первые формулировки дают мало результатов — расширяй МЕТОД поиска, а не ПРЕДМЕТ поиска. После нахождения кандидата продолжай искать следующие организации, а не обогащай уже найденную.`;
}

function compactRecoveryPrompt({
  region,
  stageIndex,
  theme,
  scope,
  alreadyFound,
  uniqueCount,
  anchorBranch,
  sourceFamilyGaps = [],
  saturatedSourceFamilies = []
}) {
  const known = alreadyFound.length
    ? `УЖЕ НАЙДЕННЫЕ — не трать поиск на повторное обнаружение: ${alreadyFound.join("; ")}`
    : "";
  return `${DISCOVERY_CORE_PROMPT}

ЭТАП ${stageIndex + 1}: ${DISCOVERY_STAGE_HINTS[stageIndex] || ""}
ОГРАНИЧЕНИЯ ЭТАПА: ${DISCOVERY_STAGE_GUARDRAILS[stageIndex] || ""}
ЯКОРНАЯ ВЕТКА ДОБОРА: ${anchorBranch || "тема этапа"}
РЕГИОН: ${region}
ДОБОР ДЛЯ ПОЛНОТЫ: ${theme}
ГЕОГРАФИЯ: ${scope}
НЕДОПОКРЫТЫЕ СЕМЕЙСТВА ИСТОЧНИКОВ: ${sourceFamilyGaps.length ? sourceFamilyGaps.join(", ") : "не выявлены; выбери новое релевантное семейство источников сам"}.
НАСЫЩЕННЫЕ СЕМЕЙСТВА — не трать повторные поиски на них без нового конкретного зацепа: ${saturatedSourceFamilies.length ? saturatedSourceFamilies.join(", ") : "нет"}.
Сейчас найдено ${uniqueCount} уникальных организаций. Это наблюдение, а не квота: продолжай, пока новые формулировки/география дают содержательный прирост.
${known}

Ищи прежде всего НОВЫЕ организации и long tail ВНУТРИ ЯКОРНОЙ ВЕТКИ.
Recovery не является разрешением на общий поиск по этапу: меняй географию, источники, синонимы и цепочки второго порядка, но сохраняй прямую доказуемую связь каждого кандидата с якорной веткой.
ОБЯЗАТЕЛЬНО СМЕНИ СЕМЕЙСТВО ИСТОЧНИКОВ относительно основного прохода: если основной поиск опирался на каталоги/карты — переходи к официальным сайтам, тендерам, вакансиям, судебным/регуляторным документам, кейсам производителей/сервисов; если основной проход был по официальным сайтам — проверь локальные каталоги, отраслевые списки, закупки, вакансии, отзывы/кейсы. Выбирай только источники, естественно подходящие теме ветки.
Не повторяй уже использованный источник только другой формулировкой запроса. Цель recovery — открыть НОВОЕ семейство evidence и новых организаций, а не углублять уже найденных.
Если новых кандидатов внутри якорной ветки мало — верни мало результатов; НЕ компенсируй низкий yield компаниями из соседних веток.
Не выполняй enrichment найденных компаний. Не выдумывай записи ради количества.`;
}

