    "Споры по ремонту прицепной техники, рам, кузовов, гидравлики, осей и подвески. Устанавливай, чья техника ремонтировалась и кто её эксплуатировал; сервис и клиент — разные организации.",
    "ДТП и страховые споры, где идентифицируются техника, маршрут, груз и эксплуатант. Группируй материалы одного ДТП/страхового события и извлекай фактического владельца/перевозчика, не принимая страховщика или представителя за эксплуатанта."
