    "Аграрные мероприятия, зерновые и элеваторные конференции. Из программ, списков участников и спикеров извлекай конкретные хозяйства, элеваторы, трейдеров и перевозчиков; затем проверяй физический грузопоток и транспорт, а не считать участие доказательством.",
    "Лесные и деревообрабатывающие выставки/конференции. Ищи локальные лесопилки, переработчиков, производителей биомассы и перевозчиков среди участников; организатор/ассоциация остаётся посредником, если сам не является эксплуатантом.",
    "Мероприятия по отходам, переработке, вторсырью и металлолому. Из участников выделяй операторов площадок, переработчиков и перевозчиков, затем подтверждай лицензии/процессы/транспорт вне мероприятия.",
