async function loadPrompt(n) {
  const commonPath = path.resolve("prompts/common.txt");
  const promptPath = path.resolve("prompts", String(n).padStart(2, "0") + ".txt");
  const [common, specific] = await Promise.all([
    fs.readFile(commonPath, "utf8"),
    fs.readFile(promptPath, "utf8")
  ]);
  return specific + "\n\n" + common;
}

function normalize(data, withStats = false) {
  const result = {
    direct_buyers: Array.isArray(data?.direct_buyers) ? data.direct_buyers : [],
    intermediaries: Array.isArray(data?.intermediaries) ? data.intermediaries : [],
    leasing: Array.isArray(data?.leasing) ? data.leasing : []
  };
  if (withStats) {
    result.statistics = Array.isArray(data?.statistics) ? data.statistics : [];
  }
  return result;
}

function rowCount(result) {
  return (
    (result.direct_buyers?.length || 0) +
    (result.intermediaries?.length || 0) +
    (result.leasing?.length || 0)
  );
}

function emptyResearchResult() {
  return { direct_buyers: [], intermediaries: [], leasing: [] };
}

async function mapWithConcurrency(items, concurrency, worker) {
  const source = Array.isArray(items) ? items : [];
  if (!source.length) return [];
  const limit = Math.max(1, Math.min(Number(concurrency || 1), source.length));
  const results = new Array(source.length);
  let cursor = 0;

  async function run(workerIndex) {
    while (true) {
      const index = cursor++;
      if (index >= source.length) return;
      results[index] = await worker(source[index], index, workerIndex);
    }
  }

  await Promise.all(Array.from({ length: limit }, (_, workerIndex) => run(workerIndex)));
  return results;
}

function deadlineRemaining(deadlineAt) {
  return Math.max(0, Number(deadlineAt || 0) - Date.now());
}

function createCheckpointBatcher(flush) {
  let pending = 0;
  let lastFlushAt = Date.now();
  let chain = Promise.resolve();

  const request = async ({ force = false } = {}) => {
    pending++;
    const due = force ||
      pending >= CHECKPOINT_FLUSH_EVERY ||
      Date.now() - lastFlushAt >= CHECKPOINT_FLUSH_INTERVAL_MS;
    if (!due) return;

    pending = 0;
    lastFlushAt = Date.now();
    chain = chain.then(() => flush()).catch((error) => {
      console.error("[CHECKPOINT_BATCH_FLUSH_ERROR] " + JSON.stringify({
        error: error?.message || String(error)
      }));
      throw error;
    });
    await chain;
  };

  return {
    request,
    flush: async () => {
      if (pending > 0) await request({ force: true });
      else await chain;
    }
  };
}

function appendResearchResult(target, source, passNumber) {
  for (const sheet of ["direct_buyers", "intermediaries", "leasing"]) {
    for (const row of source?.[sheet] || []) {
      target[sheet].push({
        ...row,
        __research_pass: passNumber
      });
    }
  }
}

function allResearchRows(result) {
  return [
    ...(result?.direct_buyers || []),
    ...(result?.intermediaries || []),
    ...(result?.leasing || [])
  ];
}

const DISCOVERY_SOURCE_FAMILIES = [
  "official",
  "procurement",
  "vacancy",
  "court_regulatory",
  "catalog_map",
  "marketplace_listing",
  "industry_media"
];

function discoverySourceFamily(url) {
  const value = String(url || "").trim().toLowerCase();
  if (!value) return "unknown";
  let host = "";
  try {
    host = new URL(value).hostname.replace(/^www\./, "");
  } catch {
    host = value;
  }

  if (/(zakup|tender|b2b|bidzaar|synapsenet|komtender|rostender|poisktender|tenderguru|etp|goszakup)/.test(host + value)) return "procurement";
  if (/(hh\.ru|superjob|dreamjob|rabota|vacan|job|zarplata)/.test(host + value)) return "vacancy";
  if (/(sudact|kad\.arbitr|actofact|garant\.ru|consultant|rostransnadzor|fedresurs|reestr|registry|nalog)/.test(host + value)) return "court_regulatory";
  if (/(2gis|yandex\.|sprav|jsprav|cataloxy|orgpage|ds67|mestas|yaspravka|nashaspravka)/.test(host + value)) return "catalog_map";
  if (/(avito|drom|auto\.ru|autoline|truck1|machineryline|gruzovik\.com|heveya|auction|torg)/.test(host + value)) return "marketplace_listing";
  if (/(news|press|journal|media|vesti|rg\.ru|kommersant|rbc|invest|promportal|industry)/.test(host + value)) return "industry_media";
  return "official";
}

function discoverySourceFamilyStats(result) {
  const counts = Object.fromEntries(DISCOVERY_SOURCE_FAMILIES.map((family) => [family, 0]));
  for (const row of allResearchRows(result)) {
    for (const url of row?.__evidence?.source_urls || []) {
      const family = discoverySourceFamily(url);
      if (family in counts) counts[family]++;
    }
  }
  return counts;
}

function discoverySourceFamilyGaps(stats, limit = 3) {
  const counts = stats || {};
  return [...DISCOVERY_SOURCE_FAMILIES]
    .sort((a, b) => Number(counts[a] || 0) - Number(counts[b] || 0))
    .filter((family) => Number(counts[family] || 0) <= 1)
    .slice(0, limit);
}

function discoverySaturatedSourceFamilies(stats, limit = 4) {
  const counts = stats || {};
  return [...DISCOVERY_SOURCE_FAMILIES]
    .sort((a, b) => Number(counts[b] || 0) - Number(counts[a] || 0))
    .filter((family) => Number(counts[family] || 0) >= 3)
    .slice(0, limit);
}

const ENTITY_CENSUS_BUCKETS = [
  {
    key: "transport",
    label: "автомобильные грузоперевозчики, АТП и транспортные операторы",
    pattern: /(грузоперевоз|перевозчик|автотранспорт|атп\b|транспортн.{0,20}(компан|оператор)|экспедитор)/
  },
  {
    key: "agro",
    label: "агро, зерно, элеваторы, комбикорм и масличные",
    pattern: /(зерн|элеватор|комбикорм|агро|сельск.{0,20}хозяйств|кфх\b|спк\b|рапс|пшениц|масличн)/
  },
  {
    key: "quarries",
    label: "карьеры, щебень, песок, ПГС и нерудные материалы",
    pattern: /(карьер|щеб|песок|пгс|неруд|грави|добыч.{0,30}(камн|пес|грав|щеб))/
  },
  {
    key: "construction",
    label: "бетон, ЖБИ, цемент, асфальт и строительные материалы",
    pattern: /(бетон|жби|цемент|асфальт|стройматериал|дорожн.{0,20}(строит|ремонт))/
  },
  {
    key: "wood",
    label: "лес, деревообработка, лесопиление, щепа и пеллеты",
    pattern: /(лесозаготов|лесопил|деревообработ|пиломатериал|щеп|опил|пеллет|древес)/
  },
  {
    key: "waste",
    label: "отходы, вторсырьё, металлолом и вторчермет",
    pattern: /(отход|тко\b|вторсыр|металлолом|вторчермет|лом.{0,20}металл)/
  },
  {
    key: "industrial",
    label: "крупные промышленные грузовладельцы с регулярными сыпучими/навалочными потоками",
    pattern: /(промышлен|производств|завод|фабрик|комбинат|сырь|сыпуч|навалоч|грузопоток)/
  }
];

function rowCoverageText(row) {
  const evidence = row?.__evidence || {};
  return [
    row?.["Организация"],
    row?.["Город/район"],
    row?.["Техника/сегмент"],
    row?.["Основание"],
    ...(Array.isArray(evidence.notes) ? evidence.notes : [])
  ]
    .map((value) => String(value || "").toLowerCase().replace(/ё/g, "е"))
    .join("\n");
}

function coverageSnapshot(result, scopes = []) {
  const rows = allResearchRows(result);
  const sectors = Object.fromEntries(ENTITY_CENSUS_BUCKETS.map((bucket) => [bucket.key, 0]));
  for (const row of rows) {
    const text = rowCoverageText(row);
    for (const bucket of ENTITY_CENSUS_BUCKETS) {
      if (bucket.pattern.test(text)) sectors[bucket.key]++;
    }
  }

  const geography = [];
  for (const scope of (Array.isArray(scopes) ? scopes.slice(1) : [])) {
    const places = String(scope || "")
      .replace(/^география:\s*/i, "")
      .replace(/^углублённые географические пробелы:\s*/i, "")
      .split(/[;,]/)
      .map((value) => value.replace(/\..*$/, "").trim().toLowerCase())
      .filter((value) => value.length >= 3);
    if (!places.length) continue;
    const count = rows.filter((row) => {
      const place = String(row?.["Город/район"] || "").toLowerCase();
      return places.some((token) => place.includes(token));
    }).length;
    geography.push({ scope: String(scope), count });
  }

  geography.sort((a, b) => a.count - b.count);
  return {
    total: uniqueResearchCount(result),
    sectors,
    undercovered_geography: geography.slice(0, 3)
  };
}

function entityCensusPrompt({ region, bucket, alreadyFound, geography = "" }) {
  const known = (alreadyFound || []).slice(-DISCOVERY_ALREADY_FOUND_LIMIT);
  return `${DISCOVERY_CORE_PROMPT}

ENTITY CENSUS / COVERAGE PASS.
РЕГИОН: ${region}
СЕКТОР: ${bucket.label}
${geography ? `ГЕОГРАФИЧЕСКИЙ ПРОБЕЛ: ${geography}` : "ГЕОГРАФИЯ: весь регион, включая малые города и районы."}

Цель этого вызова — найти СОСТАВ ДЕЙСТВУЮЩИХ ОРГАНИЗАЦИЙ сектора, а не только свежие события.
Свежая закупка, вакансия, тендер или новость НЕ обязательны.
Используй официальные отраслевые списки, реестры, каталоги организаций, карты, ассоциации, сайты районов/промзон и обычный web-поиск как discovery-источники.
Для direct buyer достаточно доказать действующий целевой производственный/грузовой процесс; если собственная техника пока не найдена, это допустимый C-кандидат.
Органы власти и бюджетные учреждения не возвращай. ГУП/МУП/ФГУП оценивай по фактической хозяйственной роли.
Не возвращай организации только по одному ОКВЭД без подтверждения реальной деятельности.
Не обогащай телефон/директора/выручку. Сохраняй 1–3 сильных URL и короткие evidence notes.
УЖЕ НАЙДЕНО — ищи прежде всего новые организации: ${known.length ? known.join("; ") : "нет"}.
Верни все подтверждённые новые организации этого сектора, которые удалось найти без выдумывания.`;
}

async function runEntityCensusAndGapSearch({
  client,
  region,
  parts,
  researchScopes,
  assertNotCancelled
}) {
  const existing = emptyResearchResult();
  for (const part of parts) appendResearchResult(existing, part, "pre-census");

  const additions = emptyResearchResult();
  const known = foundOrganizationNames(existing, DISCOVERY_ALREADY_FOUND_LIMIT);

  for (let index = 0; index < ENTITY_CENSUS_BUCKETS.length; index++) {
    await assertNotCancelled();
    const bucket = ENTITY_CENSUS_BUCKETS[index];
    const result = normalize(await askResearch(
      client,
      entityCensusPrompt({ region, bucket, alreadyFound: known }),
      RESEARCH_MICRO_MAX_OUTPUT_TOKENS,
      `entity census | ${bucket.key} | ${index + 1}/${ENTITY_CENSUS_BUCKETS.length}`,
      3
    ));
    appendResearchResult(additions, result, `census-${bucket.key}`);
    mergeKnownOrganizationNames(known, result);
    console.log("[ENTITY_CENSUS_RESULT] " + JSON.stringify({
      bucket: bucket.key,
      rows: rowCount(result),
      unique: uniqueResearchCount(result)
    }));
  }

  const combined = emptyResearchResult();
  appendResearchResult(combined, existing, "existing");
  appendResearchResult(combined, additions, "census");
  let coverage = coverageSnapshot(combined, researchScopes);

  const gapBuckets = ENTITY_CENSUS_BUCKETS
    .map((bucket) => ({
      ...bucket,
      count: Number(coverage.sectors[bucket.key] || 0)
    }))
    .filter((bucket) => bucket.count < CENSUS_BUCKET_MIN)
    .sort((a, b) => a.count - b.count)
    .slice(0, COVERAGE_GAP_MAX);

  for (let index = 0; index < gapBuckets.length; index++) {
    await assertNotCancelled();
    const bucket = gapBuckets[index];
    const geo = coverage.undercovered_geography[index % Math.max(1, coverage.undercovered_geography.length)]?.scope || "";
    const result = normalize(await askResearch(
      client,
      entityCensusPrompt({
        region,
        bucket,
        alreadyFound: known,
        geography: geo
      }),
      RESEARCH_MICRO_MAX_OUTPUT_TOKENS,
      `coverage gap | ${bucket.key} | ${index + 1}/${gapBuckets.length}`,
      3
    ));
    appendResearchResult(additions, result, `coverage-gap-${bucket.key}`);
    appendResearchResult(combined, result, `coverage-gap-${bucket.key}`);
    mergeKnownOrganizationNames(known, result);
  }

  coverage = coverageSnapshot(combined, researchScopes);
  console.log("[ENTITY_CENSUS_SUMMARY] " + JSON.stringify({
    added_rows: rowCount(additions),
    added_unique: uniqueResearchCount(additions),
    coverage,
    gap_buckets: gapBuckets.map((bucket) => bucket.key)
  }));

  return { additions, coverage, gapBuckets: gapBuckets.map((bucket) => bucket.key) };
}

function researchRowKey(row) {
  const inn = normalizeInn(row?.["ИНН"]);
  if (inn) return `inn:${inn}`;
  const org = normalizeOrgKey(row?.["Организация"]);
  const place = normalizePlaceKey(row?.["Город/район"]);
  return org ? `org:${org}|${place}` : "";
}

function uniqueResearchCount(result) {
  const keys = new Set();
  let anonymous = 0;
  for (const row of allResearchRows(result)) {
    const key = researchRowKey(row);
    if (key) keys.add(key);
    else anonymous++;
  }
  return keys.size + anonymous;
}

function foundOrganizationNames(result, limit = 180) {
  const names = [];
  const seen = new Set();
  for (const row of allResearchRows(result)) {
    const name = String(row?.["Организация"] || "").trim();
    const key = normalizeOrgKey(name);
    if (!name || !key || seen.has(key)) continue;
    seen.add(key);
    names.push(name);
    if (names.length >= limit) break;
  }
  return names;
}

function normalizeSearchScope(value) {
  if (value === null || value === undefined) return "";
  if (typeof value === "string" || typeof value === "number") {
    return String(value).replace(/\s+/g, " ").trim();
  }
  if (Array.isArray(value)) {
    return value.map(normalizeSearchScope).filter(Boolean).join(", ");
  }
  if (typeof value === "object") {
    const preferredKeys = [
      "name",
      "title",
      "label",
      "place",
      "city",
      "district",
      "municipality",
      "cluster",
      "territory",
      "area"
    ];
    for (const key of preferredKeys) {
      const normalized = normalizeSearchScope(value?.[key]);
      if (normalized) return normalized;
    }
    const pieces = Object.values(value)
      .map(normalizeSearchScope)
      .filter(Boolean);
    return [...new Set(pieces)].join(" — ");
  }
  return "";
}

async function discoverRegionSearchScopes(client, region) {
  const result = await askJson(client, {
    input: `Верни ТОЛЬКО JSON без markdown:
{"places":["строка"],"clusters":["строка"]}.
Для региона "${region}" перечисли 12–18 наиболее полезных географических точек для B2B-поиска тяжёлой логистики: областной центр, крупные и средние города, значимые районные центры. В clusters дай до 6 известных промышленных/аграрных/лесных/карьерных территорий или муниципальных кластеров.
ВАЖНО: каждый элемент places и clusters должен быть ПРОСТОЙ СТРОКОЙ с названием, не объектом и не структурой JSON.
Не включай населённые пункты вне региона. Используй web_search для проверки принадлежности к региону.`,
    model: MODEL,
    maxOutputTokens: 5000,
    webSearch: true,
    responseSchema: GEO_SCOPE_SCHEMA,
    schemaName: "region_search_scopes",
    diagnosticLabel: `география региона | ${region}`
  });

  const values = [
    ...(Array.isArray(result?.places) ? result.places : []),
    ...(Array.isArray(result?.clusters) ? result.clusters : [])
  ]
    .map(normalizeSearchScope)
    .filter(Boolean);

  const unique = [...new Set(values.map((x) => x.toLowerCase()))]
    .map((lower) => values.find((x) => x.toLowerCase() === lower))
    .filter(Boolean)
    .slice(0, 20);

  if (!unique.length) return [`весь регион: ${region}`];

  const groupCount = Math.min(RESEARCH_GEO_GROUPS, unique.length);
  const groups = Array.from({ length: groupCount }, () => []);
  unique.forEach((value, index) => groups[index % groupCount].push(value));

  return [
    `весь регион: ${region}`,
    ...groups
      .filter((group) => group.length)
      .map((group) => `география: ${group.join(", ")}`)
  ];
}

async function runResearchMicroBatch({
  client,
  region,
  stageIndex,
  branch,
  branchIndex,
  branches,
  scopes,
  extraContext = "",
  alreadyFound = []
}) {
  const selectedScopes = discoveryScopesForBranch(stageIndex, branchIndex, scopes);
  const merged = emptyResearchResult();
  const knownNames = [...alreadyFound];
  let successCount = 0;
  let firstError = null;
  let lowYieldStreak = 0;
  let regionalYield = null;
  let firstLocalYield = null;
  let regionalFamilies = {};
  let previousScopeFamilies = {};

  for (let scopeIndex = 0; scopeIndex < selectedScopes.length; scopeIndex++) {
    if (
      scopeIndex >= 2 &&
      firstLocalYield &&
      !discoveryGeoExpansionWorthwhile(firstLocalYield) &&
      !discoveryGeoExpansionWorthwhile(regionalYield)
    ) {
      console.log("[DISCOVERY_GEO_EXPANSION_SKIP] " + JSON.stringify({
        stage: stageIndex + 1,
        branch: branchIndex + 1,
        reason: "regional_and_first_local_scope_not_productive_enough",
        regional_quality_yield: regionalYield,
        first_local_quality_yield: firstLocalYield,
        skipped_scopes: selectedScopes.length - scopeIndex
      }));
      break;
    }

    const scope = selectedScopes[scopeIndex];
    const beforeKnown = [...knownNames];
    const knownContext = knownNames.length
      ? `УЖЕ НАЙДЕННЫЕ В ЭТОМ РЕГИОНЕ — не трать web_search на повторное обнаружение этих организаций; ищи новые: ${knownNames.join("; ")}`
      : "";

    try {
      const value = await askResearch(
        client,
        compactDiscoveryPrompt({
          region,
          stageIndex,
          branch,
          branchIndex,
          totalBranches: branches.length,
          scope,
          extraContext: [extraContext, knownContext].filter(Boolean).join("\n")
        }),
        RESEARCH_MICRO_MAX_OUTPUT_TOKENS,
        `этап ${stageIndex + 1} | ветка ${branchIndex + 1}/${branches.length} | ${branch} | ${scope}`
      );

      const normalized = normalize(value);
      const yieldStats = discoveryYieldStats(normalized, beforeKnown);
      const familyStats = discoverySourceFamilyStats(normalized);
      yieldStats.sourceFamilyNovelty = discoverySourceFamilyNovelty(
        familyStats,
        scopeIndex === 0 ? {} : previousScopeFamilies
      );
      const added = yieldStats.newOrganizations;
      if (scopeIndex === 0) {
        regionalYield = yieldStats;
        regionalFamilies = familyStats;
      }
      if (scopeIndex === 1) {
        yieldStats.sourceFamilyNovelty = discoverySourceFamilyNovelty(
          familyStats,
          regionalFamilies
        );
        firstLocalYield = yieldStats;
      }
      previousScopeFamilies = familyStats;
      console.log("[DISCOVERY_SCOPE_RESULT] " + JSON.stringify({
        stage: stageIndex + 1,
        branch: branchIndex + 1,
        branch_name: branch,
        scope_index: scopeIndex + 1,
        scope,
        rows: diagnosticRowCount(normalized),
        new_organizations: added,
        quality_yield: yieldStats,
        source_families: familyStats,
        source_family_novelty: yieldStats.sourceFamilyNovelty,
        token_usage_cumulative: tokenUsageSnapshot(client)
      }));
      console.log("[DISCOVERY_SCOPE_COMPANIES_SAMPLE] " + JSON.stringify({
        stage: stageIndex + 1,
        branch: branchIndex + 1,
        scope_index: scopeIndex + 1,
        sample: diagnosticDiscoveryRows(normalized).slice(0, 10)
      }));
      appendResearchResult(
        merged,
        normalized,
        `branch-${branchIndex + 1}-scope-${scopeIndex + 1}`
      );
      mergeKnownOrganizationNames(knownNames, normalized);
      successCount++;

      // Первый scope всегда региональный. Низкий yield локальных scope подряд означает,
      // что дальнейшее географическое дробление в этой ветке даёт в основном повторы.
      if (scopeIndex > 0) {
        const threshold = adaptiveDiscoveryLowYieldThreshold(knownNames.length);
        const streakLimit = adaptiveDiscoveryLowYieldStreak(selectedScopes.length);
        lowYieldStreak =
          added <= threshold || discoveryQualityIsLow(yieldStats)
            ? lowYieldStreak + 1
            : 0;
        if (
          lowYieldStreak >= streakLimit &&
          scopeIndex + 1 < selectedScopes.length
        ) {
          console.log("[DISCOVERY_SCOPE_STOP] " + JSON.stringify({
            stage: stageIndex + 1,
            branch: branchIndex + 1,
            processed_scopes: scopeIndex + 1,
            total_scopes: selectedScopes.length,
            last_added: added,
            threshold,
            streak_limit: streakLimit
          }));
          break;
        }
      }
    } catch (error) {
      if (isWebBudgetStop(error)) throw error;
      if (!firstError) firstError = error;
    }
  }

  if (!successCount && firstError) throw firstError;
  return merged;
}

function flattenCandidates(parts) {
  const rows = [];
  const groups = [
    ["direct_buyers", "Прямые покупатели"],
    ["intermediaries", "Посредники"],
    ["leasing", "Лизинг"]
  ];

  for (let stepIndex = 0; stepIndex < parts.length; stepIndex++) {
    const part = parts[stepIndex] || {};
    for (const [key, sourceSheet] of groups) {
      for (const row of part[key] || []) {
        rows.push({
          candidate_id: `c${String(rows.length + 1).padStart(6, "0")}`,
          source_step: stepIndex + 1,
          source_sheet: sourceSheet,
          data: row
        });
      }
    }
  }
  return rows;
}

function innChecksumValid(digits) {
  const sum = (weights) => weights.reduce((total, weight, index) => total + weight * Number(digits[index]), 0) % 11 % 10;
  if (digits.length === 10) return sum([2, 4, 10, 3, 5, 9, 4, 6, 8]) === Number(digits[9]);
  if (digits.length === 12) {
    return sum([7, 2, 4, 10, 3, 5, 9, 4, 6, 8]) === Number(digits[10]) &&
      sum([3, 7, 2, 4, 10, 3, 5, 9, 4, 6, 8]) === Number(digits[11]);
  }
  return false;
}

function normalizeInn(value) {
  const digits = String(value || "").replace(/\D/g, "");
  return (digits.length === 10 || digits.length === 12) && innChecksumValid(digits) ? digits : "";
}

function normalizeOrgKey(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/\b(общество с ограниченной ответственностью|публичное акционерное общество|открытое акционерное общество|закрытое акционерное общество|акционерное общество|индивидуальный предприниматель)\b/g, " ")
    .replace(/[«»"'.,()]/g, " ")
    .replace(/\b(ооо|ао|пао|зао|оао|ип)\b/g, " ")
    .replace(/[^a-zа-яё0-9]+/gi, " ")
    .trim()
    .replace(/\s+/g, " ");
}

function normalizePlaceKey(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/[^a-zа-яё0-9]+/gi, " ")
    .trim()
    .replace(/\s+/g, " ");
}

function evidenceDomains(row) {
  const urls = Array.isArray(row?.__evidence?.source_urls)
    ? row.__evidence.source_urls
    : [];
  const domains = new Set();
  for (const raw of urls) {
    try {
      const host = new URL(String(raw)).hostname
        .toLowerCase()
        .replace(/^www\./, "");
      if (host) domains.add(host);
    } catch {}
  }
  return domains;
}

function buildIdentityClusters(candidates) {
  const parent = candidates.map((_, i) => i);

  const find = (x) => {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  };
  const union = (a, b) => {
    const ra = find(a);
    const rb = find(b);
    if (ra !== rb) parent[rb] = ra;
  };

  const byExactName = new Map();
  const byNamePlace = new Map();
  const byDomain = new Map();

  for (let i = 0; i < candidates.length; i++) {
    const row = candidates[i]?.data || {};
    const org = normalizeOrgKey(row["Организация"]);
    const place = normalizePlaceKey(row["Город/район"]);

    if (org) {
      const exact = byExactName.get(org);
      if (exact !== undefined) union(i, exact);
      else byExactName.set(org, i);

      if (place) {
        const key = `${org}|${place}`;
        const known = byNamePlace.get(key);
        if (known !== undefined) union(i, known);
        else byNamePlace.set(key, i);
      }
    }

    for (const domain of evidenceDomains(row)) {
      // Один домен сам по себе не доказывает дубль. Объединяем по домену
      // только если нормализованное название также совпадает.
      if (!org) continue;
      const key = `${domain}|${org}`;
      const known = byDomain.get(key);
      if (known !== undefined) union(i, known);
      else byDomain.set(key, i);
    }
  }

  const groups = new Map();
  for (let i = 0; i < candidates.length; i++) {
    const root = find(i);
    if (!groups.has(root)) groups.set(root, []);
    groups.get(root).push(candidates[i]);
  }

  return [...groups.values()].map((items, index) => ({
    cluster_id: `i${String(index + 1).padStart(6, "0")}`,
    items
  }));
}

function extractInnFromEvidenceNotes(row) {
  const notes = Array.isArray(row?.__evidence?.notes) ? row.__evidence.notes : [];
  const candidates = new Set();
  for (const note of notes) {
    const text = String(note || "");
    for (const match of text.matchAll(/ИНН\s*[:№-]?\s*(\d{10}|\d{12})/gi)) {
      const inn = normalizeInn(match[1]);
      if (inn) candidates.add(inn);
    }
  }
  return candidates.size === 1 ? [...candidates][0] : "";
}

function extractInnFromEvidenceUrls(row) {
  const urls = Array.isArray(row?.__evidence?.source_urls) ? row.__evidence.source_urls : [];
  const candidates = new Set();

  for (const raw of urls) {
    const text = String(raw || "");
    const decoded = (() => {
      try { return decodeURIComponent(text); } catch { return text; }
    })();

    const patterns = [
      /(?:^|[^a-z])inn[-_/:= ]*(\d{10}|\d{12})(?:\D|$)/gi,
      /(?:^|[^a-zа-я])инн[-_/:= ]*(\d{10}|\d{12})(?:\D|$)/gi
    ];
    for (const pattern of patterns) {
      for (const match of decoded.matchAll(pattern)) {
        const inn = normalizeInn(match[1]);
        if (inn) candidates.add(inn);
      }
    }
  }

  return candidates.size === 1 ? [...candidates][0] : "";
}

function clusterEvidenceIdentity(cluster) {
  const items = cluster?.items || [];
  const inns = new Set();
  const names = new Set();
  const places = new Set();
  const domains = new Set();

  for (const item of items) {
    const row = item?.data || {};
    const directInn = normalizeInn(row["ИНН"]);
    const evidenceInn = extractInnFromEvidenceNotes(row);
    const urlInn = extractInnFromEvidenceUrls(row);
    if (directInn) inns.add(directInn);
    if (evidenceInn) inns.add(evidenceInn);
    if (urlInn) inns.add(urlInn);

    const name = normalizeOrgKey(row["Организация"]);
    if (name) names.add(name);

    const place = normalizePlaceKey(row["Город/район"]);
    if (place) places.add(place);

    for (const domain of evidenceDomains(row)) domains.add(domain);
  }

  return {
    inns: [...inns],
    names: [...names],
    places: [...places],
    domains: [...domains]
  };
}

function looksAmbiguousOrganizationName(value) {
  const raw = String(value || "").trim().toLowerCase();
  const normalized = normalizeOrgKey(value);
  if (!normalized) return true;

  const genericTokens = new Set([
    "тандем","транзит","ресурс","ресурсы","агро","карьер","сервис","логистика",
    "транспорт","строй","групп","группа","центр","торг","торговый","компания",
    "поставка","снабжение","экспресс","авто","спецтехника","техно","альянс"
  ]);
  const tokens = normalized.split(/\s+/).filter(Boolean);

  if (tokens.length === 1 && genericTokens.has(tokens[0])) return true;
  if (/^(сервис|центр|площадка|направление|филиал)\b/.test(raw)) return true;
  if (/основани[ея]\s+[abc]/i.test(raw)) return true;

  return false;
}

function clusterNeedsIdentityWebSearch(cluster) {
  const items = cluster?.items || [];
  if (!items.length) return false;

  const row = items[0]?.data || {};
  const identity = clusterEvidenceIdentity(cluster);

  // Конфликтующие ИНН требуют внешней проверки при любом размере кластера.
  if (identity.inns.length > 1) return true;

  // Один подтверждённый ИНН уже достаточен и для singleton, и для повторных
  // упоминаний: повторно искать тот же ИНН через web не нужно.
  if (identity.inns.length === 1) return false;

  const org = String(row["Организация"] || "").trim();
  if (looksAmbiguousOrganizationName(org)) return true;

  if (items.length > 1) {
    const normalizedNames = new Set(
      items.map((item) => normalizeOrgKey(item?.data?.["Организация"])).filter(Boolean)
    );
    const places = items
      .map((item) => normalizePlaceKey(item?.data?.["Город/район"]))
      .filter(Boolean);
    const sameNonEmptyPlace =
      places.length === items.length && new Set(places).size === 1;

    const domainSets = items.map((item) => evidenceDomains(item?.data || {}));
    let sharedDomain = false;
    if (domainSets.length && domainSets.every((set) => set.size)) {
      sharedDomain = [...domainSets[0]].some((domain) =>
        domainSets.slice(1).every((set) => set.has(domain))
      );
    }

    // Повторные упоминания одного и того же недвусмысленного названия уже
    // достаточно связаны, если совпадает география либо есть общий evidence-domain.
    // Dedupe ниже объединит их детерминированно; web-search здесь не добавляет
    // достаточной ценности, чтобы оправдать отдельный identity-вызов.
    if (normalizedNames.size === 1 && (sameNonEmptyPlace || sharedDomain)) {
      return false;
    }

    return true;
  }

  // Несколько разных доменов при singleton часто означают агрегаторы/посредников
  // или неочевидную юридическую идентичность.
  if (identity.domains.length > 2) return true;

  return false;
}

function resolveClusterWithoutWeb(cluster) {
  const identity = clusterEvidenceIdentity(cluster);
  const inn = identity.inns.length === 1 ? identity.inns[0] : "";
  return cluster.items.map((item) => {
    const data = { ...(item?.data || {}) };
    if (inn) {
      data["ИНН"] = inn;
      const existingEvidence = data.__evidence || {};
      data.__evidence = {
        ...existingEvidence,
        source_urls: Array.isArray(existingEvidence.source_urls)
          ? [...new Set(existingEvidence.source_urls.map(String).filter(Boolean))]
          : [],
        notes: [
          ...(Array.isArray(existingEvidence.notes) ? existingEvidence.notes : []),
          `Identity без нового web-search: ИНН ${inn} извлечён из уже собранного evidence.`
        ]
      };
    }
    return { ...item, data };
  });
}

function compactIdentityCluster(cluster) {
  return {
    cluster_id: cluster.cluster_id,
    mentions: cluster.items.map((item) => ({
      candidate_id: item.candidate_id,
      source_step: item.source_step,
      source_sheet: item.source_sheet,
      organization: item?.data?.["Организация"] || "",
      city: item?.data?.["Город/район"] || "",
      segment: item?.data?.["Техника/сегмент"] || "",
      basis: item?.data?.["Основание"] || "",
      evidence: item?.data?.__evidence || {}
    }))
  };
}

function applyIdentityResult(cluster, result) {
  const byId = new Map(cluster.items.map((item) => [item.candidate_id, item]));
  const assigned = new Set();
  const resolved = [];

  for (const entity of Array.isArray(result?.entities) ? result.entities : []) {
    const ids = [...new Set(
      (Array.isArray(entity?.candidate_ids) ? entity.candidate_ids : [])
        .map(String)
        .filter((id) => byId.has(id) && !assigned.has(id))
    )];
    if (!ids.length) continue;

    const inn = normalizeInn(entity?.confirmed_inn);
    // Без подтвержденного ИНН не разрешаем модели склеить несколько упоминаний.
    const groups = inn ? [ids] : ids.map((id) => [id]);

    for (const groupIds of groups) {
      for (const id of groupIds) assigned.add(id);
      for (const id of groupIds) {
        const original = byId.get(id);
        const data = { ...(original?.data || {}) };
        if (inn) data["ИНН"] = inn;
        if (String(entity?.legal_name || "").trim()) {
          data["Организация"] = String(entity.legal_name).trim();
        }
        if (String(entity?.city || "").trim() && !String(data["Город/район"] || "").trim()) {
          data["Город/район"] = String(entity.city).trim();
        }

        const existingEvidence = data.__evidence || {};
        const sourceUrls = [
          ...(Array.isArray(existingEvidence.source_urls) ? existingEvidence.source_urls : []),
          ...(Array.isArray(entity?.source_urls) ? entity.source_urls : [])
        ].map(String).filter(Boolean);
        const identityNote = String(entity?.note || "").trim();
        const identityNoteWithMarker = identityNote
          ? `${identityRegionMismatchFromNotes([`Identity: ${identityNote}`]) ? "[IDENTITY_REGION_MISMATCH] " : ""}Identity: ${identityNote}`
          : "";
        const notes = [
          ...(Array.isArray(existingEvidence.notes) ? existingEvidence.notes : []),
          identityNoteWithMarker,
          inn ? `Подтверждённый ИНН: ${inn}` : ""
        ].filter(Boolean);
        data.__evidence = {
          ...existingEvidence,
          source_urls: [...new Set(sourceUrls)],
          notes: [...new Set(notes)],
          ...(inn && Array.isArray(entity?.source_urls) && entity.source_urls.some((url) => /^https?:\/\//i.test(String(url)))
            ? { identity_verification: { inn, method: "identity_web", source_urls: entity.source_urls } }
            : {})
        };

        resolved.push({ ...original, data });
      }
    }
  }

  for (const item of cluster.items) {
    if (!assigned.has(item.candidate_id)) resolved.push(item);
  }
  return resolved;
}

async function resolveCandidateIdentities({
  client,
  candidates,
  region,
  prompt,
  onProgress,
  assertNotCancelled,
  allowWebSearch = true
}) {
  const clusters = buildIdentityClusters(candidates);
  const resolved = [];
  let completed = 0;
  let confirmedInnMentions = 0;
  let failedClusters = 0;
  let skippedWebClusters = 0;
  let searchedWebClusters = 0;

  const directClusters = [];
  const webClusters = [];

  for (const cluster of clusters) {
    const needsIdentityLookup = clusterNeedsIdentityWebSearch(cluster);
    if (allowWebSearch && needsIdentityLookup) webClusters.push(cluster);
    else directClusters.push(cluster);
  }

  console.log("[IDENTITY_SEARCH_PLAN] " + JSON.stringify({
    total_clusters: clusters.length,
    identity_web_clusters: webClusters.length,
    direct_clusters: directClusters.length,
    missing_inn_deferred_to_final: true,
    allow_web_search: allowWebSearch
  }));

  for (const cluster of directClusters) {
    await assertNotCancelled();
    const rows = resolveClusterWithoutWeb(cluster);
    confirmedInnMentions += rows.filter((x) => normalizeInn(x?.data?.["ИНН"])).length;
    resolved.push(...rows);
    completed++;

    if (completed % 25 === 0 || completed === clusters.length) {
      await onProgress({
        completed,
        total: clusters.length,
        confirmedInnMentions,
        failedClusters,
        skippedWebClusters,
        searchedWebClusters
      });
    }
  }

  const identityConcurrency = client?.__webBudget?.kind !== "full" && client?.__webBudget ? 1 : IDENTITY_CONCURRENCY;
  let identityBudgetStopped = false;
  for (let offset = 0; offset < webClusters.length; offset += identityConcurrency) {
    await assertNotCancelled();
    const batch = webClusters.slice(offset, offset + identityConcurrency);
    const settled = await Promise.allSettled(
      batch.map((cluster) =>
        askJson(client, {
          input:
            identityResolutionContract() +
            `\n\nРЕГИОН: ${region}
ВЕРОЯТНЫЙ КЛАСТЕР:
${JSON.stringify(compactIdentityCluster(cluster))}`,
          model: TARGETED_SEARCH_MODEL,
          maxOutputTokens: IDENTITY_MAX_OUTPUT_TOKENS,
          webSearch: true,
          responseSchema: IDENTITY_SCHEMA,
          schemaName: "identity_resolution",
          diagnosticLabel:
            `identity | ${cluster.cluster_id} | ${cluster.items.map((x) => x?.data?.["Организация"] || "").join(" / ")}`,
          maxToolCalls: 2
        })
      )
    );

    for (let i = 0; i < settled.length; i++) {
      const cluster = batch[i];
      const item = settled[i];

      if (item.status === "fulfilled") {
        searchedWebClusters++;
        const rows = applyIdentityResult(cluster, item.value);
        confirmedInnMentions += rows.filter((x) => normalizeInn(x?.data?.["ИНН"])).length;
        resolved.push(...rows);
      } else {
        if (isOpenAIBillingStop(item.reason)) throw item.reason;
        if (isWebBudgetStop(item.reason)) {
          identityBudgetStopped = true;
          resolved.push(...cluster.items);
          skippedWebClusters++;
        } else {
          searchedWebClusters++;
          failedClusters++;
          resolved.push(...cluster.items);
        }
      }
      completed++;
    }

    if (identityBudgetStopped) {
      const remainingStart = offset + batch.length;
      const remaining = webClusters.slice(remainingStart);
      for (const cluster of remaining) {
        resolved.push(...cluster.items);
        skippedWebClusters++;
        completed++;
      }
      console.log("[QUALITY_IDENTITY_BUDGET_STOP] " + JSON.stringify({
        searched_web_clusters: searchedWebClusters,
        skipped_after_budget: remaining.length + 1,
        budget: publicWebBudgetState(client.__webBudget)
      }));
    }

    await onProgress({
      completed,
      total: clusters.length,
      confirmedInnMentions,
      failedClusters,
      skippedWebClusters,
      searchedWebClusters
    });
    if (identityBudgetStopped) break;
  }

  const missingAfterIdentity = resolved.filter(
    (item) => !normalizeInn(item?.data?.["ИНН"])
  ).length;
  console.log("[INN_DEFERRED_TO_FINAL] " + JSON.stringify({
    region,
    mentions: resolved.length,
    inn_present: resolved.length - missingAfterIdentity,
    inn_missing: missingAfterIdentity,
    reason: "mandatory INN lookup now runs only after final qualification"
  }));

  console.log("[IDENTITY_WEB_SAVINGS] " + JSON.stringify({
    total_clusters: clusters.length,
    skipped_web_clusters: clusters.length - searchedWebClusters,
    searched_web_clusters: searchedWebClusters,
    skip_share: clusters.length
      ? Number(((clusters.length - searchedWebClusters) / clusters.length).toFixed(4))
      : 0
  }));

  return {
    candidates: resolved,
    clusters: clusters.length,
    confirmedInnMentions,
    failedClusters,
    skippedWebClusters: clusters.length - searchedWebClusters,
    searchedWebClusters
  };
}


function finalInnLookupContract() {
  return `\n\nФИНАЛЬНАЯ ПОВТОРНАЯ ПРОВЕРКА ИНН — верни ТОЛЬКО JSON по заданной схеме.
На входе только компании, уже прошедшие dedupe и финальную A/B/C qualification.
Для КАЖДОГО id обязательно заново проверь ИНН 10 или 12 цифр, даже если existing_inn уже заполнен.
Ищи только ИНН и юридическую идентичность, необходимую для его проверки. НЕ делай дополнительных web_search ради телефона, директора, email, выручки, холдинга и прочих полей.
Если эти сведения УЖЕ непосредственно видны в источнике, открытом для проверки ИНН, запиши их в observed_facts; иначе верни [].
Каждый observed_fact: field, value, source_url (ОБЯЗАТЕЛЬНО один из source_urls ответа), evidence_excerpt (дословная выдержка с ЭТИМ ИНН и данным значением).
Не приписывай сведения холдинга дочернему юрлицу, не переноси телефоны подрядчика, не угадывай и не интерпретируй единицы выручки; выручка строго целое число рублей.
Сначала используй точное название + город/регион + existing_inn; при необходимости используй один дополнительный сильный идентификатор из переданных evidence: домен, адрес, закупку, судебный/официальный документ.
Если ИНН надёжно не подтверждается — confirmed_inn оставь пустым. Не угадывай. Если надёжно подтверждён другой ИНН того же юрлица, верни подтверждённый корректный ИНН.
source_urls — максимум 2 наиболее сильных URL. note — одно короткое предложение.
legal_status: active/liquidated/ceased/unknown; при отсутствии однозначного источника unknown.
Для liquidated/ceased укажи legal_status_ogrn, legal_status_source_url (официальная ФНС) и legal_status_evidence (точная выдержка с ИНН и прекращением деятельности). Если первичный источник недоступен, статус unknown.
Каждый входной id должен встретиться ровно один раз.`;
}

function compactFinalInnTarget(row) {
  const evidence = row?.__evidence || {};
  return {
    id: checkpointRowId(row),
    organization: String(row?.["Организация"] || "").slice(0, 180),
    city: String(row?.["Город/район"] || "").slice(0, 120),
    existing_inn: normalizeInn(row?.["ИНН"]),
    evidence_urls: (Array.isArray(evidence.source_urls) ? evidence.source_urls : [])
      .map(String).filter(Boolean).slice(0, 3),
    legal_ogrns: identityOgrns(row).slice(0, 2),
    evidence_notes: (Array.isArray(evidence.notes) ? evidence.notes : [])
      .map(String).filter(Boolean)
      .filter((note) => /адрес|огрн|суд|закуп|договор|официал|сайт|домен|реестр|инн/i.test(note))
      .slice(0, 2)
      .map((note) => note.slice(0, 350))
  };
}

function applyFinalInnItems(rowsById, result) {
  let recovered = 0;
  for (const item of Array.isArray(result?.items) ? result.items : []) {
    const row = rowsById.get(String(item?.id || ""));
    if (!row) continue;
    const inn = normalizeInn(item?.confirmed_inn);
    const legalStatus = statusProofFromFinalInn(item, inn);
    const previousInn = normalizeInn(row["ИНН"]);
    row["ИНН"] = inn || "";
    if (inn && inn !== previousInn) recovered++;
    if (inn && Array.isArray(item?.source_urls) && item.source_urls.some((url) => /^https?:\/\//i.test(String(url)))) {
      row.__evidence = { ...(row.__evidence || {}), identity_verification: { inn, method: "final_inn_web", source_urls: item.source_urls } };
    }
    const existing = row.__evidence || {};
    const urls = [
      ...(Array.isArray(existing.source_urls) ? existing.source_urls : []),
      ...(Array.isArray(item?.source_urls) ? item.source_urls : [])
    ].map(String).filter(Boolean);
    const note = String(item?.note || "").trim();
    row.__evidence = {
      ...existing,
      ...(legalStatus ? { legal_status_verification: legalStatus } : {}),
      source_urls: [...new Set(urls)],
      notes: [
        ...(Array.isArray(existing.notes) ? existing.notes : []),
        note ? `Final INN: ${note}` : "",
        inn ? `Подтверждённый ИНН: ${inn}` : ""
      ].filter(Boolean)
    };
    const reused = reuseIdentityObservedFacts(row, item);
    if (reused.length) console.log("[FINAL_INN_REUSED_SOURCE_FACTS] " + JSON.stringify({
      canonical_id: checkpointRowId(row), inn,
      fields: reused.map((fact) => fact.field)
    }));
  }
  return recovered;
}

async function lookupFinalInnBatch({
  client,
  rows,
  region,
  assertNotCancelled,
  label
}) {
  await assertNotCancelled();
  const targets = rows.map(compactFinalInnTarget);
  try {
    const result = await askJson(client, {
      input:
        finalInnLookupContract() +
        `\n\nРЕГИОН: ${region}
КОМПАНИИ:
${JSON.stringify(targets)}`,
      model: TARGETED_SEARCH_MODEL,
      maxOutputTokens: FINAL_INN_MAX_OUTPUT_TOKENS,
      webSearch: true,
      responseSchema: FINAL_INN_SCHEMA,
      schemaName: "final_inn_lookup",
      diagnosticLabel: `final inn | ${label} | size ${rows.length}`,
      maxToolCalls: 2,
      allowJsonRepair: false
    });

    const returned = new Set(
      (Array.isArray(result?.items) ? result.items : [])
        .map((item) => String(item?.id || ""))
        .filter(Boolean)
    );
    const omittedRows = rows.filter((row) => !returned.has(checkpointRowId(row)));
    if (!omittedRows.length) return result;

    console.log("[FINAL_INN_RESPONSE_GAP] " + JSON.stringify({
      label,
      requested: rows.length,
      returned: returned.size,
      omitted: omittedRows.map((row) => checkpointRowId(row))
    }));

    if (rows.length <= 1) {
      return {
        items: [
          ...(result?.items || []),
          {
            id: checkpointRowId(rows[0]),
            confirmed_inn: "",
            source_urls: [],
            note: "ИНН не подтверждён: ответ поиска не содержал результата по этой компании."
          }
        ]
      };
    }

    const recovered = await lookupFinalInnBatch({
      client,
      rows: omittedRows,
      region,
      assertNotCancelled,
      label: `${label}.gap`
    });
    return { items: [...(result?.items || []), ...(recovered?.items || [])] };
  } catch (error) {
    if (isOpenAIBillingStop(error)) throw error;
    if (!isMaxOutputTokensError(error) || rows.length <= 1) throw error;
    const middle = Math.ceil(rows.length / 2);
    const left = await lookupFinalInnBatch({
      client, rows: rows.slice(0, middle), region, assertNotCancelled,
      label: `${label}.1`
    });
    const right = await lookupFinalInnBatch({
      client, rows: rows.slice(middle), region, assertNotCancelled,
      label: `${label}.2`
    });
    return { items: [...(left?.items || []), ...(right?.items || [])] };
  }
}

async function resolveFinalMissingInns({
  client,
  finalResult,
  region,
  assertNotCancelled,
  completedIds = new Set(),
  onBatch = async () => {}
}) {
  const companies = [
    ...(finalResult?.direct_buyers || []),
    ...(finalResult?.intermediaries || []),
    ...(finalResult?.leasing || [])
  ];
  const rowsById = new Map(
    companies.map((row) => [checkpointRowId(row), row]).filter(([id]) => id)
  );

  let evidenceVerified = 0;
  for (const row of companies) {
    const id = checkpointRowId(row);
    if (!id || completedIds.has(id)) continue;
    if (verifiedInnFromEvidence(row, normalizeInn)) {
      completedIds.add(id);
      evidenceVerified++;
    }
  }
  console.log("[FINAL_INN_EVIDENCE_RECHECK] " + JSON.stringify({ evidence_verified: evidenceVerified }));

  const pending = companies.filter((row) => {
    const id = checkpointRowId(row);
    return id && !completedIds.has(id);
  });
  const batches = [];
  for (let offset = 0; offset < pending.length; offset += FINAL_INN_BATCH_SIZE) {
    batches.push(pending.slice(offset, offset + FINAL_INN_BATCH_SIZE));
  }

  let attempted = 0;
  let recovered = 0;
  let retried = 0;
  let completedBatches = 0;
  const concurrency = client?.__webBudget?.kind !== "full" && client?.__webBudget ? 1 : FINAL_INN_CONCURRENCY;

  console.log("[FINAL_INN_PLAN] " + JSON.stringify({
    region,
    final_companies: companies.length,
    already_completed: completedIds.size,
    companies_to_recheck: pending.length,
    batch_size: FINAL_INN_BATCH_SIZE,
    concurrency,
    batches: batches.length
  }));

  await mapWithConcurrency(batches, concurrency, async (batch, batchIndex) => {
    await assertNotCancelled();
    const result = await lookupFinalInnBatch({
      client,
      rows: batch,
      region,
      assertNotCancelled,
      label: `${batchIndex + 1}/${batches.length}`
    });
    attempted += batch.length;
    recovered += applyFinalInnItems(rowsById, result);

    for (const row of batch) {
      const id = checkpointRowId(row);
      if (id) completedIds.add(id);
    }

    completedBatches++;
    const missingProcessed = companies.filter(
      (row) => completedIds.has(checkpointRowId(row)) && !normalizeInn(row?.["ИНН"])
    ).length;
    console.log("[FINAL_INN_BATCH] " + JSON.stringify({
      completed_batches: completedBatches,
      total_batches: batches.length,
      completed_companies: completedIds.size,
      total_companies: companies.length,
      recovered,
      still_missing_in_processed: missingProcessed
    }));
    await onBatch({
      completedIds,
      attempted,
      recovered,
      retried,
      pendingTotal: pending.length
    });
  });

  const retryRows = companies.filter((row) => !normalizeInn(row?.["ИНН"]) && !completedIds.has(`retry:${checkpointRowId(row)}`));
  if (retryRows.length) {
    const retryBatches = [];
    for (let offset = 0; offset < retryRows.length; offset += FINAL_INN_BATCH_SIZE) {
      retryBatches.push(retryRows.slice(offset, offset + FINAL_INN_BATCH_SIZE));
    }
    console.log("[FINAL_INN_RETRY_PLAN] " + JSON.stringify({
      missing_after_first_pass: retryRows.length,
      batches: retryBatches.length,
      concurrency
    }));

    await mapWithConcurrency(retryBatches, concurrency, async (batch, batchIndex) => {
      await assertNotCancelled();
      const result = await lookupFinalInnBatch({
        client,
        rows: batch,
        region,
        assertNotCancelled,
        label: `retry-${batchIndex + 1}/${retryBatches.length}`
      });
      retried += batch.length;
      recovered += applyFinalInnItems(rowsById, result);
      for (const row of batch) completedIds.add(`retry:${checkpointRowId(row)}`);
      await onBatch({
        completedIds,
        attempted,
        recovered,
        retried,
        pendingTotal: pending.length
      });
    });
  }

  for (const row of companies) mergeResearchComment(row);
  const finalMissing = companies.filter((row) => !normalizeInn(row?.["ИНН"])).length;
  console.log("[FINAL_INN_SUMMARY] " + JSON.stringify({
    region,
    final_companies: companies.length,
    attempted,
    retried,
    recovered,
    inn_present: companies.length - finalMissing,
    inn_missing: finalMissing
  }));

  return { completedIds, attempted, retried, recovered, missing: finalMissing };
}

function duplicateInnConflictGroups(finalResult) {
  const groups = new Map();
  for (const row of allResearchRows(finalResult)) {
    const inn = normalizeInn(row?.["ИНН"]);
    if (!inn) continue;
    if (!groups.has(inn)) groups.set(inn, []);
    groups.get(inn).push(row);
  }
  return [...groups.entries()]
    .filter(([, rows]) => rows.length > 1)
    .map(([inn, rows]) => ({ inn, rows }));
}

function clearUnresolvedInnConflicts(finalResult) {
  const groups = duplicateInnConflictGroups(finalResult);
  let clearedRows = 0;
  for (const group of groups) {
    const organizations = [...new Set(group.rows.map((row) =>
      String(row["Организация"] || "").trim()).filter(Boolean)
    )];
    const competingOgrns = [...new Set(group.rows.flatMap((row) => identityOgrns(row)))];
    for (const row of group.rows) {
      // Clear only the field asserting an unresolved identity. Do not erase
      // supporting notes, OGRN candidates or the underlying legal entity.
      row["ИНН"] = "";
      const evidence = row.__evidence || { source_urls: [], notes: [] };
      const conflicts = Array.isArray(evidence.legal_identity_conflicts)
        ? evidence.legal_identity_conflicts : [];
      row.__evidence = {
        ...evidence,
        source_urls: Array.isArray(evidence.source_urls) ? evidence.source_urls : [],
        legal_identity_conflicts: [
          ...conflicts,
          {
            contested_inn: group.inn,
            status: "manual_review_required",
            conflicting_organizations: organizations,
            competing_ogrns: competingOgrns,
            own_ogrns: identityOgrns(row),
            recorded_at_stage: "final_inn_conflict"
          }
        ],
        notes: [
          ...(Array.isArray(evidence.notes) ? evidence.notes : []),
          `Final INN conflict: ИНН ${group.inn} встретился у несовместимых сущностей и очищен до однозначного подтверждения.`
        ]
      };
      mergeResearchComment(row);
      clearedRows++;
    }
  }
  return { groups: groups.length, clearedRows };
}

function deterministicRequalification(records) {
  const decisions = new Map();
  for (const record of records) {
    const decision = deterministicQualificationDecision(record);
    decisions.set(record.id, {
      decision: decision.decision,
      grade: decision.grade,
      reason: decision.reason,
      aEvidence: decision.aEvidence || "",
      aRule: decision.aRule || ""
    });
  }
  return applyFinalQualification(records, decisions);
}

function postInnDedupe(finalResult, region, diagnostics = null) {
  const records = deterministicGlobalDedupe(
    makeQaRecords(finalResult),
    diagnostics,
    region
  );
  const qualified = deterministicRequalification(records);
  qualified.result.qualification_review = mergedQualificationReviews(
    Array.isArray(finalResult?.qualification_review) ? finalResult.qualification_review : [],
    qualified.result.qualification_review
  );
  return { records, qualified };
}

function enforceFinalInnRequirement(finalResult) {
  const missing = [];
  for (const sheet of ["direct_buyers", "intermediaries", "leasing"]) {
    for (const row of finalResult?.[sheet] || []) {
      if (!normalizeInn(row?.["ИНН"])) {
        missing.push({
          sheet,
          id: checkpointRowId(row),
          organization: String(row?.["Организация"] || ""),
          city: String(row?.["Город/район"] || "")
        });
      }
    }
  }
  console.log("[FINAL_INN_ENFORCEMENT] " + JSON.stringify({
    kept_without_confirmed_inn: missing.length,
    companies: missing
  }));
  // По синхронизированным инструкциям отсутствие подтверждённого ИНН
  // не является причиной удалять релевантную компанию.
  return [];
}
function canonicalizeCandidates(candidates, region = "") {
  const parent = candidates.map((_, i) => i);
  const rank = candidates.map(() => 0);

  const find = (x) => {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  };

  const union = (a, b) => {
    let ra = find(a);
    let rb = find(b);
    if (ra === rb) return;
    if (rank[ra] < rank[rb]) [ra, rb] = [rb, ra];
    parent[rb] = ra;
    if (rank[ra] === rank[rb]) rank[ra]++;
  };

  const innOwners = new Map();

  for (let i = 0; i < candidates.length; i++) {
    const row = candidates[i]?.data || {};
    const inn = normalizeInn(row["ИНН"]);
    if (inn) {
      const owners = innOwners.get(inn) || [];
      const name = String(row["Организация"] || "").trim();
      let compatibleOwner = null;

      for (const ownerIndex of owners) {
        const ownerName = String(candidates[ownerIndex]?.data?.["Организация"] || "").trim();
        if (organizationNamesCompatible(name, ownerName, region)) {
          compatibleOwner = ownerIndex;
          break;
        }
      }

      if (compatibleOwner !== null) {
        union(i, compatibleOwner);
      } else {
        if (owners.length) {
          console.log("[CANONICAL_INN_CONFLICT] " + JSON.stringify({
            inn,
            organization: name,
            existing_organizations: owners.map((ownerIndex) =>
              String(candidates[ownerIndex]?.data?.["Организация"] || "").trim()
            )
          }));
        }
        owners.push(i);
        innOwners.set(inn, owners);
      }
    }

    // Без подтвержденного ИНН строки не объединяем программно только по названию/городу.
    // Одинаковый ИНН тоже не схлопывает явно несовместимые названия на этом раннем слое.
  }

  const groups = new Map();
  for (let i = 0; i < candidates.length; i++) {
    const root = find(i);
    if (!groups.has(root)) groups.set(root, []);
    groups.get(root).push(candidates[i]);
  }

  return [...groups.values()].map((evidence, index) => ({
    canonical_id: `k${String(index + 1).padStart(6, "0")}`,
    candidate_ids: evidence.map((x) => x.candidate_id),
    source_steps: [...new Set(evidence.map((x) => x.source_step))],
    source_sheets: [...new Set(evidence.map((x) => x.source_sheet))],
    evidence
  }));
}

function mergedEvidenceFromCanonical(canonical) {
  const sourceUrls = [];
  const notes = [];
  const facts = [];
  let identityVerification = null;
  for (const evidenceItem of canonical?.evidence || []) {
    const ev = evidenceItem?.data?.__evidence || {};
    for (const fact of Array.isArray(ev.facts) ? ev.facts : []) facts.push(fact);
    if (!identityVerification && ev.identity_verification?.inn) identityVerification = ev.identity_verification;
    for (const url of Array.isArray(ev.source_urls) ? ev.source_urls : []) {
      if (url) sourceUrls.push(String(url));
    }
    for (const note of Array.isArray(ev.notes) ? ev.notes : []) {
      if (note) notes.push(String(note));
    }
  }
  return {
    source_urls: [...new Set(sourceUrls)],
    notes: [...new Set(notes)],
    facts: distinctSourceFacts({ __evidence: { facts } }),
    ...(identityVerification ? { identity_verification: identityVerification } : {})
  };
}

function preferredSheetForCanonical(canonical) {
  const sourceSheets = new Set(
    (Array.isArray(canonical?.source_sheets) ? canonical.source_sheets : [])
      .map((value) => String(value || ""))
  );
  const evidenceRows = canonical?.evidence?.map((item) => item?.data || {}) || [];
  const text = evidenceRows
    .flatMap((row) => [
      row?.["Организация"],
      row?.["Техника/сегмент"],
      row?.["Основание"],
      ...(Array.isArray(row?.__evidence?.notes) ? row.__evidence.notes : [])
    ])
    .map((value) => String(value || "").toLowerCase().replace(/ё/g, "е"))
    .join("\n");

  const lessee =
    /лизингополучател|получател.{0,20}лизинг|предмет.{0,30}лизинг.{0,80}(эксплуат|использ|парк)|эксплуат.{0,80}лизинг/.test(text);
  const financier =
    /лизингодател|лизингов.{0,25}(компан|организац|финанс|услуг)|финанс.{0,25}лизинг|предоставл.{0,30}лизинг/.test(text);
  const intermediary =
    /(дилер|сервис|ремонт|шиномонтаж|телематик|гидравлик|запчаст|торгов.{0,20}(дом|центр)|продаж.{0,30}(прицеп|полуприцеп))/.test(text);
  const directOperation =
    /(перевозчик|грузоперевоз|собственн.{0,30}парк|эксплуат.{0,50}(тягач|прицеп|полуприцеп|самосвал)|производств|добыч|выращив|элеватор|карьер|лесозаготов|деревообработ|отход|металлолом|зерн|щеб|песок|пгс)/.test(text);

  if (financier && !lessee) return "leasing";
  if (
    sourceSheets.has("Прямые покупатели") ||
    sourceSheets.has("direct_buyers") ||
    lessee ||
    (directOperation && !intermediary)
  ) {
    return "direct_buyers";
  }
  if (
    sourceSheets.has("Посредники") ||
    sourceSheets.has("intermediaries") ||
    intermediary
  ) {
    return "intermediaries";
  }
  if (sourceSheets.has("Лизинг") || sourceSheets.has("leasing")) return "leasing";
  return "direct_buyers";
}

function baselineRowFromCanonical(canonical) {
  const row = {};
  const evidenceRows = canonical?.evidence?.map((x) => x.data || {}) || [];

  for (const col of COLS) {
    const values = [...new Set(
      evidenceRows
        .map((item) => String(item?.[col] ?? "").trim())
        .filter(Boolean)
    )];

    if (col === "Телефон") row[col] = values.join("; ");
    else if (col === "Основание" || col === "Техника/сегмент") row[col] = values.join(" | ");
    else row[col] = values[0] || "";
  }

  row.__evidence = mergedEvidenceFromCanonical(canonical);
  row.__canonical_id = canonical.canonical_id;
  row.__decision = "review";
  row.__decision_reason = "Восстановлено из исходных свидетельств: пакетный ответ пропустил canonical-компанию.";
  row.__comment = [
    "Сайт/источник: не подтверждено",
    `ИНН: ${row["ИНН"] || "не подтверждено"}`,
    "Деятельность: требуется финальная проверка",
    `Холдинг/УК/группа: ${row["Управляющая компания"] || "не подтверждено"}`,
    "Email: не найден"
  ].join("\n");
  return row;
}

function ensureBatchCoverage(batch, batchResult) {
  const output = {
    direct_buyers: [],
    intermediaries: [],
    leasing: []
  };
  const seen = new Set();
  const byCanonicalId = new Map(batch.map((item) => [item.canonical_id, item]));

  for (const sheet of ["direct_buyers", "intermediaries", "leasing"]) {
    for (const row of batchResult?.[sheet] || []) {
      const id = String(row?.__canonical_id || "");
      if (!id || !byCanonicalId.has(id) || seen.has(id)) continue;
      seen.add(id);
      const canonical = byCanonicalId.get(id);
      output[sheet].push({
        ...row,
        __evidence: mergedEvidenceFromCanonical(canonical)
      });
    }
  }

  for (const canonical of batch) {
    if (seen.has(canonical.canonical_id)) continue;

    const fallback = baselineRowFromCanonical(canonical);
    const preferred = preferredSheetForCanonical(canonical);
    output[preferred].push(fallback);
  }

  return output;
}

function applyFinalBatchDelta(batch, delta) {
  const byId = new Map((delta?.items || []).map((item) => [String(item?.canonical_id || ""), item]));
  const output = { direct_buyers: [], intermediaries: [], leasing: [] };
  const allowedFields = new Set([...COLS, "__comment"]);

  for (const canonical of batch) {
    const item = byId.get(String(canonical.canonical_id || "")) || null;
    const row = baselineRowFromCanonical(canonical);
    if (item) {
      for (const change of Array.isArray(item.changes) ? item.changes : []) {
        const field = String(change?.field || "");
        if (allowedFields.has(field)) row[field] = String(change?.value ?? "");
      }
      row.__decision = item.decision === "keep" ? "keep" : "review";
      row.__decision_reason = String(item.decision_reason || "");
    }
    row.__evidence = mergedEvidenceFromCanonical(canonical);
    const requestedSheet = String(item?.sheet || "");
    const preferred = ["direct_buyers", "intermediaries", "leasing"].includes(requestedSheet)
      ? requestedSheet
      : preferredSheetForCanonical(canonical);
    output[preferred].push(row);
  }
  return output;
}

function isMaxOutputTokensError(error) {
  return /max_output_tokens|incomplete; reason: max_output_tokens/i.test(
    String(error?.message || error || "")
  );
}

async function processFinalBatchResilient({
  client,
  prompt,
  region,
  batch,
  assertNotCancelled,
  label,
  depth = 0
}) {
  await assertNotCancelled();
  try {
    const delta = await askJson(client, {
      input:
        prompt +
        finalBatchContract() +
        `\n\nРЕГИОН: ${region}
Это пакет CANONICAL-компаний после discovery 1–9 и identity-resolution.
Все подтверждённые ИНН уже перенесены в записи. Не ищи новые данные и не переписывай evidence.
Верни компактный delta для каждого canonical_id.

ПАКЕТ CANONICAL-КОМПАНИЙ JSON:
${JSON.stringify(batch)}`,
      model: FINAL_BATCH_MODEL,
      maxOutputTokens: FINAL_BATCH_MAX_OUTPUT_TOKENS,
      webSearch: false,
      responseSchema: FINAL_BATCH_DELTA_SCHEMA,
      schemaName: "final_batch_delta",
      diagnosticLabel: `final batch | ${label} | size ${batch.length}`
    });
    return applyFinalBatchDelta(batch, delta);
  } catch (error) {
    if (!isMaxOutputTokensError(error)) throw error;
    if (batch.length <= FINAL_BATCH_MIN_SPLIT_SIZE) {
      console.error("[FINAL_BATCH_FALLBACK] " + JSON.stringify({
        label,
        size: batch.length,
        depth,
        reason: "max_output_tokens",
        action: "deterministic_baseline"
      }));
      return applyFinalBatchDelta(batch, { items: [] });
    }

    const middle = Math.ceil(batch.length / 2);
    const left = batch.slice(0, middle);
    const right = batch.slice(middle);
    console.log("[FINAL_BATCH_SPLIT] " + JSON.stringify({
      label,
      size: batch.length,
      depth,
      reason: "max_output_tokens",
      split: [left.length, right.length]
    }));
    const leftResult = await processFinalBatchResilient({
      client, prompt, region, batch: left, assertNotCancelled,
      label: `${label}.1`, depth: depth + 1
    });
    const rightResult = await processFinalBatchResilient({
      client, prompt, region, batch: right, assertNotCancelled,
      label: `${label}.2`, depth: depth + 1
    });
    return {
      direct_buyers: [...leftResult.direct_buyers, ...rightResult.direct_buyers],
      intermediaries: [...leftResult.intermediaries, ...rightResult.intermediaries],
      leasing: [...leftResult.leasing, ...rightResult.leasing]
    };
  }
}

function prefilterCandidatesForIdentity(candidates, region = "") {
  const canonicalPool = canonicalizeCandidates(candidates, region);
  const staged = { direct_buyers: [], intermediaries: [], leasing: [] };

  for (const canonical of canonicalPool) {
    const row = baselineRowFromCanonical(canonical);
    const sheet = preferredSheetForCanonical(canonical);
    staged[sheet].push(row);
  }

  const deduped = deterministicGlobalDedupe(makeQaRecords(staged), null, region);
  const keepNames = new Set();
  const keepInns = new Set();
  const reviewNames = new Set();
  const reviewInns = new Set();
  const decisions = [];
  let included = 0;
  let excluded = 0;
  let reviewing = 0;

  for (const record of deduped) {
    const decision = deterministicQualificationDecision(record);
    const row = record.row || {};
    const name = normalizeOrgKey(row["Организация"]);
    const inn = normalizeInn(row["ИНН"]);
    const notes = Array.isArray(row.__evidence?.notes) ? row.__evidence.notes : [];
    const allText = [row["Техника/сегмент"], row["Основание"], ...notes].join(" ").toLowerCase().replace(/ё/g, "е");
    const commercialSignal = /(полуприцеп|прицеп|тонар|schmitz|kogel|krone|wielton|grunwald|седельн.{0,20}тягач|автопоезд|зерновоз|ломовоз|щеповоз|лесовоз|самосвал|пгс|щебен|песок|перевозк.{0,40}(зерн|лес|лом|отход)|ремонт.{0,60}(грузов|прицеп)|грузов.{0,40}перевоз)/i.test(allText);
    const discoveryStrong = /^\\s*[ab]\\s*[—–-]/i.test(String(row["Основание"] || "")) ||
      /^\\s*[ab]\\s*[—–-]/i.test(String(row["Техника/сегмент"] || ""));
    const concreteReviewEvent =
      /(закупк|тендер|контракт|договор|приобрет|купил|куплен|лизинг|на балансе|в собственности|собственн.{0,30}парк|автопарк|эксплуат|водител.{0,40}(прицеп|полуприцеп)|заказчик.{0,80}(прицеп|полуприцеп)|клиент.{0,80}(прицеп|полуприцеп)|выполн.{0,40}ремонт|акт выполненн|заказ.наряд)/i.test(allText);
    const negativeOnly = /(ликвидирован|прекратил деятельность|не относится к региону)/.test(allText) &&
      !concreteReviewEvent;
    // REVIEW is deliberately narrower than a generic trailer/service mention:
    // retain discovery A/B or a concrete commercial/operational event, but do
    // not send every directory/service listing through the expensive final batch.
    const reviewSignal = commercialSignal && (discoveryStrong || concreteReviewEvent);
    const status = decision.grade ? "KEEP" : reviewSignal && !negativeOnly ? "REVIEW" : "EXCLUDE";
    if (status === "KEEP") {
      included++;
      if (name) keepNames.add(name);
      if (inn) keepInns.add(inn);
    } else if (status === "REVIEW") {
      reviewing++;
      if (name) reviewNames.add(name);
      if (inn) reviewInns.add(inn);
    } else excluded++;

    decisions.push({
      canonical_id: record.canonical_id || "",
      organization: String(row["Организация"] || ""),
      city: String(row["Город/район"] || ""),
      status,
      reason: decision.reason,
      signals: decision.signals,
      source_urls: (row.__evidence?.source_urls || []).slice(0, 8),
      evidence_notes: notes.slice(0, 8),
      initial_inn: String(row["ИНН"] || "")
    });
  }

  const matches = (candidate, names, inns) => {
    const row = candidate?.data || {};
    const name = normalizeOrgKey(row["Организация"]);
    const inn = normalizeInn(row["ИНН"]);
    return (name && names.has(name)) || (inn && inns.has(inn));
  };
  const filtered = candidates.filter((candidate) => matches(candidate, keepNames, keepInns));
  const reviewCandidates = candidates.filter((candidate) =>
    !matches(candidate, keepNames, keepInns) && matches(candidate, reviewNames, reviewInns)
  );
  const excludedCandidates = candidates.filter((candidate) =>
    !matches(candidate, keepNames, keepInns) && !matches(candidate, reviewNames, reviewInns)
  );

  const summary = {
    input_mentions: candidates.length,
    local_canonical: canonicalPool.length,
    local_after_dedupe: deduped.length,
    qualified_before_identity: included,
    review_before_identity: reviewing,
    excluded_before_identity: excluded,
    identity_mentions: filtered.length,
    review_mentions: reviewCandidates.length,
    excluded_mentions: excludedCandidates.length,
    saved_mentions: candidates.length - filtered.length
  };
  console.log("[PRE_IDENTITY_FILTER] " + JSON.stringify(summary));
  console.log("[PRE_IDENTITY_AUDIT] " + JSON.stringify({
    region, summary, decisions,
    review_candidates: reviewCandidates.map((c) => ({
      candidate_id: c.candidate_id, source_step: c.source_step,
      source_sheet: c.source_sheet, data: c.data
    }))
  }));

  return {
    candidates: filtered,
    reviewCandidates,
    excludedCandidates,
    decisions,
    inputMentions: candidates.length,
    localCanonical: canonicalPool.length,
    localAfterDedupe: deduped.length,
    qualified: included,
    review: reviewing,
    excluded,
    savedMentions: candidates.length - filtered.length
  };
}

// REVIEW remains in the evidence stream and is evaluated by the same final QA.
// Its provisional status never counts as a confirmed A/B/C grade.
function appendReviewCandidates(resolved, reviewCandidates, region, label) {
  if (!reviewCandidates?.length) return resolved;
  const existing = new Set(resolved.map((c) => c.candidate_id));
  const added = reviewCandidates.filter((c) => !existing.has(c.candidate_id));
  for (const item of added) {
    const evidence = item.data?.__evidence || {};
    item.data.__evidence = {
      ...evidence,
      source_urls: Array.isArray(evidence.source_urls) ? evidence.source_urls : [],
      notes: Array.isArray(evidence.notes) ? evidence.notes : []
    };
    item.data.__pre_identity_status = "REVIEW";
  }
  console.log("[PRE_IDENTITY_REVIEW_RETAINED] " + JSON.stringify({
    label, region, added_mentions: added.length,
    no_extra_identity_web_search: true
  }));
  return [...resolved, ...added];
}

function makeQaRecords(result) {
  const records = [];
  const groups = ["direct_buyers", "intermediaries", "leasing"];
  for (const sheet of groups) {
    for (const row of result[sheet] || []) {
      records.push({
        id: `q${String(records.length + 1).padStart(6, "0")}`,
        canonical_id: row?.__canonical_id || "",
        sheet,
        row
      });
    }
  }
  return records;
}

function applyFinalQa(records, qa) {
  const allowedSheets = new Set(["direct_buyers", "intermediaries", "leasing"]);
  const allowedFields = new Set([...COLS, "__comment", "__decision", "__decision_reason", "__evidence", "__final_grade"]);
  const removeIds = new Set(Array.isArray(qa?.remove_ids) ? qa.remove_ids.map(String) : []);
  const moves = new Map();

  for (const item of Array.isArray(qa?.moves) ? qa.moves : []) {
    const id = String(item?.id || "");
    const sheet = String(item?.sheet || "");
    if (id && allowedSheets.has(sheet)) moves.set(id, sheet);
  }

  const patches = new Map();
  for (const item of Array.isArray(qa?.patches) ? qa.patches : []) {
    const id = String(item?.id || "");
    if (!id) continue;
    const filtered = {};
    if (item?.fields && typeof item.fields === "object") {
      for (const [key, value] of Object.entries(item.fields)) {
        if (allowedFields.has(key)) filtered[key] = value ?? "";
      }
    }
    for (const change of Array.isArray(item?.changes) ? item.changes : []) {
      const key = String(change?.field || "");
      if (allowedFields.has(key)) filtered[key] = change?.value ?? "";
    }
    if (Object.keys(filtered).length) patches.set(id, filtered);
  }

  const byId = new Map(records.map((record) => [record.id, record]));
  for (const removedId of removeIds) {
    const removed = byId.get(removedId);
    if (!removed) continue;
    const removedInn = normalizeInn(removed?.row?.["ИНН"]);
    const removedName = String(removed?.row?.["Организация"] || "");
    const target = records.find((record) => {
      if (removeIds.has(record.id) || record.id === removedId) return false;
      const targetInn = normalizeInn(record?.row?.["ИНН"]);
      if (removedInn && targetInn) return removedInn === targetInn;
      return organizationNamesCompatible(
        removedName,
        String(record?.row?.["Организация"] || "")
      );
    });
    if (!target) continue;
    const merged = mergeQaRecordRows([target, removed]);
    target.row = merged.row;
  }

  const result = {
    direct_buyers: [],
    intermediaries: [],
    leasing: [],
    statistics: []
  };

  for (const record of records) {
    if (removeIds.has(record.id)) continue;
    const row = { ...record.row, ...(patches.get(record.id) || {}) };
    const sheet = moves.get(record.id) || record.sheet;
    if (allowedSheets.has(sheet)) result[sheet].push(row);
  }

  return result;
}

function mergeQaRecordRows(records) {
  const first = records[0];
  const mergedRow = { ...(first?.row || {}) };
  const urls = [];
  const notes = [];
  const facts = [];
  const legalIdentityConflicts = [];
  const legalIdentityMerges = [];
  let identityVerification = null;

  for (const record of records) {
    const row = record?.row || {};
    for (const col of COLS) {
      const current = String(mergedRow[col] || "").trim();
      const incoming = String(row[col] || "").trim();
      if (!current && incoming) mergedRow[col] = incoming;
    }

    const segments = [mergedRow["Техника/сегмент"], row["Техника/сегмент"]]
      .flatMap((value) => String(value || "").split("|"))
      .map((value) => value.trim())
      .filter(Boolean);
    if (segments.length) mergedRow["Техника/сегмент"] = [...new Set(segments)].join(" | ");

    const evidence = row.__evidence || {};
    for (const fact of Array.isArray(evidence.facts) ? evidence.facts : []) facts.push(fact);
    for (const conflict of Array.isArray(evidence.legal_identity_conflicts) ? evidence.legal_identity_conflicts : []) legalIdentityConflicts.push(conflict);
    for (const merge of Array.isArray(evidence.legal_identity_merges) ? evidence.legal_identity_merges : []) legalIdentityMerges.push(merge);
    if (!identityVerification && evidence.identity_verification?.inn) identityVerification = evidence.identity_verification;
    for (const url of Array.isArray(evidence.source_urls) ? evidence.source_urls : []) {
      if (url) urls.push(String(url));
    }
    for (const note of Array.isArray(evidence.notes) ? evidence.notes : []) {
      if (note) notes.push(String(note));
    }
  }

  const mergedInns = [...new Set(records.map((record) =>
    normalizeInn(record?.row?.["ИНН"])).filter(Boolean))];
  if (mergedInns.length === 1 && records.length > 1) {
    const anchor = records[0];
    for (const record of records.slice(1)) {
      const decision = confirmedInnAliasDecision(anchor, record, mergedInns[0],
        (a, b) => organizationNamesCompatible(a, b));
      if (!decision.merge) continue;
      legalIdentityMerges.push({
        confirmed_inn: mergedInns[0],
        survivor_name: String(anchor?.row?.["Организация"] || ""),
        merged_name: String(record?.row?.["Организация"] || ""),
        decision: decision.reason,
        ogrns: [...new Set([...decision.ogrnsA, ...decision.ogrnsB])],
        identity_source_urls: [...new Set([
          ...(anchor?.row?.__evidence?.identity_verification?.source_urls || []),
          ...(record?.row?.__evidence?.identity_verification?.source_urls || [])
        ])].slice(0, 4)
      });
    }
  }
  mergedRow.__evidence = {
    source_urls: [...new Set(urls)],
    notes: [...new Set(notes)],
    facts: distinctSourceFacts({ __evidence: { facts } }),
    ...(legalIdentityConflicts.length ? { legal_identity_conflicts: legalIdentityConflicts } : {}),
    ...(legalIdentityMerges.length ? { legal_identity_merges: legalIdentityMerges } : {}),
    ...(identityVerification ? { identity_verification: identityVerification } : {})
  };

  return {
    ...first,
    row: mergedRow
  };
}

const ORG_IDENTITY_STOP_TOKENS = new Set([
  // Universal legal forms.
  "ооо", "ао", "пао", "оао", "зао", "ип", "спк", "схпк", "согбу",
  "фгуп", "муп", "гуп", "нко",
  // Universal structural / geographic descriptors.
  "группа", "групп", "компания", "компаний", "филиал", "проект",
  "область", "области", "край", "республика", "район", "округ",
  "автономная", "автономный", "региональный", "город"
]);

function regionIdentityTokens(region) {
  return normalizePlaceKey(region)
    .split(/\s+/)
    .filter((token) => token.length >= 3 && !ORG_IDENTITY_STOP_TOKENS.has(token));
}

function isRegionIdentityToken(token, region) {
  const value = String(token || "").toLowerCase();
  for (const regional of regionIdentityTokens(region)) {
    if (value === regional) return true;
    if (regional.length >= 6) {
      const prefix = regional.slice(0, Math.min(7, regional.length));
      if (value.length >= prefix.length && value.startsWith(prefix)) return true;
    }
  }
  return false;
}

function organizationIdentityTokens(value, region = "") {
  return normalizeOrgKey(value)
    .split(/\s+/)
    .filter((token) =>
      token.length >= 2 &&
      !ORG_IDENTITY_STOP_TOKENS.has(token) &&
      !isRegionIdentityToken(token, region)
    );
}

function organizationNamesCompatible(a, b, region = "") {
  const left = normalizeOrgKey(a);
  const right = normalizeOrgKey(b);
  if (!left || !right) return false;
  if (left === right) return true;

  const lt = organizationIdentityTokens(a, region);
  const rt = organizationIdentityTokens(b, region);
  if (!lt.length || !rt.length) return false;

  const ls = new Set(lt);
  const rs = new Set(rt);
  const shared = [...ls].filter((token) => rs.has(token));
  const minSize = Math.min(ls.size, rs.size);

  // Alias matching must never be decided by one shared token.
  // Exact normalized names were handled above; all fuzzy name matches now
  // require at least two shared non-structural tokens with strong overlap.
  // Industry vocabulary is intentionally not hard-coded here.
  if (
    shared.length >= 2 &&
    minSize >= 2 &&
    shared.length / minSize >= 0.67
  ) return true;

  return false;
}

function organizationAcronymCandidates(value, region = "") {
  const normalized = normalizeOrgKey(value);
  const geoStop = new Set([
    "ооо", "ао", "пао", "оао", "зао", "ип", "спк", "схпк", "согбу",
    "область", "области", "край", "республика", "район", "района", "округ", "город"
  ]);
  const tokens = normalized
    .split(/\s+/)
    .filter((token) =>
      token.length >= 2 &&
      !geoStop.has(token) &&
      !isRegionIdentityToken(token, region)
    );

  const acronyms = new Set();

  // Only derive a real initials-based acronym from a multi-word name.
  // Treating every short token ("агро", "транс", "центр", "строй", etc.)
  // as an acronym caused unrelated companies to collapse into one group.
  if (tokens.length >= 2 && tokens.length <= 5) {
    const initials = tokens.map((token) => token[0]).join("");
    if (initials.length >= 2 && initials.length <= 5) acronyms.add(initials);
  }

  return acronyms;
}

function recordsShareEvidenceDomain(a, b) {
  const left = evidenceDomains(a?.row || {});
  const right = evidenceDomains(b?.row || {});
  for (const domain of left) {
    if (right.has(domain)) return true;
  }
  return false;
}

function organizationRoleSignature(value) {
  const normalized = normalizeOrgKey(value);
  return {
    management:
      /(^|\s)ук(\s|$)/.test(normalized) ||
      normalized.includes("управляющая компания"),
    project: /(^|\s)проект(\s|$)/.test(normalized),
    group:
      /(^|\s)гк(\s|$)/.test(normalized) ||
      /(^|\s)группа(\s|$)/.test(normalized) ||
      /(^|\s)холдинг(\s|$)/.test(normalized),
    branch:
      /(^|\s)филиал(\s|$)/.test(normalized) ||
      /(^|\s)подразделени/.test(normalized),
    brand:
      /(^|\s)бренд(\s|$)/.test(normalized) ||
      normalized.includes("торговая марка")
  };
}

function materiallyDifferentRoleSignatures(a, b) {
  const left = organizationRoleSignature(a);
  const right = organizationRoleSignature(b);
  return Object.keys(left).some((key) => Boolean(left[key]) !== Boolean(right[key]));
}

function compoundOrganizationSegments(value) {
  return String(value || "")
    .split(/[\/|;]/)
    .map((part) => part.trim())
    .filter(Boolean);
}

function safeAliasIdentityCompatible(a, b, region = "") {
  const aInn = normalizeInn(a?.row?.["ИНН"]);
  const bInn = normalizeInn(b?.row?.["ИНН"]);

  // Alias pass must never override the stricter INN pass.
  // If both records already have confirmed INNs, they were either merged safely
  // in splitInnGroupByCompatibleIdentity or intentionally kept apart.
  if (aInn && bInn) return false;

  const aName = String(a?.row?.["Организация"] || "").trim();
  const bName = String(b?.row?.["Организация"] || "").trim();
  if (!aName || !bName) return false;
  if (legalEvidenceConflict(a, b)) return false;
  if (legalNameKey(aName) === legalNameKey(bName)) return true;

  // Compound fields are handled structurally rather than by a blanket slash rule.
  // If a row names several materially different variants, every non-trivial
  // segment must independently agree with the other organization's name.
  if (!aInn || !bInn) {
    for (const [compound, other] of [[aName, bName], [bName, aName]]) {
      const segments = compoundOrganizationSegments(compound);
      if (segments.length > 1) {
        const allCompatible = segments.every((segment) =>
          organizationNamesCompatible(segment, other, region) ||
          normalizeOrgKey(segment) === normalizeOrgKey(other)
        );
        if (!allCompatible) return false;
      }
    }
  }

  // Structural role changes (management company, project, group, branch, brand)
  // are evidence of a relationship, not proof of one legal entity.
  if (!aInn && !bInn && materiallyDifferentRoleSignatures(aName, bName)) {
    return false;
  }

  if (organizationNamesCompatible(aName, bName, region)) return true;

  // Long official name vs stable acronym, e.g. Regional Leasing Center / RLC.
  const aTokens = new Set(normalizeOrgKey(aName).split(/\s+/).filter(Boolean));
  const bTokens = new Set(normalizeOrgKey(bName).split(/\s+/).filter(Boolean));
  const aAcronyms = organizationAcronymCandidates(aName, region);
  const bAcronyms = organizationAcronymCandidates(bName, region);
  for (const acronym of aAcronyms) {
    if (bTokens.has(acronym) && acronym.length >= 3) return true;
  }
  for (const acronym of bAcronyms) {
    if (aTokens.has(acronym) && acronym.length >= 3) return true;
  }

  // Evidence-domain overlap is intentionally NOT enough to merge legal entities.
  // Many unrelated companies share marketplace, registry or industry domains.
  // If names are not compatible above, keep the records separate.

  return false;
}

function conservativeAliasDedupe(records, diagnostics = null, region = "") {
  const consumed = new Set();
  const merged = [];
  let aliasMerged = 0;

  // Greedy representative matching avoids transitive bridge merges:
  // A~B and B~C no longer implies A~C.
  for (let i = 0; i < records.length; i++) {
    if (consumed.has(i)) continue;

    const group = [records[i]];
    consumed.add(i);

    for (let j = i + 1; j < records.length; j++) {
      if (consumed.has(j)) continue;

      // Every candidate must be directly compatible with the representative.
      if (!safeAliasIdentityCompatible(records[i], records[j], region)) continue;

      // If the candidate has an INN and the representative does not, do not let
      // that candidate turn the group into a bridge for other legal entities.
      group.push(records[j]);
      consumed.add(j);
    }

    if (group.length === 1) {
      merged.push(group[0]);
      continue;
    }

    const inns = [...new Set(
      group.map((record) => normalizeInn(record?.row?.["ИНН"])).filter(Boolean)
    )];

    if (inns.length > 1) {
      console.log("[DEDUPE_ALIAS_CONFLICT] " + JSON.stringify({
        inns,
        organizations: group.map((record) =>
          String(record?.row?.["Организация"] || "").trim()
        )
      }));
      merged.push(...group);
      continue;
    }

    aliasMerged += group.length - 1;
    recordDedupeMerge(diagnostics, "alias", group, inns[0] || "");
    console.log("[DEDUPE_ALIAS_MERGE] " + JSON.stringify({
      inn: inns[0] || "",
      organizations: group.map((record) =>
        String(record?.row?.["Организация"] || "").trim()
      )
    }));
    merged.push(mergeQaRecordRows(group));
  }

  return { records: merged, aliasMerged };
}

function splitInnGroupByCompatibleIdentity(records, inn, region = "") {
  const groups = [];
  const aliasReasons = new Map();
  const conflictReasons = new Map();

  for (const record of records) {
    let target = null;

    for (const group of groups) {
      // Pairwise compatibility avoids a transitive "bridge" merge of
      // unrelated companies with one repeated or hallucinated INN.
      const decisions = group.map((existing) =>
        confirmedInnAliasDecision(record, existing, inn,
          (a, b) => organizationNamesCompatible(a, b, region))
      );
      if (decisions.every((item) => item.merge)) {
        target = group;
        for (const item of decisions) {
          aliasReasons.set(item.reason, (aliasReasons.get(item.reason) || 0) + 1);
        }
        break;
      }
      for (const item of decisions.filter((decision) => !decision.merge)) {
        conflictReasons.set(item.reason, (conflictReasons.get(item.reason) || 0) + 1);
      }
    }
    if (target) target.push(record);
    else groups.push([record]);
  }

  if (records.length > 1 && (groups.length > 1 || groups.some((g) => g.length > 1))) {
    console.log("[DEDUPE_INN_ALIAS_DECISIONS] " + JSON.stringify({
      inn,
      before: records.length,
      after: groups.length,
      accepted: Object.fromEntries(aliasReasons),
      rejected: Object.fromEntries(conflictReasons),
      groups: groups.map((group) => group.map((record) =>
        String(record?.row?.["Организация"] || "").trim()))
    }));
  }

  if (groups.length > 1) {
    console.log("[DEDUPE_INN_CONFLICT] " + JSON.stringify({
      inn,
      organizations: groups.map((group) =>
        [...new Set(group.map((record) => String(record?.row?.["Организация"] || "").trim()).filter(Boolean))]
      )
    }));
  }

  return groups;
}

function recordDedupeMerge(diagnostics, type, records, key = "") {
  if (!diagnostics || !Array.isArray(records) || records.length < 2) return;
  if (!Array.isArray(diagnostics.merges)) diagnostics.merges = [];
  diagnostics.merges.push({
    type,
    key,
    organizations: records.map((record) =>
      String(record?.row?.["Организация"] || "").trim()
    ).filter(Boolean),
    inns: [...new Set(
      records.map((record) => normalizeInn(record?.row?.["ИНН"])).filter(Boolean)
    )]
  });
}

function deterministicGlobalDedupe(records, diagnostics = null, region = "") {
  const output = [];
  const unresolved = [];
  const byInn = new Map();

  // Confirmed INN is the strongest deterministic identity key and must work
  // across legal-name variants and source sheets.
  for (const record of records) {
    const inn = normalizeInn(record?.row?.["ИНН"]);
    if (!inn) {
      unresolved.push(record);
      continue;
    }
    if (!byInn.has(inn)) byInn.set(inn, []);
    byInn.get(inn).push(record);
  }

  for (const [inn, innGroup] of byInn.entries()) {
    const compatibleGroups = splitInnGroupByCompatibleIdentity(innGroup, inn, region);
    for (const compatibleGroup of compatibleGroups) {
      if (compatibleGroup.length > 1) {
        recordDedupeMerge(diagnostics, "confirmed_inn", compatibleGroup, inn);
      }
      output.push(
        compatibleGroup.length === 1
          ? compatibleGroup[0]
          : mergeQaRecordRows(compatibleGroup)
      );
    }
  }

  // Rows without confirmed INN are deduplicated conservatively by normalized
  // organization name. Ambiguous generic names also require matching place.
  const grouped = new Map();
  const singles = [];

  for (const record of unresolved) {
    const row = record?.row || {};
    const org = normalizeOrgKey(row["Организация"]);
    if (!org) {
      singles.push(record);
      continue;
    }

    const ambiguous = looksAmbiguousOrganizationName(row["Организация"]);
    const place = ambiguous ? normalizePlaceKey(row["Город/район"]) : "";
    const key = ambiguous ? `org:${org}|place:${place}` : `org:${org}`;
    if (!grouped.has(key)) grouped.set(key, []);
    grouped.get(key).push(record);
  }

  output.push(...singles);
  for (const [key, group] of grouped.entries()) {
    // A cleared or missing INN is not permission to merge distinct legal
    // entities. Partition same-name candidates by OGRN and branch/group role.
    const compatible = [];
    for (const record of group) {
      const target = compatible.find((partition) =>
        partition.every((prior) => unresolvedNameCompatible(prior, record))
      );
      if (target) target.push(record);
      else compatible.push([record]);
    }
    if (compatible.length > 1) {
      console.log("[DEDUPE_NAME_LEGAL_CONFLICT] " + JSON.stringify({
        key, organizations: group.map((record) =>
          String(record?.row?.["Организация"] || "")),
        ogrns: group.map((record) => identityOgrns(record?.row || {}))
      }));
    }
    for (const partition of compatible) {
      if (partition.length > 1) recordDedupeMerge(diagnostics, "normalized_name", partition, key);
      output.push(partition.length === 1 ? partition[0] : mergeQaRecordRows(partition));
    }
  }

  const aliasPass = conservativeAliasDedupe(output, diagnostics, region);
  output.length = 0;
  output.push(...aliasPass.records);
  if (aliasPass.aliasMerged) {
    console.log("[DEDUPE_ALIAS_SUMMARY] " + JSON.stringify({
      merged: aliasPass.aliasMerged,
      after: output.length
    }));
  }

  // Stable ordering makes repeated qualification byte-for-byte reproducible.
  output.sort((a, b) => {
    const ao = normalizeOrgKey(a?.row?.["Организация"]);
    const bo = normalizeOrgKey(b?.row?.["Организация"]);
    return ao.localeCompare(bo, "ru") ||
      normalizePlaceKey(a?.row?.["Город/район"]).localeCompare(
        normalizePlaceKey(b?.row?.["Город/район"]),
        "ru"
      ) ||
      String(a?.canonical_id || "").localeCompare(String(b?.canonical_id || ""));
  });

  return output.map((record, index) => ({
    ...record,
    id: `q${String(index + 1).padStart(6, "0")}`
  }));
}

function finalQualificationInput(records) {
  return records.map((record) => ({
    id: record.id,
    sheet: record.sheet,
    canonical_id: record.canonical_id,
    organization: record?.row?.["Организация"] || "",
    city: record?.row?.["Город/район"] || "",
    segment: record?.row?.["Техника/сегмент"] || "",
    basis_summary: record?.row?.["Основание"] || "",
    inn: record?.row?.["ИНН"] || "",
    evidence: record?.row?.__evidence || { source_urls: [], notes: [] }
  }));
}

function qualificationText(record) {
  const row = record?.row || {};
  const evidence = row.__evidence || {};
  return [
    row["Организация"],
    row["Город/район"],
    row["Техника/сегмент"],
    row["Основание"],
    ...(Array.isArray(evidence.notes) ? evidence.notes : [])
  ]
    .map((value) => String(value || "").toLowerCase())
    .join("\n")
    .replace(/ё/g, "е");
}

function qualificationEvidenceNotes(record) {
  const notes = record?.row?.__evidence?.notes;
  return (Array.isArray(notes) ? notes : [])
    .map((value) => String(value || "").toLowerCase().replace(/ё/g, "е").trim())
    .filter(Boolean);
}

function hasAnyPattern(text, patterns) {
  return patterns.some((pattern) => pattern.test(text));
}

const QUAL_PRIORITY_TARGET_PATTERNS = [
  /зерн/, /рапс/, /пшениц/, /ячмен/, /кукуруз/, /масличн/, /комбикорм/, /корм/,
  /щебен/, /щебн/, /песок/, /пгс/, /пгм/, /грави/, /карьер/, /неруд/,
  /торф/, /древес/, /лесоматериал/, /пиломатериал/, /щеп/, /опил/, /пеллет/,
  /лом/, /металлолом/, /вторсыр/, /отход/, /тко/, /контейнер/,
  /цемент/, /бетон/, /жби/, /асфальт/, /стройматериал/
];

const QUAL_GENERAL_TARGET_PATTERNS = [
  /сыпуч/, /навалоч/, /насыпн/, /объемн.{0,20}груз/, /объёмн.{0,20}груз/,
  /гранулирован/, /порошкообразн/, /инертн.{0,20}материал/, /минеральн.{0,20}сыр/,
  /руда/, /угол/, /кокс/, /соль/, /удобрен/, /сырь[ея]/, /bulk/
];

const QUAL_GENERAL_FLOW_PATTERNS = [
  /регулярн.{0,30}(перевоз|достав|вывоз|отгруз)/,
  /грузопоток/, /массов.{0,20}перевоз/, /автомобильн.{0,25}отгруз/,
  /добыч/, /перераб(?:от|ат)/, /производств/, /погруз/, /разгруз/,
  /перевозк/, /доставк/, /вывоз/
];

const QUAL_TRAILER_PATTERNS = [
  /полуприцеп/, /прицеп[- ]?зерновоз/, /прицеп[- ]?самосвал/, /самосвальн.{0,20}прицеп/,
  /зерновоз.{0,30}прицеп/, /щеповоз.{0,30}прицеп/, /ломовоз.{0,30}прицеп/,
  /тонар/, /grunwald/, /kogel/, /schmitz/, /wielton/, /krone/,
  /vin.{0,40}(полуприцеп|прицеп)/, /(полуприцеп|прицеп).{0,40}vin/
];

const QUAL_TRAILER_ACTION_PATTERNS = [
  /купил/, /куплен/, /приобрел/, /приобретен/, /закуп/, /лизинг/,
  /аренд/, /эксплуат/, /использ/, /парк/, /продаж/, /продает/, /продаем/,
  /ремонт/, /восстанов/, /владельц/, /собственник/, /госномер/, /гос номер/
];

const QUAL_HEAVY_PATTERNS = [
  /седельн.{0,20}тягач/, /тягач/, /категори.{0,8}(е|ce|cе)/, /водител.{0,30}(е|ce|cе)/,
  /самосвал/, /грузов.{0,20}автомоб/, /грузовик/, /автопарк/, /парк.{0,20}(камаз|маз|shacman|howo|sitrak|тягач|самосвал)/,
  /автотранспорт/, /атп\b/, /гараж/, /механик.{0,30}(груз|тягач|прицеп)/,
  /транспортн.{0,20}контракт/, /автомобильн.{0,20}перевоз/, /грузоперевоз/,
  /перевозчик/, /экспедитор/
];

const QUAL_TRANSPORT_PATTERNS = [
  ...QUAL_HEAVY_PATTERNS,
  /собственн.{0,20}достав/, /собственн.{0,20}вывоз/, /вывоз.{0,25}(отход|лом|щеб|пес|зерн|груз)/,
  /доставк.{0,25}(автотранспорт|самосвал|грузов|машин)/,
  /перевозк.{0,35}(зерн|щеб|пес|пгс|торф|щеп|лес|лом|отход|стройматериал)/
];

const QUAL_OPERATING_PROCESS_PATTERNS = [
  /производств/, /добыч/, /перераб(?:от|ат)/, /выращив/, /сельск.{0,20}хозяйств/,
  /фермер/, /кфх\b/, /спк\b/, /элеватор/, /комбикорм/, /карьер/,
  /лесозаготов/, /деревообработ/, /лесопил/, /заготовк.{0,30}(лом|вторсыр)/,
  /прием.{0,30}(лом|вторсыр|отход)/, /приём.{0,30}(лом|вторсыр|отход)/,
  /отгруз/, /погруз/, /разгруз/, /грузопоток/, /регулярн.{0,30}(перевоз|достав|вывоз)/
];

const GOVERNMENT_ENTITY_PATTERNS = [
  /(^|\s)администраци/,
  /(^|\s)министерств/,
  /(^|\s)департамент/,
  /(^|\s)комитет(\s|$)/,
  /(^|\s)правительств/,
  /совет.{0,20}депутат/,
  /городск.{0,20}дума/,
  /муниципальн.{0,30}(совет|собрани)/
];
const BUDGET_ENTITY_PATTERN =
  /(^|\s)(фку|фгбу|гбу|гку|мбу|мку|гау|мау|согбу|огбу|огку|мбоу|гбоу)(\s|$)/;
const PUBLIC_OPERATOR_PATTERN =
  /(^|\s)(фгуп|гуп|муп)(\s|$)/;

function classifyEntityType(row) {
  const documented = classifyCommercialEntity(row);
  if (documented !== "commercial") return documented;
  const name = normalizeOrgKey(row?.["Организация"] || "");
  if (!name) return "commercial";
  if (GOVERNMENT_ENTITY_PATTERNS.some((pattern) => pattern.test(name))) {
    return "government_body";
  }
  if (BUDGET_ENTITY_PATTERN.test(name)) return "budget_institution";
  if (PUBLIC_OPERATOR_PATTERN.test(name)) return "public_operator";
  return "commercial";
}

function entityTypeExcluded(entityType) {
  return entityType === "government_body" ||
    entityType === "budget_institution" ||
    (!INCLUDE_PUBLIC_OPERATORS && entityType === "public_operator");
}

function identityRegionMismatchFromNotes(notes = []) {
  return notes.some((raw) => {
    const note = String(raw || "").toLowerCase().replace(/ё/g, "е");
    if (!note.includes("identity:")) return false;
    return /региональн.{0,30}конфликт.{0,160}ошибочн|исходн.{0,40}(регион|указан).{0,80}ошибочн|не относится.{0,100}(регион|област|край|республик)|юридическ.{0,80}(?:адрес|лиц).{0,120}(?:друг|ином|не.{0,20}регион)|организац.{0,80}(?:из|зарегистрирован).{0,80}(?:друг|ином).{0,30}регион|упоминан.{0,80}относится.{0,80}(?:друг|ином).{0,30}регион/.test(note);
  });
}

function deterministicQualificationDecision(record) {
  const text = qualificationText(record);
  const role = String(record?.sheet || "");
  const directRole = role === "direct_buyers";
  const intermediaryRole = role === "intermediaries";
  const leasingRole = role === "leasing";
  const notes = qualificationEvidenceNotes(record);
  const identityRegionMismatch = identityRegionMismatchFromNotes(notes);
  const priorityTarget = hasAnyPattern(text, QUAL_PRIORITY_TARGET_PATTERNS);
  const generalTarget =
    hasAnyPattern(text, QUAL_GENERAL_TARGET_PATTERNS) &&
    hasAnyPattern(text, QUAL_GENERAL_FLOW_PATTERNS);
  const target = priorityTarget || generalTarget;
  const heavy = hasAnyPattern(text, QUAL_HEAVY_PATTERNS);
  const transport = hasAnyPattern(text, QUAL_TRANSPORT_PATTERNS);
  const operatingProcess = hasAnyPattern(text, QUAL_OPERATING_PROCESS_PATTERNS);
  const entityType = classifyEntityType(record?.row || {});
  const eligibility = commercialEligibility(record?.row || {});

  const speculative = /потенциал|потенциальн|перспектив|возможн|может использ|может эксплуат|вероятн|предполож|оценк.{0,30}уровн[ея]\s*b|целевой сегмент|подходит для|экономическ.{0,30}рациональн|наиболее близок|профиль.{0,30}близок/;
  const negativeAEvidence =
    /не подтвержд(ен|ена|ено|ены|ает|ают|ается|аются)|не обнаружен|не обнаружено|не обнаружены|нет подтвержден|нет достаточн|недостаточн.{0,80}(доказательств|данн|сведен)|(доказательств|данн|сведен).{0,180}недостаточн|нет\s+(?:достаточн|достоверн|прямых)[а-я]*.{0,60}(идентификац|клиент|модел|данн|сведен|подтверж)|нет данных|данн.{0,100}нет|не найден|не указа[нн]|не раскрыва|не раскрыт|не раскрыты|не идентифицир|клиент.{0,80}не (?:идентифицир|раскрыт|указан)|не дает.{0,40}подтверж|нет основан.{0,80}(утвержд|считать|полагать)|не дает.{0,40}основан.{0,80}(утвержд|считать|полагать)|не является|а не.{0,80}(владел|собственник|эксплуат|перевозчик)|не собственник|не доказательств.{0,30}собственн|не доказательство.{0,50}собственн|роль.{0,30}(оператор|посредник).{0,80}(?:а не|не явля)|только.{0,30}(канал|каталог|карточк)|без.{0,50}(конкретн.{0,20}(клиент|ремонт|сделк)|подтвержден)|требует дополнительн|требуется дополнительн|уровень b|уровень c|а не a|собственн.{0,40}(парк|эксплуатац).{0,40}не подтвержд|доказательств.{0,80}нет|прямых сведений.{0,80}не найден/;
  const farmImplementOnly =
    /(прицепн.{0,20}агрегат|плуг|сеялк|опрыскивател|разбрасывател).{0,120}/;
  const priorityTrailerModel =
    /(тонар\s*\d{3,5}|grunwald\s*[a-zа-я0-9-]+|kogel\s*[a-zа-я0-9-]+|schmitz\s*[a-zа-я0-9-]+|wielton\s*[a-zа-я0-9-]+|krone\s*[a-zа-я0-9-]+|пс[- ]?\d{1,3}[а-яa-z-]*|пст[- ]?\d{1,3}[а-яa-z-]*|ts\s*\d{2,3})/i;
  const genericTrailerIdentification =
    /((полуприцеп|прицеп).{0,50}(марка|модель|тип|серия|идентификатор).{0,50}[a-zа-я0-9-]{2,})|((марка|модель|тип|серия).{0,50}[a-zа-я0-9-]{2,}.{0,50}(полуприцеп|прицеп))/i;
  // A driver-operation signal is valid only when the SAME evidence note
  // contains all three elements: driver/vacancy + CE/E category + trailer.
  // Order is irrelevant, but none of the three may be omitted.
  const ceTrailerJob =
    /(?=[\s\S]*(?:водител|ваканси))(?=[\s\S]*категори.{0,12}(?:е|e|ce|cе))(?=[\s\S]*(?:полуприцеп|прицеп|тонар))/i;
  const trailerFleet =
    /(парк|автопарк|наличие|на балансе|в собственности|имеет|эксплуатирует|эксплуатаци).{0,100}(полуприцеп|прицеп|тонар)|((полуприцеп|прицеп|тонар).{0,100}(парк|автопарк|наличие|на балансе|в собственности|эксплуатирует|эксплуатаци))/;
  // Объявление об услуге ремонта/обслуживания не подтверждает выполненный
  // ремонт конкретной техники. Не приравниваем каталог сервиса к сделке.
  const trailerCommerce =
    /(продает|продаем|продаж[а-я]*|лизинг|лизингует|сдает в аренду|аренда).{0,100}(полуприцеп|прицеп|тонар)|((полуприцеп|прицеп|тонар).{0,100}(продает|продаем|продаж[а-я]*|лизинг|лизингует|сдает в аренду|аренда))/;
  const serviceOffering =
    /(сервис|сто|автосервис|ремонт|обслужив|диагностик|услуг|каталог|карточк|специализац)/;
  const specificServiceEvent =
    /(выполн(ен|ены|ила|или)|отремонтирован|проведен.{0,25}ремонт|заказ.наряд|акт выполненн|договор.{0,40}ремонт|контракт.{0,40}ремонт|закупк.{0,40}ремонт|тендер.{0,40}ремонт|клиент.{0,70}(полуприцеп|прицеп)|заказчик.{0,70}(полуприцеп|прицеп))/;
  const serviceMarketingOnly =
    /(оказыва.{0,30}услуг|предлага.{0,30}(ремонт|услуг)|перечень услуг|указан.{0,40}(ремонт|услуг)|заявлен.{0,40}(ремонт|услуг)|карточк.{0,70}ремонт|специализиру.{0,50}ремонт)/;

  let aEvidence = "";
  let aRule = "";

  for (const note of notes) {
    if (speculative.test(note) || negativeAEvidence.test(note)) continue;
    // Ownership/lease/procurement of someone else's trailer is not direct A.
    if (/(?:сторонн|треть[еёи]го|чуж|подрядчик).{0,80}(?:прицеп|полуприцеп)|(?:прицеп|полуприцеп).{0,80}(?:сторонн|треть[еёи]го|чуж|подрядчик)/.test(note) &&
        !/(?:собственн.{0,30}(?:прицеп|полуприцеп)|(?:прицеп|полуприцеп).{0,30}в собственности|на балансе|собственн.{0,20}парк)/.test(note)) continue;

    const cargoTrailerMention =
      /(полуприцеп|прицеп[- ]?(зерновоз|самосвал)|самосвальн.{0,20}прицеп|тонар|kogel|krone|schmitz|wielton|grunwald|пс[- ]?\d|пст[- ]?\d|пптс[- ]?\d)/i.test(note);
    if (farmImplementOnly.test(note) && !cargoTrailerMention) continue;

    const trailer = hasAnyPattern(note, QUAL_TRAILER_PATTERNS);
    const trailerAction = hasAnyPattern(note, QUAL_TRAILER_ACTION_PATTERNS);
    const explicitVinOrPlate =
      /(vin|госномер|гос номер).{0,60}(полуприцеп|прицеп)|(полуприцеп|прицеп).{0,60}(vin|госномер|гос номер)/.test(note);
    const tractorTrailerOperation =
      /(тягач|седельн).{0,100}(полуприцеп|прицеп|тонар)|(полуприцеп|прицеп|тонар).{0,100}(тягач|седельн)/.test(note) &&
      /(эксплуат|работа|рейс|перевоз|парк|водител|автопоезд)/.test(note);
    const freightTrailerContext =
      /(полуприцеп|тонар|kogel|krone|schmitz|wielton|grunwald|2птс[- ]?\d|пс[- ]?\d|пст[- ]?\d|низкорамн.{0,30}(прицеп|полуприцеп)|тяжеловозн.{0,30}(прицеп|полуприцеп)|грузов.{0,35}(прицеп|полуприцеп)|(прицеп|полуприцеп).{0,35}грузов)/i.test(note);
    const explicitTrailerProcurement =
      freightTrailerContext &&
      (
        /(закупк|тендер|поставк|приобрет|приобрел|приобрела|приобрели|купил|куплен|контракт|договор).{0,140}(полуприцеп|прицеп|тонар|kogel|krone|schmitz|wielton|grunwald)/i.test(note) ||
        /(полуприцеп|прицеп|тонар|kogel|krone|schmitz|wielton|grunwald).{0,140}(закупк|тендер|поставк|приобрет|приобрел|приобрела|приобрели|купил|куплен|контракт|договор)/i.test(note)
      );
    const explicitTrailerOwnership =
      freightTrailerContext &&
      (
        /(в собственности|на балансе|собственник|собственником|владелец|владельцем|принадлежит|собственн.{0,30}парк|имеет|эксплуатирует|эксплуатаци).{0,120}(полуприцеп|прицеп|тонар|kogel|krone|schmitz|wielton|grunwald)/i.test(note) ||
        /(полуприцеп|прицеп|тонар|kogel|krone|schmitz|wielton|grunwald).{0,120}(в собственности|на балансе|собственник|собственником|владелец|владельцем|принадлежит|собственн.{0,30}парк|имеет|эксплуатирует|эксплуатаци)/i.test(note)
      );
    // Если запись сообщает лишь об услуге/возможности ремонта, нельзя
    // выдавать её за конкретный заказ, эксплуатацию или выполненную работу.
    const genericServiceOnly =
      serviceOffering.test(note) &&
      !specificServiceEvent.test(note) &&
      (serviceMarketingOnly.test(note) || /ремонт|обслужив|сервис/.test(note)) &&
      !/(приобрел|приобретен|купил|куплен|лизинг|на балансе|эксплуатирует|собственн.{0,30}парк|вин|vin|госномер)/.test(note);
    if (genericServiceOnly) continue;

    const serviceProcurementOnly =
      /(закупк|тендер|контракт|договор).{0,80}услуг.{0,120}(полуприцеп|прицеп)|услуг.{0,120}(закупк|тендер|контракт|договор).{0,120}(полуприцеп|прицеп)/i.test(note);
    const partsOnly =
      /(запчаст|комплектующ|оси|подвеск|тормозн|пневматич).{0,100}(полуприцеп|прицеп)|(полуприцеп|прицеп).{0,100}(запчаст|комплектующ|оси|подвеск|тормозн|пневматич)/i.test(note);
    const sellerOnly =
      /(продает|продаж[а-я]*|продавец|продавцом|предлагает)/i.test(note) &&
      !/(закупк|приобрет|приобрел|купил|в собственности|на балансе|собственн.{0,30}парк|эксплуат)/i.test(note);
    const actualTrailerProcurement = explicitTrailerProcurement && !serviceProcurementOnly && !partsOnly;
    const actualServiceEvent =
      intermediaryRole && trailer && specificServiceEvent.test(note);
    const ongoingTrailerSeller =
      intermediaryRole &&
      /(компания|дилер|центр).{0,80}(продает|продаж[а-я]*).{0,100}(прицепн.{0,20}техник|полуприцеп|прицеп)/i.test(note) &&
      !/(объявлен|карточк|предложени|площадк)/i.test(note);
    const establishedCommercialChannel =
      intermediaryRole &&
      freightTrailerContext &&
      (
        trailerCommerce.test(note) &&
        /(официальн.{0,40}дилер|дилерск.{0,30}центр|trade[- ]?in|аренд.{0,30}выкуп|продаж[а-я]*.{0,40}и аренд|сервисн.{0,30}(центр|дилер))/i.test(note) ||
        ongoingTrailerSeller
      );
    const actualLeaseContract =
      leasingRole &&
      freightTrailerContext &&
      /(договор.{0,50}лизинг|лизингов.{0,50}договор|клиент.{0,100}лизинг|лизинг.{0,100}(тонар|полуприцеп|прицеп))/i.test(note);
    const directVinOwnership =
      directRole &&
      explicitVinOrPlate &&
      /(собствен|принадлеж|владел|эксплуат|перевозчик)/i.test(note);

    let matchedRule = "";
    if (directRole) {
      if (actualTrailerProcurement) matchedRule = "direct_procurement";
      else if (explicitTrailerOwnership || trailerFleet.test(note)) matchedRule = "direct_ownership_or_fleet";
      else if (ceTrailerJob.test(note) && !serviceProcurementOnly && !sellerOnly) matchedRule = "direct_driver_operation";
      else if (tractorTrailerOperation && !serviceProcurementOnly && !sellerOnly) matchedRule = "direct_operation";
      else if (directVinOwnership) matchedRule = "direct_vin_ownership";
    } else if (intermediaryRole) {
      const explicitIntermediaryOwnOperation =
        freightTrailerContext &&
        (
          /(в собственности|на балансе|собственник|собственником|собственн.{0,30}парк|имеет собственн|эксплуатирует).{0,120}(полуприцеп|прицеп|тонар|kogel|krone|schmitz|wielton|grunwald)/i.test(note) ||
          /(полуприцеп|прицеп|тонар|kogel|krone|schmitz|wielton|grunwald).{0,120}(в собственности|на балансе|собственник|собственником|собственн.{0,30}парк|имеет собственн|эксплуатирует)/i.test(note)
        );
      if (actualTrailerProcurement) matchedRule = "intermediary_completed_transaction";
      else if (actualServiceEvent) matchedRule = "intermediary_completed_service";
      else if (establishedCommercialChannel) matchedRule = "intermediary_established_channel";
      else if (explicitIntermediaryOwnOperation) matchedRule = "intermediary_own_operation";
    } else if (leasingRole) {
      if (actualLeaseContract) matchedRule = "leasing_concrete_contract";
      else if (actualTrailerProcurement) matchedRule = "leasing_concrete_transaction";
    }

    // A model name, product card, directory listing or generic sale/service
    // offer is supporting context only. It cannot independently promote a row
    // to A without a role-appropriate concrete event or operating signal.
    if (matchedRule) {
      // A negative, identity-only or hypothetical mention is not positive
      // trailer ownership/operation, even if it contains all regex keywords.
      const aExclusion = rejectUnsafeAEvidence(record, note);
      if (aExclusion) continue;
      aEvidence = note;
      aRule = matchedRule;
      break;
    }
  }

  // A is evidence-note only. Segment/basis text may support B/C context but
  // must never promote a company to A by itself.

  let grade = "";
  let reason = "";

  if (eligibility.blocked) {
    reason = eligibility.reason;
  } else if (entityTypeExcluded(entityType)) {
    reason = entityType === "government_body"
      ? "Орган власти исключён из коммерческого списка независимо от факта закупки техники."
      : entityType === "budget_institution"
        ? "Бюджетное/казённое учреждение исключено из коммерческого списка."
        : "Публичный оператор исключён настройкой INCLUDE_PUBLIC_OPERATORS.";
  } else if (identityRegionMismatch) {
    reason = "Identity-resolution подтвердил, что организация относится к другому региону; кандидат исключён до A/B/C.";
  } else if (aEvidence) {
    grade = "A";
    reason = "Конкретный evidence-note одновременно подтверждает прицепную/полуприцепную технику и факт сделки, владения, эксплуатации, ремонта или лизинга.";
  } else if (target && independentBSignals(record.row).valid) {
    grade = "B";
    reason = "В evidence одновременно подтверждены целевой груз/процесс и тяжелая автологистика или эксплуатационный сигнал.";
  } else if (directRole && target && operatingProcess) {
    grade = "C";
    reason = "Подтверждён действующий целевой производственный/грузовой процесс коммерческого грузовладельца; собственная техника или перевозчик пока не установлены.";
  } else if (target && transport) {
    grade = "C";
    reason = "В evidence подтверждены целевой груз/процесс и конкретный транспортно-логистический сигнал, но недостаточно данных для A/B.";
  } else {
    reason = target
      ? "Целевой груз упомянут, но evidence не подтверждает действующий коммерческий процесс или достаточный транспортный сигнал."
      : "Evidence не подтверждает достаточную коммерческую релевантность для A/B/C.";
  }

  return {
    decision: grade ? "include" : "exclude",
    grade,
    reason,
    aEvidence,
    aRule,
    signals: {
      target,
      priorityTarget,
      generalTarget,
      heavy,
      transport,
      operatingProcess,
      entityType,
      legalEligibility: eligibility.method,
      aEvidence: Boolean(aEvidence),
      identityRegionMismatch
    }
  };
}

async function runFinalQualification({
  client,
  records,
  region,
  assertNotCancelled,
  diagnosticPrefix = "final qualification"
}) {
  const decisions = new Map();
  const counts = { A: 0, B: 0, C: 0, excluded: 0 };

  for (let index = 0; index < records.length; index++) {
    if (index % 50 === 0) await assertNotCancelled();
    const record = records[index];
    const decision = deterministicQualificationDecision(record);
    decisions.set(record.id, {
      decision: decision.decision,
      grade: decision.grade,
      reason: decision.reason,
      aEvidence: decision.aEvidence || "",
      aRule: decision.aRule || ""
    });

    if (decision.grade) counts[decision.grade]++;
    else counts.excluded++;
  }

  console.log("[DETERMINISTIC_FINAL_QUALIFICATION] " + JSON.stringify({
    prefix: diagnosticPrefix,
    region,
    total: records.length,
    A: counts.A,
    B: counts.B,
    C: counts.C,
    excluded: counts.excluded
  }));

  return decisions;
}

// Candidate inventory is intentionally NOT a CRM sheet. Strong transport
// candidates with insufficient A/B/C evidence stay recoverable in checkpoint.
function actionableUnqualifiedLead(record) {
  const row = record?.row || {};
  const eligibility = commercialEligibility(row);
  if (eligibility.blocked || identityRegionMismatchFromNotes(qualificationEvidenceNotes(record))) return false;
  const ev = row.__evidence || {};
  const notes = (Array.isArray(ev.notes) ? ev.notes : [])
    .filter((note) => !/^(?:final inn:|identity:|подтвержденный инн:)/i.test(String(note).trim()));
  const urls = Array.isArray(ev.source_urls) ? ev.source_urls : [];
  if (!notes.length || !urls.some((url) => /^https?:\/\//i.test(String(url)))) return false;
  const claim = [row["Техника/сегмент"], ...notes].join(" ").toLowerCase().replace(/ё/g, "е");
  // Evidence of a real carrier, fleet, freight process or operations department.
  return /(грузоперевоз|грузов.{0,25}транспорт|транспортн.{0,20}компани|седельн.{0,20}тягач|полуприцеп|автопарк|автологистик|категори.{0,10}(?:ce|cе|е|e)|водител.{0,35}рейс|фулфилмент|механик.{0,25}транспорт|лизинг.{0,25}тягач|тентованн.{0,25}транспорт|междугородн.{0,30}перевоз|международн.{0,30}перевоз)/i.test(claim);
}

function reviewQueueKey(row) {
  return String(row?.__canonical_id || "") ||
    [normalizeOrgKey(row?.["Организация"]), normalizeInn(row?.["ИНН"])].join("|");
}

function mergedQualificationReviews(existing = [], newly = []) {
  const merged = new Map();
  for (const row of [...existing, ...newly]) {
    if (!row || !String(row["Организация"] || "").trim()) continue;
    if (commercialEligibility(row).blocked) continue;
    const key = reviewQueueKey(row);
    if (!merged.has(key)) merged.set(key, row);
  }
  return [...merged.values()];
}

function applyFinalQualification(records, decisions) {
  const result = {
    direct_buyers: [],
    intermediaries: [],
    leasing: [],
    statistics: [],
    qualification_review: []
  };
  const counts = { A: 0, B: 0, C: 0, excluded: 0 };

  for (const record of records) {
    const decision = decisions.get(record.id);
    if (!decision || decision.decision !== "include" || !decision.grade) {
      counts.excluded++;
      if (actionableUnqualifiedLead(record)) {
        const row = { ...record.row };
        row.__decision = "manual_review";
        row.__final_grade = "";
        row.__a_evidence = "";
        row.__a_rule = "";
        row.__qualification_origin_sheet = record.sheet;
        row.__decision_reason = String(decision?.reason || "Недостаточно подтверждённой квалификации.");
        row.__evidence = {
          ...(row.__evidence || {}),
          commercial_eligibility: commercialEligibility(row)
        };
        result.qualification_review.push(row);
      }
      continue;
    }

    const row = { ...record.row };
    row.__final_grade = decision.grade;
    row.__decision = "include";
    row.__decision_reason = decision.reason;
    row.__a_evidence = decision.grade === "A" ? String(decision.aEvidence || "") : "";
    row.__a_rule = decision.grade === "A" ? String(decision.aRule || "") : "";
    row["Основание"] = `${decision.grade} — ${decision.reason}`;
    row.__evidence = { ...(row.__evidence || {}), commercial_eligibility: commercialEligibility(row) };
    populateCommercialActions(row, record.sheet, decision.grade);
    counts[decision.grade]++;

    result[record.sheet].push(row);
  }

  return { result, counts };
}

function buildQualificationCheckpoint(records, decisions) {
  return {
    version: 1,
    records: records.map((record) => {
      const decision = decisions.get(record.id) || {};
      return {
        id: String(record.id || ""),
        canonical_id: String(record.canonical_id || ""),
        organization: String(record?.row?.["Организация"] || ""),
        grade: String(decision.grade || ""),
        decision: String(decision.decision || "exclude"),
        reason: String(decision.reason || ""),
        a_evidence: String(decision.aEvidence || ""),
        a_rule: String(decision.aRule || "")
      };
    })
  };
}

function compareQualificationCheckpoints(previousCheckpoint, currentCheckpoint) {
  const previous = Array.isArray(previousCheckpoint?.records)
    ? previousCheckpoint.records
    : [];
  const current = Array.isArray(currentCheckpoint?.records)
    ? currentCheckpoint.records
    : [];

  const keyFor = (item) =>
    String(item?.id || "").trim() ||
    String(item?.canonical_id || "").trim() ||
    normalizeOrgKey(item?.organization || "");

  const previousByKey = new Map(
    previous.map((item) => [keyFor(item), item]).filter(([key]) => key)
  );
  const currentByKey = new Map(
    current.map((item) => [keyFor(item), item]).filter(([key]) => key)
  );
  const transitions = {};
  const changed = [];
  let unchanged = 0;
  let added = 0;
  let removed = 0;

  for (const [key, now] of currentByKey.entries()) {
    const before = previousByKey.get(key);
    if (!before) {
      added++;
      continue;
    }

    const from = String(before.grade || "EXCLUDE").toUpperCase() || "EXCLUDE";
    const to = String(now.grade || "EXCLUDE").toUpperCase() || "EXCLUDE";

    if (from === to) {
      unchanged++;
      continue;
    }

    const transition = `${from}->${to}`;
    transitions[transition] = (transitions[transition] || 0) + 1;
    changed.push({
      id: String(now.id || before.id || ""),
      canonical_id: String(now.canonical_id || before.canonical_id || ""),
      organization: String(now.organization || before.organization || ""),
      from,
      to,
      previous_reason: String(before.reason || ""),
      current_reason: String(now.reason || "")
    });
  }

  for (const key of previousByKey.keys()) {
    if (!currentByKey.has(key)) removed++;
  }

  return {
    previous_total: previousByKey.size,
    current_total: currentByKey.size,
    unchanged,
    changed_count: changed.length,
    added,
    removed,
    transitions,
    changed
  };
}

class WebBudgetStopError extends Error {
  constructor(scope, used, limit, totalUsed, totalLimit) {
    super(`WEB_BUDGET_STOP:${scope}:${used}/${limit}:total=${totalUsed}/${totalLimit}`);
    this.name = "WebBudgetStopError";
    this.code = "WEB_BUDGET_STOP";
    this.scope = scope;
    this.used = used;
    this.limit = limit;
    this.totalUsed = totalUsed;
    this.totalLimit = totalLimit;
  }
}

function webBudgetScope(label = "") {
  const value = String(label || "").toLowerCase();
  if (value.startsWith("этап 1 |")) return "stage1";
  if (value.startsWith("этап 2 |")) return "stage2";
  if (value.startsWith("identity |")) return "identity";
  if (value.startsWith("география региона |")) return "geography";
  return "other";
}

function createFullWebBudget() {
  const total = Math.max(100, Math.floor(Number(process.env.OPENAI_FULL_WEB_MAX_CALLS || 4500)));
  return { limits: { total }, used: { stage1: 0, stage2: 0, identity: 0, geography: 0, other: 0, total: 0 }, warned: new Set(), stopped: new Set(), kind: "full" };
}

function createQualityWebBudget() {
  return {
    limits: {
      stage1: 50,
      stage2: 40,
      identity: 30,
      total: 120
    },
    used: {
      stage1: 0,
      stage2: 0,
      identity: 0,
      geography: 0,
      other: 0,
      total: 0
    },
    warned: new Set(),
    stopped: new Set()
  };
}

function publicWebBudgetState(budget) {
  if (!budget) return null;
  return {
    limits: { ...budget.limits },
    used: { ...budget.used }
  };
}

function budgetLimitForScope(budget, scope) {
  return Number(budget?.limits?.[scope] || 0);
}

function estimatedApiCostUsd(client) {
  const usage = tokenUsageSnapshot(client);
  const input = Math.max(0, usage.input_tokens - usage.cached_input_tokens);
  const cached = usage.cached_input_tokens;
  const output = usage.output_tokens;
  return Number(((input * Number(process.env.OPENAI_ESTIMATE_INPUT_USD_PER_M || 0.2)
    + cached * Number(process.env.OPENAI_ESTIMATE_CACHED_USD_PER_M || 0.02)
    + output * Number(process.env.OPENAI_ESTIMATE_OUTPUT_USD_PER_M || 1.2)) / 1000000
    + webUsageSnapshot(client) * OPENAI_WEB_SEARCH_COST_PER_CALL).toFixed(4));
}

function assertWebBudgetBeforeCall(client, diagnosticLabel) {
  const costLimit = Math.max(1, Number(process.env.OPENAI_MAX_RESEARCH_COST_USD || 60));
  const costSpent = estimatedApiCostUsd(client);
  if (costSpent >= costLimit) {
    const e = new WebBudgetStopError("estimated_cost_usd", costSpent, costLimit, webUsageSnapshot(client), Number(client?.__webBudget?.limits?.total || 0));
    console.error("[RESEARCH_COST_GUARDRAIL] " + JSON.stringify({ estimated_usd: costSpent, limit_usd: costLimit }));
    throw e;
  }
  const budget = client?.__webBudget;
  if (!budget) return;

  const scope = webBudgetScope(diagnosticLabel);
  const scopeLimit = budgetLimitForScope(budget, scope);
  const totalLimit = Number(budget.limits.total || 0);
  const scopeUsed = Number(budget.used[scope] || 0);
  const totalUsed = Number(budget.used.total || 0);

  const scopeExceeded = Boolean(scopeLimit && scopeUsed >= scopeLimit);
  const totalExceeded = Boolean(totalLimit && totalUsed >= totalLimit);
  if (scopeExceeded || totalExceeded) {
    throw new WebBudgetStopError(
      totalExceeded && !scopeExceeded ? "total" : scope,
      totalExceeded && !scopeExceeded ? totalUsed : scopeUsed,
      totalExceeded && !scopeExceeded ? totalLimit : scopeLimit,
      totalUsed,
      totalLimit
    );
  }
}

function recordWebUsage(client, diagnosticLabel, calls) {
  const amount = Math.max(0, Number(calls || 0));
  if (!amount) return;
  if (!client.__webUsage) {
    client.__webUsage = { total: 0, by_scope: {} };
  }
  const scope = webBudgetScope(diagnosticLabel);
  client.__webUsage.total = Number(client.__webUsage.total || 0) + amount;
  client.__webUsage.by_scope[scope] =
    Number(client.__webUsage.by_scope[scope] || 0) + amount;
}

function webUsageSnapshot(client) {
  return Number(client?.__webUsage?.total || 0);
}

function webYieldMetrics(webCalls, unique, strong) {
  const calls = Math.max(0, Number(webCalls || 0));
  return {
    web_calls: calls,
    estimated_web_cost_usd: Number((calls * OPENAI_WEB_SEARCH_COST_PER_CALL).toFixed(4)),
    unique_per_web: calls ? Number((Number(unique || 0) / calls).toFixed(3)) : null,
    strong_per_web: calls ? Number((Number(strong || 0) / calls).toFixed(3)) : null
  };
}

function stageRecoveryEvidenceOriented(stageIndex) {
  return stageIndex === 1 || stageIndex === 6;
}

function recoveryBranchIsSaturated(stageIndex, item) {
  if (!stageRecoveryEvidenceOriented(stageIndex)) return false;
  const familyCount = Object.values(item?.sourceFamilies || {})
    .filter((value) => Number(value || 0) > 0).length;
  return (
    (Number(item?.preliminaryA || 0) >= 2 || Number(item?.qualityScore || 0) >= 8) &&
    familyCount >= 2
  );
}

function recordWebBudgetUsage(client, diagnosticLabel, calls) {
  const budget = client?.__webBudget;
  const amount = Math.max(0, Number(calls || 0));
  if (!budget || !amount) return;

  const scope = webBudgetScope(diagnosticLabel);
  budget.used[scope] = Number(budget.used[scope] || 0) + amount;
  budget.used.total = Number(budget.used.total || 0) + amount;

  const checks = [
    { key: scope, used: budget.used[scope], limit: budgetLimitForScope(budget, scope) },
    { key: "total", used: budget.used.total, limit: Number(budget.limits.total || 0) }
  ];

  for (const check of checks) {
    if (!check.limit) continue;
    const ratio = check.used / check.limit;
    if (ratio >= 0.8 && !budget.warned.has(check.key)) {
      budget.warned.add(check.key);
      console.log("[WEB_BUDGET_WARNING] " + JSON.stringify({
        scope: check.key,
        used: check.used,
        limit: check.limit,
        total_used: budget.used.total,
        total_limit: budget.limits.total
      }));
    }
    if (check.used >= check.limit && !budget.stopped.has(check.key)) {
      budget.stopped.add(check.key);
      console.log("[WEB_BUDGET_STOP] " + JSON.stringify({
        scope: check.key,
        used: check.used,
        limit: check.limit,
        total_used: budget.used.total,
        total_limit: budget.limits.total
      }));
    }
  }
}

function isWebBudgetStop(error) {
  return error?.code === "WEB_BUDGET_STOP" || error?.name === "WebBudgetStopError";
}

function isOpenAIBillingStop(error) {
  const message = String(error?.message || error || "").toLowerCase();
  return (
    message.includes("no credits remaining") ||
    message.includes("insufficient_quota") ||
    message.includes("billing") && message.includes("credit") ||
    message.includes("quota") && message.includes("exceeded")
  );
}

function diagnosticRowCount(data) {
  return (
    (Array.isArray(data?.direct_buyers) ? data.direct_buyers.length : 0) +
    (Array.isArray(data?.intermediaries) ? data.intermediaries.length : 0) +
    (Array.isArray(data?.leasing) ? data.leasing.length : 0)
  );
}

function diagnosticEvidenceUrlCount(data) {
  let count = 0;
  for (const row of [
    ...(data?.direct_buyers || []),
    ...(data?.intermediaries || []),
    ...(data?.leasing || [])
  ]) {
    count += Array.isArray(row?.__evidence?.source_urls)
      ? row.__evidence.source_urls.length
      : 0;
  }
  return count;
}

function diagnosticDiscoveryRows(data) {
  const rows = [];
  for (const [sheet, values] of [
    ["direct_buyers", data?.direct_buyers || []],
    ["intermediaries", data?.intermediaries || []],
    ["leasing", data?.leasing || []]
  ]) {
    for (const row of values) {
      rows.push({
        sheet,
        organization: String(row?.["Организация"] || "").trim(),
        city: String(row?.["Город/район"] || "").trim(),
        segment: String(row?.["Техника/сегмент"] || "").trim(),
        basis: String(row?.["Основание"] || "").trim(),
        evidence: {
          source_urls: Array.isArray(row?.__evidence?.source_urls)
            ? row.__evidence.source_urls.map(String)
            : [],
          notes: Array.isArray(row?.__evidence?.notes)
            ? row.__evidence.notes.map(String)
            : []
        }
      });
    }
  }
  return rows;
}

function emptyTokenUsage() {
  return {
    input_tokens: 0,
    output_tokens: 0,
    reasoning_tokens: 0,
    cached_input_tokens: 0,
    total_tokens: 0
  };
}

function tokenUsageSnapshot(client) {
  return { ...emptyTokenUsage(), ...(client?.__tokenUsage || {}) };
}

function recordTokenUsage(client, usage) {
  if (!client || !usage) return;
  if (!client.__tokenUsage) client.__tokenUsage = emptyTokenUsage();
  const input = Number(usage?.input_tokens || 0);
  const output = Number(usage?.output_tokens || 0);
  const total = Number(usage?.total_tokens || input + output);
  client.__tokenUsage.input_tokens += input;
  client.__tokenUsage.output_tokens += output;
  client.__tokenUsage.reasoning_tokens += Number(
    usage?.output_tokens_details?.reasoning_tokens || 0
  );
  client.__tokenUsage.cached_input_tokens += Number(
    usage?.input_tokens_details?.cached_tokens || 0
  );
  client.__tokenUsage.total_tokens += total;
}

function tokenUsageDelta(after, before) {
  const result = {};
  for (const key of Object.keys(emptyTokenUsage())) {
    result[key] = Math.max(0, Number(after?.[key] || 0) - Number(before?.[key] || 0));
  }
  return result;
}

function diagnosticToolCounts(response) {
  const counts = {};
  for (const item of response?.output || []) {
    const type = String(item?.type || "unknown");
    if (!type.endsWith("_call")) continue;
    counts[type] = (counts[type] || 0) + 1;
  }
  return counts;
}

function diagnosticWebQueries(response) {
  const queries = [];
  for (const item of response?.output || []) {
    if (item?.type !== "web_search_call") continue;
    const action = item?.action || {};
    if (typeof action.query === "string" && action.query.trim()) {
      queries.push(action.query.trim());
    }
    if (Array.isArray(action.queries)) {
      for (const query of action.queries) {
        if (typeof query === "string" && query.trim()) queries.push(query.trim());
      }
    }
  }
  return [...new Set(queries)];
}

function compactDiagnosticQuery(input, explicitLabel = "") {
  if (explicitLabel) return explicitLabel;
  return String(input || "")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 320);
}

async function askJson(client, {
  input,
  model = MODEL,
  maxOutputTokens = RESEARCH_MAX_OUTPUT_TOKENS,
  webSearch = false,
  fileSearchVectorStoreId = "",
  diagnosticLabel = "",
  responseSchema = null,
  schemaName = "structured_output",
  allowJsonRepair = true,
  maxToolCalls = null,
  timeoutMs = null
}) {
  const request = {
    model,
    input,
    max_output_tokens: maxOutputTokens
  };
  if (responseSchema) {
    request.text = {
      format: {
        type: "json_schema",
        name: schemaName,
        strict: true,
        schema: responseSchema
      }
    };
  }
  const tools = [];
  if (webSearch) tools.push({ type: "web_search" });
  if (fileSearchVectorStoreId) {
    tools.push({
      type: "file_search",
      vector_store_ids: [fileSearchVectorStoreId],
      max_num_results: COURT_FILE_SEARCH_MAX_RESULTS
    });
  }
  if (tools.length) {
    request.tools = tools;
    request.tool_choice = "required";
    if (Number.isFinite(Number(maxToolCalls)) && Number(maxToolCalls) > 0) {
      request.max_tool_calls = Math.floor(Number(maxToolCalls));
    }
  }

  let requestSignal = client.__jobSignal || null;
  if (Number.isFinite(Number(timeoutMs)) && Number(timeoutMs) > 0) {
    const timeoutSignal = AbortSignal.timeout(Math.floor(Number(timeoutMs)));
    requestSignal = requestSignal
      ? AbortSignal.any([requestSignal, timeoutSignal])
      : timeoutSignal;
  }
  const requestOptions = requestSignal ? { signal: requestSignal } : undefined;
  const startedAt = Date.now();
  const query = compactDiagnosticQuery(input, diagnosticLabel);

  if (webSearch) assertWebBudgetBeforeCall(client, diagnosticLabel);

  try {
    const response = await client.responses.create(request, requestOptions);
    const usage = response?.usage || {};
    recordTokenUsage(client, usage);
    const stopReason =
      response?.incomplete_details?.reason ||
      (response?.status === "completed" ? "completed" : response?.status || "unknown");
    const toolCounts = diagnosticToolCounts(response);
    if (webSearch) {
      const webCalls = Number(toolCounts.web_search_call || 0);
      recordWebUsage(client, diagnosticLabel, webCalls);
      recordWebBudgetUsage(
        client,
        diagnosticLabel,
        webCalls
      );
    }

    let parsed = null;
    let parseError = "";
    let repaired = false;
    let repairUsage = null;
    try {
      parsed = parseJson(response.output_text || "");
    } catch (error) {
      parseError = error?.message || "parse error";

      if (
        allowJsonRepair &&
        response.status === "completed" &&
        String(response.output_text || "").trim()
      ) {
        try {
          const repairStartedAt = Date.now();
          const repairRequest = {
            model,
            input:
              "Исправь ТОЛЬКО синтаксис/структуру следующего ответа JSON. " +
              "Не добавляй новые факты, компании, URL или выводы. " +
              "Сохрани всю информацию исходного ответа, которую можно однозначно восстановить.\n\n" +
              String(response.output_text || ""),
            max_output_tokens: Math.min(maxOutputTokens, 12000)
          };
          if (responseSchema) {
            repairRequest.text = {
              format: {
                type: "json_schema",
                name: schemaName + "_repair",
                strict: true,
                schema: responseSchema
              }
            };
          } else {
            repairRequest.text = { format: { type: "json_object" } };
          }

          const repairedResponse = await client.responses.create(
            repairRequest,
            requestOptions
          );
          if (!repairedResponse.status || repairedResponse.status === "completed") {
            parsed = parseJson(repairedResponse.output_text || "");
            repaired = true;
            parseError = "";
            repairUsage = repairedResponse?.usage || null;
            recordTokenUsage(client, repairUsage);
            console.log("[OPENAI_JSON_REPAIR] " + JSON.stringify({
              query,
              model,
              schema_name: responseSchema ? schemaName : null,
              duration_ms: Date.now() - repairStartedAt,
              input_tokens: repairUsage?.input_tokens ?? null,
              output_tokens: repairUsage?.output_tokens ?? null,
              reasoning_tokens: repairUsage?.output_tokens_details?.reasoning_tokens ?? null,
              rows_recovered: diagnosticRowCount(parsed)
            }));
          }
        } catch (repairError) {
          console.error("[OPENAI_JSON_REPAIR] " + JSON.stringify({
            query,
            model,
            schema_name: responseSchema ? schemaName : null,
            status: "error",
            error: repairError?.message || String(repairError)
          }));
        }
      }
    }

    console.log("[OPENAI_DIAG] " + JSON.stringify({
      query,
      model,
      web_search: webSearch,
      file_search: Boolean(fileSearchVectorStoreId),
      structured_output: Boolean(responseSchema),
      schema_name: responseSchema ? schemaName : null,
      initial_prompt_chars: String(input || "").length,
      max_output_tokens: maxOutputTokens,
      max_tool_calls: maxToolCalls,
      timeout_ms: timeoutMs,
      status: response?.status || "",
      stop_reason: stopReason,
      duration_ms: Date.now() - startedAt,
      input_tokens: usage?.input_tokens ?? null,
      output_tokens: usage?.output_tokens ?? null,
      total_tokens: usage?.total_tokens ?? (
        Number(usage?.input_tokens || 0) + Number(usage?.output_tokens || 0)
      ),
      reasoning_tokens: usage?.output_tokens_details?.reasoning_tokens ?? null,
      cached_input_tokens: usage?.input_tokens_details?.cached_tokens ?? null,
      repair_total_tokens: repairUsage
        ? Number(repairUsage?.total_tokens || (
            Number(repairUsage?.input_tokens || 0) + Number(repairUsage?.output_tokens || 0)
          ))
        : 0,
      cumulative_tokens: tokenUsageSnapshot(client),
      estimated_api_cost_usd: estimatedApiCostUsd(client),
      tool_calls: toolCounts,
      web_search_queries: diagnosticWebQueries(response),
      output_chars: String(response?.output_text || "").length,
      rows_returned: parsed ? diagnosticRowCount(parsed) : null,
      evidence_urls: parsed ? diagnosticEvidenceUrlCount(parsed) : null,
      json_repaired: repaired,
      repair_input_tokens: repairUsage?.input_tokens ?? null,
      repair_output_tokens: repairUsage?.output_tokens ?? null,
      parse_error: parseError || null
    }));

    if (response.status && response.status !== "completed") {
      throw new Error(`OpenAI response status: ${response.status}; reason: ${stopReason}`);
    }
    if (parseError) throw new Error(parseError);
    return parsed;
  } catch (error) {
    if (isOpenAIBillingStop(error)) {
      error.code = "OPENAI_BILLING_STOP";
    }
    console.error("[OPENAI_DIAG] " + JSON.stringify({
      query,
      model,
      web_search: webSearch,
      file_search: Boolean(fileSearchVectorStoreId),
      structured_output: Boolean(responseSchema),
      schema_name: responseSchema ? schemaName : null,
      initial_prompt_chars: String(input || "").length,
      max_output_tokens: maxOutputTokens,
      timeout_ms: timeoutMs,
      status: "error",
      stop_reason: client.__jobSignal?.aborted ? "cancelled" : "error",
      duration_ms: Date.now() - startedAt,
      error: error?.message || String(error)
    }));
    throw error;
  }
}

function askResearch(
  client,
  input,
  maxOutputTokens = RESEARCH_MAX_OUTPUT_TOKENS,
  diagnosticLabel = "",
  maxToolCalls = 4
) {
  return askJson(client, {
    input,
    model: MODEL,
    maxOutputTokens,
    webSearch: true,
    responseSchema: DISCOVERY_SCHEMA,
    schemaName: "research_discovery",
    diagnosticLabel,
    maxToolCalls
  });
}

function askWithoutSearch(client, input, model, maxOutputTokens) {
  return askJson(client, {
    input,
    model,
    maxOutputTokens,
    webSearch: false
  });
}

function askTargetedSearch(client, input, timeoutMs = ENRICHMENT_SEARCH_TIMEOUT_MS, maxToolCalls = 2) {
  return askJson(client, {
    input,
    model: TARGETED_SEARCH_MODEL,
    maxOutputTokens: TARGETED_SEARCH_MAX_OUTPUT_TOKENS,
    webSearch: true,
    maxToolCalls,
    timeoutMs
  });
}

function contactSearchPrompt(row, region, kind = "contacts") {
  const organization = String(row?.["Организация"] || "").trim();
  const inn = normalizeInn(row?.["ИНН"]);
  const exactQuery = [
    organization,
    inn,
    kind === "phone" ? "телефон" : "контакты"
  ].filter(Boolean).join(" ");

  return `ПОИСК КОНТАКТОВ ОДНОЙ КОМПАНИИ.
РЕГИОН: ${region}
ОРГАНИЗАЦИЯ: ${organization}
ИНН: ${inn || "не подтверждён"}

ОБЯЗАТЕЛЬНЫЙ ПЕРВИЧНЫЙ ЗАПРОС: "${exactQuery}".
Используй web_search. Приоритет: официальный сайт/страница контактов, официальный реестр/документ, устойчивый бизнес-реестр.
Возвращай телефон ТОЛЬКО если он явно относится к этому юрлицу/ИНН. Не используй номер одноимённой или связанной компании.
Руководителя/ЛПР возвращай отдельно от телефона и только при явной привязке к этому юрлицу.
Российские телефоны нормализуй к 7XXXXXXXXXX. Несколько телефонов — отдельными элементами массива.
Не выдумывай и не дополняй цифры.
Верни ТОЛЬКО JSON по схеме.`;
}

function compactContactBatchTarget(row) {
  const evidence = row?.__evidence || {};
  return {
    id: checkpointRowId(row),
    organization: String(row?.["Организация"] || "").slice(0, 170),
    inn: normalizeInn(row?.["ИНН"]),
    city: String(row?.["Город/район"] || "").slice(0, 110),
    need_phone: !hasConfirmedPhone(row),
    need_leader: !hasConfirmedLeader(row),
    official_urls: (Array.isArray(evidence.source_urls) ? evidence.source_urls : [])
      .filter((url) => /^https?:\/\//i.test(String(url))).slice(0, 2)
  };
}
async function searchContactBatchWithWeb({ client, rows, region, deadlineAt }) {
  const remaining = deadlineRemaining(deadlineAt);
  if (remaining <= 8000) throw new Error("CONTACT_BATCH_DEADLINE");
  // The model sees all five legal entities at once; it must not search
  // for each one separately or infer phone ownership from group websites.
  const response = await askJson(client, {
    input: "ПАКЕТНЫЙ ПОИСК КОНТАКТОВ. РЕГИОН: " + region +
      "\nКОМПАНИИ: " + JSON.stringify(rows.map(compactContactBatchTarget)) +
      "\nИспользуй только 1–2 общих web_search на пакет. Возвращай отдельные элементы по id/ИНН. " +
      "Убедись в строгой принадлежности телефона или руководителя К ЭТОМУ юрлицу, а не группе, филиалу, чужому перевозчику или одноимённой компании. " +
      "Для найденных контактов обязательны точные source_urls. Не подтверждены — оставь phones=[], leader='' и status='not_found'. " +
      "Не выполняй отдельный web_search ради каждого телефона или директора. " +
      "Верни JSON строго по схеме. Каждый id представь один раз.",
    model: TARGETED_SEARCH_MODEL,
    maxOutputTokens: Math.max(CONTACT_SEARCH_MAX_OUTPUT_TOKENS, 3200),
    webSearch: true,
    responseSchema: CONTACT_BATCH_SCHEMA,
    schemaName: "contact_batch_search",
    maxToolCalls: CONTACT_BATCH_SETTINGS.batchWebCalls,
    diagnosticLabel: "contact batch | " + rows.length + " companies",
    timeoutMs: Math.min(CONTACT_SEARCH_TIMEOUT_MS * 2, Math.max(5000, remaining - 3000)),
    allowJsonRepair: false
  });
  const byId = new Map();
  for (const item of Array.isArray(response?.items) ? response.items : []) {
    const id = String(item?.id || "");
    if (id && !byId.has(id)) byId.set(id, item);
  }
  return rows.map((row) => ({
    id: checkpointRowId(row),
    result: validBatchContactItem(byId.get(checkpointRowId(row)), row, checkpointRowId(row))
  }));
}
async function searchContactsWithWeb({
  client,
  row,
  region,
  deadlineAt,
  phoneRetryBudget = null
}) {
  if (hasConfirmedPhone(row) && hasConfirmedLeader(row)) {
    return { status: "ok", phones: [], leader: "", official_site: "", note: "Already confirmed" };
  }
  const firstTimeout = Math.min(
    CONTACT_SEARCH_TIMEOUT_MS,
    Math.max(5000, deadlineRemaining(deadlineAt) - 2000)
  );
  const first = await askJson(client, {
    input: contactSearchPrompt(row, region, "contacts"),
    model: TARGETED_SEARCH_MODEL,
    maxOutputTokens: CONTACT_SEARCH_MAX_OUTPUT_TOKENS,
    webSearch: true,
    responseSchema: CONTACT_SEARCH_SCHEMA,
    schemaName: "contact_search",
    diagnosticLabel: `contact web | ${row?.["Организация"] || ""}`,
    maxToolCalls: 2,
    timeoutMs: firstTimeout,
    allowJsonRepair: false
  });

  const phones = new Set(
    (Array.isArray(first?.phones) ? first.phones : [])
      .map(normalizePhoneDigits)
      .filter(Boolean)
  );

  let second = null;
  // Never retry merely because the first search found no phone (or found only
  // a leader). A strict A + sourced official-site reason and global one-call
  // reservation is required.
  const retryAllowed = mayRetryContactPhone(
    row, { phones: [...phones], official_site: first?.official_site,
      source_urls: first?.source_urls },
    Number(phoneRetryBudget?.remaining || 0), deadlineRemaining(deadlineAt)
  );
  if (retryAllowed && !hasConfirmedPhone(row)) {
    phoneRetryBudget.remaining--;
    const secondTimeout = Math.min(
      CONTACT_SEARCH_TIMEOUT_MS,
      Math.max(5000, deadlineRemaining(deadlineAt) - 2000)
    );
    second = await askJson(client, {
      input: contactSearchPrompt(row, region, "phone"),
      model: TARGETED_SEARCH_MODEL,
      maxOutputTokens: CONTACT_SEARCH_MAX_OUTPUT_TOKENS,
      webSearch: true,
      responseSchema: CONTACT_SEARCH_SCHEMA,
      schemaName: "contact_phone_search",
      diagnosticLabel: `contact phone retry | ${row?.["Организация"] || ""}`,
      maxToolCalls: 1,
      timeoutMs: secondTimeout,
      allowJsonRepair: false
    });
    for (const phone of Array.isArray(second?.phones) ? second.phones : []) {
      const normalized = normalizePhoneDigits(phone);
      if (normalized) phones.add(normalized);
    }
  }

  const leader = String(first?.leader || second?.leader || "").trim();
  return {
    status: phones.size || leader ? "ok" : "not_found",
    phones: [...phones],
    leader,
    official_site: String(first?.official_site || second?.official_site || "").trim(),
    note: [first?.note, second?.note].map((value) => String(value || "").trim()).filter(Boolean).join(" | ")
  };
}

async function verifyPhoneWithWebSearch({
  client,
  row,
  region,
  phone,
  deadlineAt
}) {
  const inn = normalizeInn(row?.["ИНН"]);
  if (!inn || deadlineRemaining(deadlineAt) <= 5000) {
    return { confirmed: false, phone, note: "Недостаточно времени или нет подтверждённого ИНН для конфликтной проверки." };
  }
  const timeoutMs = Math.min(
    CONTACT_SEARCH_TIMEOUT_MS,
    Math.max(5000, deadlineRemaining(deadlineAt) - 2000)
  );
  return askJson(client, {
    input: `ПРОВЕРКА ПРИНАДЛЕЖНОСТИ ТЕЛЕФОНА.
РЕГИОН: ${region}
КОМПАНИЯ: ${row?.["Организация"] || ""}
ИНН: ${inn}
ТЕЛЕФОН: ${phone}

Выполни web_search запрос строго по смыслу: "${phone} ${inn}".
confirmed=true только если найденные сведения явно связывают этот телефон именно с этим юрлицом/ИНН.
Одноимённые, соседние и связанные компании не подходят. Не угадывай.
Верни только JSON по схеме.`,
    model: TARGETED_SEARCH_MODEL,
    maxOutputTokens: 900,
    webSearch: true,
    responseSchema: PHONE_VERIFY_SCHEMA,
    schemaName: "phone_owner_verification",
    diagnosticLabel: `phone verify | ${phone} | ${inn}`,
    maxToolCalls: 2,
    timeoutMs,
    allowJsonRepair: false
  });
}

function askCourtArchive(client, input) {
  if (!COURT_VECTOR_STORE_ID) return null;
  return askJson(client, {
    input,
    model: COURT_ARCHIVE_MODEL,
    maxOutputTokens: RESEARCH_MAX_OUTPUT_TOKENS,
    fileSearchVectorStoreId: COURT_VECTOR_STORE_ID
  });
}

function courtArchiveInstruction(theme, region, alreadyFound = []) {
  const known = alreadyFound.length
    ? `\nУже найденные на предыдущих архивных проходах: ${alreadyFound.join("; ")}. Ищи прежде всего НОВЫЕ организации и новые дела.`
    : "";
  return `РЕГИОН: ${region}
ИСТОЧНИК: загруженный пользователем архив судебных актов в file_search.
ТЕМА АРХИВНОГО ПРОХОДА: ${theme}

ОБЯЗАТЕЛЬНО используй file_search по архиву. Ищи документы, связанные именно с выбранным регионом — по суду, месту события, маршруту, адресу организации или обстоятельствам дела.
Извлекай реальные организации, которые могут быть собственниками, перевозчиками, лизингополучателями, арендаторами или фактическими эксплуатантами тяжёлого транспорта.
В "__evidence.source_urls" не выдумывай URL архивного файла; в "__evidence.notes" укажи номер дела, суд, дату, транспорт, госномер/VIN, статью и обстоятельства, если они явно есть в найденном тексте.
Сам факт упоминания организации не даёт A/B. Не делай вывод о собственнике/эксплуатанте без текста судебного акта.
Возвращай только организации, имеющие отношение к тяжёлой автологистике, прицепной технике, весогабаритному контролю, лизингу/ремонту техники или иному релевантному транспортному спору.${known}`;
}

function commentValue(comment, label) {
  const line = String(comment || "")
    .split(/\r?\n/)
    .find((x) => x.trim().toLowerCase().startsWith(label.toLowerCase() + ":"));
  return line ? line.slice(line.indexOf(":") + 1).trim() : "";
}

function isMissingText(value) {
  const text = String(value || "").trim().toLowerCase();
  return !text ||
    text === "н/д" ||
    text.includes("не найден") ||
    text.includes("не подтвержден") ||
    text.includes("требуется финальная проверка");
}

function evidenceEmail(row) {
  const evidence = row?.__evidence || {};
  const texts = [
    evidence.email,
    ...(Array.isArray(evidence.notes) ? evidence.notes : [])
  ].map((value) => String(value || ""));
  for (const text of texts) {
    const match = text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
    if (match) return match[0];
  }
  return "";
}

function compactActivityDescription(row) {
  const raw = String(
    row?.["Техника/сегмент"] ||
    row?.["Основание"] ||
    ""
  )
    .replace(/^\s*[ABC]\s*[—–:-]\s*/i, "")
    .replace(/\s+/g, " ")
    .trim();
  return raw ? raw.slice(0, 420) : "требуется финальная проверка";
}

function mergeResearchComment(row, incomingComment = "") {
  const current = String(row?.__comment || "");
  const evidence = row?.__evidence || {};
  const pickIncoming = (label) => {
    const value = commentValue(incomingComment, label);
    return isMissingText(value) ? "" : value;
  };
  const pickCurrent = (label) => {
    const value = commentValue(current, label);
    return isMissingText(value) ? "" : value;
  };

  const source =
    pickIncoming("Сайт/источник") ||
    pickCurrent("Сайт/источник") ||
    String(evidence.official_site || "").trim() ||
    (Array.isArray(evidence.source_urls) ? String(evidence.source_urls[0] || "").trim() : "") ||
    "не подтверждено";
  const activity =
    pickIncoming("Деятельность") ||
    pickCurrent("Деятельность") ||
    compactActivityDescription(row);
  const manager = String(row?.["Управляющая компания"] || "").trim();
  const holding =
    pickIncoming("Холдинг/УК/группа") ||
    pickCurrent("Холдинг/УК/группа") ||
    (manager && !/не подтвержд/i.test(manager) ? manager : "") ||
    "не подтверждено";
  const email =
    pickIncoming("Email") ||
    pickCurrent("Email") ||
    evidenceEmail(row) ||
    "не найден";

  row.__comment = [
    `Сайт/источник: ${source}`,
    `ИНН: ${normalizeInn(row?.["ИНН"]) || "не подтверждено"}`,
    `Деятельность: ${activity}`,
    `Холдинг/УК/группа: ${holding}`,
    `Email: ${email}`
  ].join("\n");
  return row.__comment;
}

function missingResearchFields(row) {
  mergeResearchComment(row);
  const gaps = [];
  const comment = row?.__comment || "";
  if (isMissingText(commentValue(comment, "Email"))) gaps.push("email");

  const holding = commentValue(comment, "Холдинг/УК/группа");
  const manager = String(row?.["Управляющая компания"] || "").trim();
  if (isMissingText(holding) && (!manager || /не подтвержд/i.test(manager))) {
    gaps.push("холдинг/УК/группа");
  }

  if (isMissingText(row?.["Выручка последнего подтвержденного года"])) {
    gaps.push("выручка последнего подтвержденного года");
  }
  if (isMissingText(row?.["Численность"])) {
    gaps.push("численность");
  }

  return [...new Set(gaps)];
}

function prioritizedResearchGaps(row) {
  populateKnownEvidenceFields(row);
  return missingResearchFields(row);
}

function compactEnrichmentTarget(row) {
  const evidence = row?.__evidence || {};
  return {
    id: checkpointRowId(row),
    organization: String(row?.["Организация"] || "").slice(0, 180),
    inn: normalizeInn(row?.["ИНН"]),
    city: String(row?.["Город/район"] || "").slice(0, 120),
    manager: String(row?.["Управляющая компания"] || "").slice(0, 180),
    revenue: row?.["Выручка последнего подтвержденного года"] || "",
    headcount: row?.["Численность"] || "",
    comment: String(row?.__comment || "").slice(0, 1200),
    evidence_urls: (Array.isArray(evidence.source_urls) ? evidence.source_urls : [])
      .map(String).filter(Boolean).slice(0, 3),
    evidence_notes: (Array.isArray(evidence.notes) ? evidence.notes : [])
      .map(String).filter(Boolean).slice(0, 3).map((value) => value.slice(0, 420))
  };
}

function strictResearchNumber(value) {
  if (typeof value === "number") return Number.isFinite(value) ? Math.round(value) : "";
  const text = String(value ?? "").trim().replace(/\s+/g, "");
  if (!/^\d+(?:[.,]\d+)?$/.test(text)) return "";
  const parsed = Number(text.replace(",", "."));
  return Number.isFinite(parsed) ? Math.round(parsed) : "";
}

function applyTargetedPatch(row, result) {
  const allowed = new Set([
    "Управляющая компания",
    "Выручка последнего подтвержденного года",
    "Численность"
  ]);
  for (const [key, value] of Object.entries(result?.fields || {})) {
    if (!allowed.has(key)) continue;
    if (value === undefined || value === null || String(value).trim() === "") continue;
    if (key === "Выручка последнего подтвержденного года" || key === "Численность") {
      const numeric = strictResearchNumber(value);
      if (numeric !== "" && isMissingText(row[key])) row[key] = numeric;
    } else if (!String(row[key] || "").trim() || /не подтвержд/i.test(String(row[key]))) {
      row[key] = value;
    }
  }
  mergeResearchComment(row, String(result?.__comment || "").trim());
}

function buildConflictGroups(records) {
  const buckets = new Map();
  const add = (key, record) => {
    if (!key) return;
    if (!buckets.has(key)) buckets.set(key, []);
    const arr = buckets.get(key);
    if (!arr.some((x) => x.id === record.id)) arr.push(record);
  };

  for (const record of records) {
    const row = record.row || {};
    const org = normalizeOrgKey(row["Организация"]);
    const place = normalizePlaceKey(row["Город/район"]);
    if (org && place) add(`orgplace:${org}|${place}`, record);

    for (const phone of splitPhoneEntries(row["Телефон"])) {
      const normalized = normalizePhoneDigits(phone);
      if (normalized) add(`phone:${normalized}`, record);
    }
  }

  const groups = [];
  const seen = new Set();
  for (const [key, items] of buckets) {
    if (items.length < 2) continue;
    const inns = [...new Set(items.map((x) => normalizeInn(x.row?.["ИНН"])).filter(Boolean))];
    const canonicalIds = [...new Set(items.map((x) => x.canonical_id).filter(Boolean))];
    if (inns.length <= 1 && canonicalIds.length <= 1) continue;
    const signature = items.map((x) => x.id).sort().join("|");
    if (seen.has(signature)) continue;
    seen.add(signature);
    groups.push({ key, records: items });
  }
  return groups;
}


function testCandidateGrade(row) {
  const basis = String(row?.["Основание"] || "").trim().toUpperCase();
  if (basis.startsWith("A")) return "A";
  if (basis.startsWith("B")) return "B";
  return "";
}

function buildTestQualificationCandidates(parts) {
  const groups = new Map();
  let sequence = 0;

  for (let stageIndex = 0; stageIndex < parts.length; stageIndex++) {
    for (const row of allResearchRows(parts[stageIndex])) {
      const grade = testCandidateGrade(row);
      if (!grade) continue;

      const org = String(row?.["Организация"] || "").trim();
      const orgKey = normalizeOrgKey(org);
      if (!orgKey) continue;
      const place = String(row?.["Город/район"] || "").trim();
      const placeKey = normalizePlaceKey(place);
      const key = `${orgKey}|${placeKey}`;

      if (!groups.has(key)) {
        sequence++;
        groups.set(key, {
          id: `tq${String(sequence).padStart(5, "0")}`,
          organization: org,
          city: place,
          stages: new Set(),
          grades: new Set(),
          segments: new Set(),
          bases: new Set(),
          source_urls: new Set(),
          notes: new Set()
        });
      }

      const item = groups.get(key);
      item.stages.add(stageIndex + 1);
      item.grades.add(grade);
      if (row?.["Техника/сегмент"]) item.segments.add(String(row["Техника/сегмент"]).trim());
      if (row?.["Основание"]) item.bases.add(String(row["Основание"]).trim());
      for (const url of row?.__evidence?.source_urls || []) {
        if (url) item.source_urls.add(String(url));
      }
      for (const note of row?.__evidence?.notes || []) {
        if (note) item.notes.add(String(note));
      }
    }
  }

  return [...groups.values()].map((item) => ({
    id: item.id,
    organization: item.organization,
    city: item.city,
    stages: [...item.stages].sort(),
    discovery_grades: [...item.grades],
    segments: [...item.segments].slice(0, 8),
    bases: [...item.bases].slice(0, 12),
    evidence: {
      source_urls: [...item.source_urls].slice(0, 12),
      notes: [...item.notes].slice(0, 16)
    }
  }));
}

async function qualifyTestCandidates({ client, candidates, region, assertNotCancelled }) {
  const qualified = [];
  let excluded = 0;

  for (let offset = 0; offset < candidates.length; offset += TEST_QUALIFICATION_BATCH_SIZE) {
    await assertNotCancelled();
    const batch = candidates.slice(offset, offset + TEST_QUALIFICATION_BATCH_SIZE);

    const result = await askJson(client, {
      input: `ПРОВЕРКА КАЧЕСТВА КАНДИДАТОВ ТЕСТА ЭТАПОВ 1–2.
РЕГИОН: ${region}

Оцени ТОЛЬКО переданный evidence. Новый web_search запрещён.
Нужно оставить только компании, которые действительно релевантны продаже прицепной техники САТ.

INCLUDE:
A — есть конкретное подтверждение релевантной прицепной техники, предмета лизинга, VIN/госномера, закупки/ремонта/эксплуатации такой техники.
B — конкретной прицепной техники нет, но evidence подтверждает одновременно реальный целевой груз/процесс И тяжёлую автологистику/эксплуатационный сигнал (собственный или лизинговый тяжёлый парк, тягачи, профильные перевозки, CE-вакансии в релевантном контексте, транспортный контракт, обновление/ремонт парка).

EXCLUDE:
- только отрасль, ОКВЭД или общий профиль компании;
- только целевой груз без подтверждения тяжёлой автологистики;
- только вакансия без достаточной привязки к релевантному процессу;
- посредник/каталог/площадка, ошибочно принятые за конечного пользователя, если нет собственной эксплуатации;
- лизингодатель без релевантной роли для нашего списка;
- evidence не подтверждает заявленный A/B;
- связь основана на предположении.

Для каждого входного id верни ровно одно решение. При сомнении EXCLUDE.
reason — коротко и конкретно, какой факт делает компанию подходящей либо почему evidence недостаточно.
Не добавляй никаких новых фактов.

КАНДИДАТЫ:
${JSON.stringify(batch)}`,
      model: FINAL_QA_MODEL,
      maxOutputTokens: 16000,
      webSearch: false,
      responseSchema: TEST_QUALIFICATION_SCHEMA,
      schemaName: "test12_qualification",
      diagnosticLabel: `test12 qualification | batch ${Math.floor(offset / TEST_QUALIFICATION_BATCH_SIZE) + 1}`
    });

    const byId = new Map(batch.map((x) => [x.id, x]));
    const seen = new Set();
    for (const decision of result?.decisions || []) {
      const id = String(decision?.id || "");
      if (!id || seen.has(id) || !byId.has(id)) continue;
      seen.add(id);
      const source = byId.get(id);

      if (decision.decision === "include" && (decision.grade === "A" || decision.grade === "B")) {
        qualified.push({
          id,
          organization: source.organization,
          city: source.city,
          grade: decision.grade,
          reason: String(decision.reason || "").trim(),
          stages: source.stages,
          segments: source.segments,
          source_urls: source.evidence.source_urls.slice(0, 3)
        });
      } else {
        excluded++;
      }
    }

    // Missing decision = conservative exclude.
    excluded += batch.length - seen.size;
  }

  qualified.sort((a, b) => {
    if (a.grade !== b.grade) return a.grade === "A" ? -1 : 1;
    return a.organization.localeCompare(b.organization, "ru");
  });

  for (const company of qualified) {
    console.log("[TEST12_QUALIFIED_COMPANY] " + JSON.stringify({
      id: company.id,
      organization: company.organization,
      city: company.city,
      grade: company.grade,
      reason: company.reason,
      stages: company.stages,
      segments: company.segments,
      source_urls: company.source_urls
    }));
  }

  console.log("[TEST12_QUALIFICATION] " + JSON.stringify({
    candidates: candidates.length,
    qualified: qualified.length,
    excluded
  }));

  return { qualified, excluded };
}

function initialStatuses() {
  return STEPS.map((name, index) => ({
    step: index + 1,
    name,
    status: "waiting",
    detail: "",
    startedAt: null,
    completedAt: null
  }));
}

function startStep(status) {
  status.status = "running";
  status.startedAt = Date.now();
  status.completedAt = null;
}

function finishStep(status) {
  status.status = "done";
  status.completedAt = Date.now();
}

function mergePhone(current, found) {
  const parts = String(current || "")
    .split(";")
    .concat(String(found || "").split(";"))
    .map((x) => x.trim())
    .filter(Boolean);
  return [...new Set(parts)].join(";");
}

function applyContact(row, contact) {
  if (contact?.phone) row["Телефон"] = mergePhone(row["Телефон"], contact.phone);
  if (contact?.leader) row["Руководитель / ЛПР"] = contact.leader;
}

function normalizePhoneDigits(value) {
  let digits = String(value || "").replace(/\D/g, "");
  if (digits.length === 11 && digits.startsWith("8")) digits = "7" + digits.slice(1);
  if (digits.length === 10) digits = "7" + digits;
  return digits.length === 11 && digits.startsWith("7") ? digits : "";
}

function splitPhoneEntries(value) {
  return String(value || "")
    .split(";")
    .map((x) => x.trim())
    .filter(Boolean);
}

function buildPhoneOwnerMap(rows) {
  const map = new Map();
  for (const row of rows) {
    for (const entry of splitPhoneEntries(row["Телефон"])) {
      const normalized = normalizePhoneDigits(entry);
      if (!normalized) continue;
      if (!map.has(normalized)) map.set(normalized, []);
      map.get(normalized).push(row);
    }
  }
  return map;
}

function filterAlreadyInCurrentCell(currentValue, candidateValue) {
  const existing = new Set(
    splitPhoneEntries(currentValue)
      .map(normalizePhoneDigits)
      .filter(Boolean)
  );
  return splitPhoneEntries(candidateValue).filter((entry) => {
    const normalized = normalizePhoneDigits(entry);
    return normalized && !existing.has(normalized);
  });
}

function hasConfirmedPhone(row) {
  return splitPhoneEntries(row?.["Телефон"]).some((entry) => Boolean(normalizePhoneDigits(entry)));
}

function hasConfirmedLeader(row) {
  return Boolean(String(row?.["Руководитель / ЛПР"] || "").trim());
}

function needsGoogleResearch(row) {
  return !hasConfirmedPhone(row) || !hasConfirmedLeader(row);
}

function isPriorityAB(row) {
  const basis = String(row?.["Основание"] || "").trim().toUpperCase();
  return basis.startsWith("A") || basis.startsWith("B");
}

const TEST_PROFILES = {
  smoke: {
    stageLimit: 1,
    branchIndexes: { 0: [0, 1] },
    scopeLimit: 1,
    recovery: false,
    identityWebSearch: false
  },
  quality: {
    stageLimit: 2,
    branchIndexes: {
      0: [0, 1, 2, 5],
      1: [0, 2, 5]
    },
    scopeLimit: 2,
    recovery: false,
    identityWebSearch: true
  },
  test12: {
    stageLimit: 2,
    branchIndexes: null,
    scopeLimit: null,
    recovery: true,
    identityWebSearch: true
  },
  replay: {
    stageLimit: 0,
    branchIndexes: null,
    scopeLimit: 0,
    recovery: false,
    identityWebSearch: false
  },
  dedupe_replay: {
    stageLimit: 0,
    branchIndexes: null,
    scopeLimit: 0,
    recovery: false,
    identityWebSearch: false
  }
};

function testProfileForMode(mode, stageNumber = null) {
  if (mode === "stage_test") {
    const stage = Number(stageNumber);
    if (!Number.isInteger(stage) || stage < 1 || stage > 9) return null;
    return {
      stageLimit: 9,
      stageIndexes: [stage - 1],
      branchIndexes: null,
      scopeLimit: null,
      recovery: true,
      identityWebSearch: true,
      stageNumber: stage
    };
  }
  return TEST_PROFILES[mode] || null;
}

function discoverySnapshot(
  region,
  parts,
  sourceMode,
  identityCheckpoint = null,
  dedupeCheckpoint = null,
  qualificationCheckpoint = null
) {
  return {
    version: 4,
    region,
    source_mode: sourceMode,
    created_at: new Date().toISOString(),
    parts,
    identity_checkpoint: identityCheckpoint,
    dedupe_checkpoint: dedupeCheckpoint,
    qualification_checkpoint: qualificationCheckpoint
  };
}

const PIPELINE_CHECKPOINT_VERSION = 1;
const PIPELINE_PHASE_ORDER = {
  starting: 0,
  discovery: 1,
  pre_identity: 2,
  identity: 3,
  final_batches: 4,
  dedupe: 5,
  qualification: 6,
  final_inn: 7,
  enrichment: 8,
  statistics: 9,
  contacts: 10,
  completed: 11
};

function cloneJson(value) {
  return value === undefined ? undefined : JSON.parse(JSON.stringify(value));
}

function checkpointPhaseAtLeast(checkpoint, phase) {
  return Number(PIPELINE_PHASE_ORDER[String(checkpoint?.phase || "")] || 0) >=
    Number(PIPELINE_PHASE_ORDER[phase] || 0);
}

function checkpointRowId(row) {
  return String(row?.__canonical_id || "").trim() ||
    [normalizeOrgKey(row?.["Организация"]), normalizePlaceKey(row?.["Город/район"])]
      .filter(Boolean)
      .join("|");
}

function checkpointSummaryForLog(checkpoint) {
  return {
    version: checkpoint?.version,
    phase: checkpoint?.phase,
    completed_stage: Number(checkpoint?.completed_stage || 0),
    completed_final_batches: Number(checkpoint?.completed_final_batches || 0),
    final_inn_completed: Array.isArray(checkpoint?.final_inn_completed_ids)
      ? checkpoint.final_inn_completed_ids.length : 0,
    final_inn_removed_without_inn: Number(checkpoint?.final_inn_removed_without_inn || 0),
    enrichment_completed: Array.isArray(checkpoint?.enrichment_completed_ids)
      ? checkpoint.enrichment_completed_ids.length : 0,
    contacts_completed: Array.isArray(checkpoint?.contact_completed_ids)
      ? checkpoint.contact_completed_ids.length : 0,
    updated_at: checkpoint?.updated_at || null
  };
}

export async function runResearchPipeline({ job, apiKey }) {
  if (!apiKey) throw new Error("OpenAI API key is required");

  const client = new OpenAI({ apiKey });
  client.__tokenUsage = emptyTokenUsage();
  client.__webUsage = { total: 0, by_scope: {} };
  const jobSignal = job.abortController?.signal;
  client.__jobSignal = jobSignal;
  const region = String(job.region || job.data?.region || "").trim();
  const mode = String(job.mode || "full");
  const resumeCheckpoint =
    mode === "resume" && job.data?.checkpoint?.version === PIPELINE_CHECKPOINT_VERSION
      ? cloneJson(job.data.checkpoint)
      : null;
  const executionMode = mode === "resume" ? "full" : mode;
  const requestedStage = Number(job.data?.stage || 0);
  const testProfile = testProfileForMode(executionMode, requestedStage);
  const diagnosticMode = Boolean(testProfile);
  const replayMode = executionMode === "replay";
  const dedupeReplayMode = executionMode === "dedupe_replay";
  const researchStageLimit = diagnosticMode ? testProfile.stageLimit : 9;
  const researchStageIndexes = Array.isArray(testProfile?.stageIndexes)
    ? testProfile.stageIndexes
    : Array.from({ length: researchStageLimit }, (_, index) => index);
  const diagnosticStep = mode === "stage_test" ? requestedStage : 2;
  if (mode === "quality") client.__webBudget = createQualityWebBudget();
  else if (mode === "full" || mode === "resume") client.__webBudget = createFullWebBudget();
  if (!region) throw new Error("Region is required");

  const statuses = initialStatuses();
  const progress = async (patch = {}) => {
    await job.updateProgress({
      statuses,
      region,
      ...patch
    });
  };

  const checkpointState = resumeCheckpoint || {
    version: PIPELINE_CHECKPOINT_VERSION,
    region,
    source_mode: "full",
    phase: "starting",
    completed_stage: 0,
    parts: [],
    created_at: new Date().toISOString()
  };

  const persistCheckpoint = async (phase, patch = {}) => {
    Object.assign(checkpointState, cloneJson(patch), {
      version: PIPELINE_CHECKPOINT_VERSION,
      region,
      source_mode: "full",
      phase,
      updated_at: new Date().toISOString()
    });
    if (!checkpointState.created_at) checkpointState.created_at = checkpointState.updated_at;
    if (typeof job.updateCheckpoint === "function") {
      await job.updateCheckpoint(checkpointState);
    }
    console.log("[PIPELINE_CHECKPOINT] " + JSON.stringify({
      job_id: job.id || "",
      ...checkpointSummaryForLog(checkpointState)
    }));
  };

  const assertNotCancelled = async () => {
    if (job.cancelled || jobSignal?.aborted) throw new Error("JOB_CANCELLED");
  };

  const abortableSleep = (ms) =>
    new Promise((resolve, reject) => {
      if (jobSignal?.aborted) return reject(new Error("JOB_CANCELLED"));
      const timer = setTimeout(resolve, ms);
      if (jobSignal) {
        jobSignal.addEventListener(
          "abort",
          () => {
            clearTimeout(timer);
            reject(new Error("JOB_CANCELLED"));
          },
          { once: true }
        );
      }
    });

  await progress({ phase: "starting", percent: 0 });
  if (!resumeCheckpoint) {
    await persistCheckpoint("starting", { parts: [] });
  } else {
    console.log("[PIPELINE_RESUME] " + JSON.stringify({
      job_id: job.id || "",
      source_job_id: job.data?.sourceJobId || "",
      checkpoint: checkpointSummaryForLog(resumeCheckpoint)
    }));
  }

  if (dedupeReplayMode) {
    const snapshot = job.data?.snapshot;
    const identityCheckpoint = snapshot?.identity_checkpoint;
    if (
      !snapshot ||
      ![2, 3, 4].includes(snapshot.version) ||
      !Array.isArray(identityCheckpoint?.candidates)
    ) {
      throw new Error("Dedupe replay требует snapshot с identity checkpoint");
    }

    await progress({
      phase: "dedupe",
      step: 2,
      percent: 40,
      qualificationDetail: "dedupe replay · frozen identity checkpoint"
    });

    const canonicalPool = canonicalizeCandidates(identityCheckpoint.candidates, region);
    const stagedTest = { direct_buyers: [], intermediaries: [], leasing: [] };
    for (const canonical of canonicalPool) {
      const row = baselineRowFromCanonical(canonical);
      const sheet = preferredSheetForCanonical(canonical);
      stagedTest[sheet].push(row);
    }

    const beforeDedupe = makeQaRecords(stagedTest);
    const diagnostics = { merges: [] };
    const qaRecords = deterministicGlobalDedupe(beforeDedupe, diagnostics, region);
    const previousRecords = Array.isArray(snapshot?.dedupe_checkpoint?.records)
      ? snapshot.dedupe_checkpoint.records
      : [];

    const comparison = {
      identity_candidates: identityCheckpoint.candidates.length,
      canonical_before_dedupe: beforeDedupe.length,
      previous_after_dedupe: previousRecords.length || null,
      current_after_dedupe: qaRecords.length,
      previous_removed: previousRecords.length
        ? beforeDedupe.length - previousRecords.length
        : null,
      current_removed: beforeDedupe.length - qaRecords.length,
      delta_after: previousRecords.length
        ? qaRecords.length - previousRecords.length
        : null,
      merge_groups: diagnostics.merges.length,
      merges: diagnostics.merges
    };

    console.log("[DEDUPE_REPLAY_SUMMARY] " + JSON.stringify(comparison));
    await progress({
      phase: "completed",
      step: 2,
      percent: 100,
      qualificationDetail:
        `dedupe replay · ${beforeDedupe.length} → ${qaRecords.length} · merge-групп: ${diagnostics.merges.length}`
    });

    return {
      mode,
      region,
      result: { direct_buyers: [], intermediaries: [], leasing: [], statistics: [] },
      counts: {
        raw_mentions: identityCheckpoint.candidates.length,
        canonical_after_inn: beforeDedupe.length,
        after_global_dedupe: qaRecords.length,
        dedupe_removed: beforeDedupe.length - qaRecords.length,
        dedupe_merge_groups: diagnostics.merges.length
      },
      dedupe_comparison: comparison,
      qualified_companies: [],
      replay_comparison: null,
      discovery_snapshot: discoverySnapshot(
        region,
        Array.isArray(snapshot.parts) ? snapshot.parts : [],
        snapshot.source_mode || "dedupe_replay",
        identityCheckpoint,
        { version: DEDUPE_CHECKPOINT_VERSION, records: qaRecords },
        snapshot.qualification_checkpoint || null
      ),
      contacts: { total: 0, checked: 0, skipped: 0, ok: 0, unavailable: 0, notFound: 0 }
    };
  }

  const prompts = await Promise.all(Array.from({ length: 10 }, (_, i) => loadPrompt(i + 1)));
  let parts = resumeCheckpoint && Array.isArray(resumeCheckpoint.parts)
    ? cloneJson(resumeCheckpoint.parts)
    : [];
  const completedDiscoveryStage = resumeCheckpoint
    ? Math.max(0, Math.min(9, Number(resumeCheckpoint.completed_stage || 0)))
    : 0;
  for (let index = 0; index < completedDiscoveryStage; index++) {
    if (!parts[index]) continue;
    statuses[index].status = "done";
    statuses[index].detail =
      `восстановлен из checkpoint · ${rowCount(parts[index])} записей · ${uniqueResearchCount(parts[index])} уникальных`;
    statuses[index].completedAt = Date.now();
  }
  const compactCourtArchive = COURT_VECTOR_STORE_ID ? [] : courtArchiveCandidates(region, 180);
  const compactCourtArchiveMeta = COURT_VECTOR_STORE_ID ? null : courtArchiveStats();

  if (replayMode) {
    const snapshot = job.data?.snapshot;
    if (!snapshot || ![1, 2, 3, 4].includes(snapshot.version) || !Array.isArray(snapshot.parts)) {
      throw new Error("Replay snapshot отсутствует или имеет неподдерживаемый формат");
    }
    parts = snapshot.parts;
    console.log("[REPLAY_SNAPSHOT] " + JSON.stringify({
      region,
      source_mode: snapshot.source_mode || "",
      snapshot_version: snapshot.version,
      has_identity_checkpoint: Array.isArray(snapshot.identity_checkpoint?.candidates),
      has_dedupe_checkpoint: Array.isArray(snapshot.dedupe_checkpoint?.records),
      has_qualification_checkpoint: Array.isArray(snapshot.qualification_checkpoint?.records),
      parts: parts.length,
      rows: parts.reduce((sum, part) => sum + rowCount(part), 0)
    }));
    await progress({ phase: "qualification", step: Math.min(2, parts.length || 1), percent: 90 });
  }

  let researchScopes = [];
  if (!replayMode) {
    researchScopes = Array.isArray(resumeCheckpoint?.research_scopes)
      ? cloneJson(resumeCheckpoint.research_scopes)
      : executionMode === "smoke"
        ? [`весь регион: ${region}`]
        : await discoverRegionSearchScopes(client, region);

    if (testProfile?.scopeLimit) {
      researchScopes = researchScopes.slice(0, testProfile.scopeLimit);
    }

    console.log("[RESEARCH_SCOPES] " + JSON.stringify({
      region,
      mode: executionMode,
      resumed: Boolean(resumeCheckpoint),
      scopes: researchScopes
    }));
  }

  const pendingResearchStageIndexes = !replayMode
    ? researchStageIndexes.filter((index) => index >= completedDiscoveryStage)
    : [];

  for (const i of pendingResearchStageIndexes) {
    await assertNotCancelled();
    startStep(statuses[i]);
    const stageTokenStart = tokenUsageSnapshot(client);
    const stageWebStart = webUsageSnapshot(client);

    const combined = emptyResearchResult();

    const compactCourtArchiveContext =
      i === 6 && !COURT_VECTOR_STORE_ID && compactCourtArchive.length
        ? `\n\nПОЛЬЗОВАТЕЛЬСКИЙ АРХИВ СУДЕБНЫХ АКТОВ — discovery-кандидаты:
Архив содержит ${compactCourtArchiveMeta?.documents || 10109} документов. Для выбранного региона компактный индекс дал:
${JSON.stringify(compactCourtArchive)}
Не добавляй организацию только из-за присутствия в этом списке. Используй список для поиска конкретного дела через web_search/официальный судебный источник и возвращай организацию только после подтверждения транспортно-релевантных обстоятельств.`
        : "";

    if (i === 6 && COURT_VECTOR_STORE_ID) {
      const archiveThemes = [
        "превышение массы и осевой нагрузки, автоматический весогабаритный контроль, ущерб дорогам, статья 12.21.1 КоАП",
        "тягачи, полуприцепы и прицепы, VIN, госномера, собственник, перевозчик, фактический эксплуатант",
        "лизинг, изъятие и возврат техники, ремонт полуприцепов, ДТП и страховые споры с идентификацией транспорта"
      ];

      for (let archivePass = 0; archivePass < archiveThemes.length; archivePass++) {
        await assertNotCancelled();
        const alreadyFound = foundOrganizationNames(combined, 300);
        statuses[i].detail = `судебный архив · ${archivePass + 1} / ${archiveThemes.length}`;
        await progress({ phase: "research", step: i + 1, percent: i * 9 });

        const archiveOutput = normalize(
          await askCourtArchive(
            client,
            prompts[i] +
              contract(false) +
              "\n\n" +
              courtArchiveInstruction(archiveThemes[archivePass], region, alreadyFound)
          )
        );
        console.log("[DISCOVERY_ARCHIVE_RESULT] " + JSON.stringify({
          stage: i + 1,
          archive_pass: archivePass + 1,
          theme: archiveThemes[archivePass],
          rows: diagnosticRowCount(archiveOutput),
          token_usage_cumulative: tokenUsageSnapshot(client)
        }));
        console.log("[DISCOVERY_ARCHIVE_COMPANIES_SAMPLE] " + JSON.stringify({
          stage: i + 1,
          archive_pass: archivePass + 1,
          sample: diagnosticDiscoveryRows(archiveOutput).slice(0, 10)
        }));
        appendResearchResult(combined, archiveOutput, `archive-${archivePass + 1}`);
      }
    }

    const allBranches = STAGE_SEARCH_BRANCHES[i] || [];
    const selectedIndexes = testProfile?.branchIndexes?.[i];
    const branches = Array.isArray(selectedIndexes)
      ? selectedIndexes.map((index) => allBranches[index]).filter(Boolean)
      : allBranches;
    let stageBudgetStopped = false;
    const branchDiagnostics = [];
    for (let branchIndex = 0; branchIndex < branches.length; branchIndex++) {
      await assertNotCancelled();
      const before = uniqueResearchCount(combined);
      statuses[i].detail =
        `ветка ${branchIndex + 1} / ${branches.length} · adaptive geo-scope · ${before} уникальных`;
      await progress({
        phase: "research",
        step: i + 1,
        percent: i * 9 + Math.floor((branchIndex / Math.max(1, branches.length)) * 8)
      });

      const extraContext = [
        compactCourtArchiveContext,
        i === 6 && COURT_VECTOR_STORE_ID
          ? "До web-поиска по судам уже выполнен file_search по пользовательскому архиву. Перепроверяй найденные там организации и дела через официальные источники."
          : ""
      ].filter(Boolean).join("\n");

      const alreadyFound = discoveryKnownNames(combined);
      const branchScopes = discoveryScopesForBranch(i, branchIndex, researchScopes);
      const branchWebStart = webUsageSnapshot(client);
      let branchResult;
      try {
        branchResult = await runResearchMicroBatch({
          client,
          region,
          stageIndex: i,
          branch: branches[branchIndex],
          branchIndex,
          branches,
          scopes: researchScopes,
          extraContext,
          alreadyFound
        });
      } catch (error) {
        if (!isWebBudgetStop(error)) throw error;
        stageBudgetStopped = true;
        statuses[i].detail =
          `web budget достигнут · ${uniqueResearchCount(combined)} уникальных · переходим дальше`;
        console.log("[QUALITY_STAGE_BUDGET_STOP] " + JSON.stringify({
          stage: i + 1,
          scope: error.scope,
          used: error.used,
          limit: error.limit,
          total_used: error.totalUsed,
          total_limit: error.totalLimit
        }));
        break;
      }
      appendResearchResult(combined, branchResult, `branch-${branchIndex + 1}`);
      const after = uniqueResearchCount(combined);
      const branchYield = discoveryYieldStats(branchResult, alreadyFound);
      const branchWebCalls = Math.max(0, webUsageSnapshot(client) - branchWebStart);
      const branchEconomics = webYieldMetrics(
        branchWebCalls,
        Math.max(0, after - before),
        branchYield.strongNew
      );
      console.log("[DISCOVERY_BRANCH_RESULT] " + JSON.stringify({
        stage: i + 1,
        branch: branchIndex + 1,
        branch_name: branches[branchIndex],
        rows: diagnosticRowCount(branchResult),
        unique_in_branch: uniqueResearchCount(branchResult),
        marginal_new: Math.max(0, after - before),
        quality_yield: branchYield,
        ...branchEconomics,
        token_usage_cumulative: tokenUsageSnapshot(client)
      }));
      console.log("[DISCOVERY_BRANCH_COMPANIES_SAMPLE] " + JSON.stringify({
        stage: i + 1,
        branch: branchIndex + 1,
        sample: diagnosticDiscoveryRows(branchResult).slice(0, 10)
      }));

      branchDiagnostics.push({
        branchIndex,
        branch: branches[branchIndex],
        rows: diagnosticRowCount(branchResult),
        uniqueInBranch: uniqueResearchCount(branchResult),
        marginalNew: Math.max(0, after - before),
        qualityScore: branchYield.qualityScore,
        strongNew: branchYield.strongNew,
        preliminaryA: branchYield.a,
        preliminaryB: branchYield.b,
        preliminaryC: branchYield.c,
        sourceFamilies: discoverySourceFamilyStats(branchResult),
        ...branchEconomics
      });
      statuses[i].detail =
        `ветка ${branchIndex + 1} / ${branches.length} · до ${branchScopes.length} geo-scope · +${Math.max(0, after - before)} новых · ${after} уникальных`;
      await progress({
        phase: "research",
        step: i + 1,
        percent: i * 9 + Math.floor(((branchIndex + 1) / Math.max(1, branches.length)) * 8)
      });
    }

    // Recovery should deepen branches that have already proven they can yield
    // strong A/B evidence, not spend the safety-net budget on branches producing
    // almost exclusively weak C rows. If at least two branches have >=2 strong
    // discoveries, prioritize those; otherwise fall back to all branches.
    const recoverableBranches = branchDiagnostics.filter(
      (item) =>
        Number(item.strongNew || 0) >= 2 &&
        !recoveryBranchIsSaturated(i, item)
    );
    const recoveryPool = stageRecoveryEvidenceOriented(i)
      ? recoverableBranches
      : recoverableBranches.length >= 2 ? recoverableBranches : branchDiagnostics;
    const recoveryBranchOrder = [...recoveryPool]
      .sort((a, b) => {
        const aStrong = Number(a.strongNew || 0);
        const bStrong = Number(b.strongNew || 0);
        const aRows = Math.max(1, Number(a.uniqueInBranch || a.rows || 1));
        const bRows = Math.max(1, Number(b.uniqueInBranch || b.rows || 1));
        const aShare = aStrong / aRows;
        const bShare = bStrong / bRows;

        // Prefer proven but still under-covered branches: fewer absolute strong
        // finds first, then better strong-evidence density. This avoids wasting
        // recovery on nearly all-C branches while still seeking missing long tail.
        return (
          aStrong - bStrong ||
          bShare - aShare ||
          Number(a.qualityScore || 0) - Number(b.qualityScore || 0) ||
          Number(a.branchIndex || 0) - Number(b.branchIndex || 0)
        );
      });

    // Recovery is a safety net for under-covered branches, not a second full
    // traversal of every branch. Scale the number of recovery themes with
    // stage breadth: roughly one recovery branch per four primary branches,
    // while respecting the configured global ceiling.
    const adaptiveRecoveryLimit = recoveryPool.length
      ? Math.max(
          1,
          Math.min(
            stageRecoveryEvidenceOriented(i) ? 1 : RESEARCH_MAX_RECOVERY_BRANCHES,
            RESEARCH_MAX_RECOVERY_BRANCHES,
            Math.ceil(Math.max(1, branches.length) / 4)
          )
        )
      : 0;

    console.log("[DISCOVERY_BRANCH_COVERAGE] " + JSON.stringify({
      stage: i + 1,
      branches: branchDiagnostics,
      recovery_limit: adaptiveRecoveryLimit,
      recovery_policy: stageRecoveryEvidenceOriented(i)
        ? "evidence_oriented_saturation_stop"
        : "breadth_oriented",
      configured_recovery_limit: RESEARCH_MAX_RECOVERY_BRANCHES,
      recovery_pool: recoveryBranchOrder.map((item) => ({
        branchIndex: item.branchIndex,
        strongNew: item.strongNew,
        qualityScore: item.qualityScore,
        uniqueInBranch: item.uniqueInBranch
      }))
    }));

    let lowYieldStreak = 0;
    let previousRecovery = null;
    for (
      let recoveryIndex = 0;
      !stageBudgetStopped &&
      (!testProfile || testProfile.recovery) &&
      recoveryIndex < adaptiveRecoveryLimit &&
      lowYieldStreak < 2;
      recoveryIndex++
    ) {
      await assertNotCancelled();
      const before = uniqueResearchCount(combined);
      const recoveryWebStart = webUsageSnapshot(client);
      const alreadyFound = foundOrganizationNames(combined, 80);
      const theme = RESEARCH_RECOVERY_THEMES[recoveryIndex % RESEARCH_RECOVERY_THEMES.length];
      const orderedBranch =
        recoveryBranchOrder[recoveryIndex % Math.max(1, recoveryBranchOrder.length)] ||
        { branchIndex: 0, branch: branches[0] || DISCOVERY_STAGE_HINTS[i] || "" };
      let recoveryBranch = orderedBranch;
      let recoveryStrategy = "next_proven_branch";

      if (recoveryIndex > 0 && previousRecovery) {
        const prevNew = Math.max(1, Number(previousRecovery.qualityYield.newOrganizations || 1));
        const prevStrong = Number(previousRecovery.qualityYield.strongNew || 0);
        const prevStrongShare = prevStrong / prevNew;
        if (prevStrong >= 3 && prevStrongShare >= 0.3) {
          recoveryBranch = previousRecovery.branch;
          recoveryStrategy = "deepen_previous_strong_recovery";
        } else {
          const nextStrong = Number(orderedBranch.strongNew || 0);
          const nextRows = Math.max(1, Number(orderedBranch.uniqueInBranch || orderedBranch.rows || 1));
          const nextStrongShare = nextStrong / nextRows;
          if (nextStrong < 4 || nextStrongShare < 0.35) {
            console.log("[DISCOVERY_RECOVERY_SKIP] " + JSON.stringify({
              stage: i + 1,
              recovery: recoveryIndex + 1,
              reason: "no_strong_followup",
              previous_strong: prevStrong,
              previous_new: prevNew,
              next_branch: orderedBranch.branchIndex + 1,
              next_strong: nextStrong,
              next_rows: nextRows
            }));
            break;
          }
        }
      }

      const anchorBranch = recoveryBranch.branch || DISCOVERY_STAGE_HINTS[i] || "";
      const sourceFamilyGaps = discoverySourceFamilyGaps(recoveryBranch.sourceFamilies, 3);
      const saturatedSourceFamilies = discoverySaturatedSourceFamilies(
        recoveryBranch.sourceFamilies,
        4
      );

      statuses[i].detail =
        `добор ${recoveryIndex + 1} · ветка ${recoveryBranch.branchIndex + 1} · ${before} уникальных · проверяем насыщение`;
      await progress({ phase: "research", step: i + 1, percent: i * 9 + 8 });

      let successes = 0;
      let recoveryScopeLowYield = 0;
      const recoveryKnown = [...alreadyFound];
      const recoveryScopes = discoveryScopesForBranch(
        i,
        recoveryBranch.branchIndex,
        researchScopes
      );
      const recoveryYieldAggregate = {
        newOrganizations: 0,
        a: 0,
        b: 0,
        c: 0,
        ungraded: 0,
        strongNew: 0,
        qualityScore: 0,
        sourceFamilyNovelty: 0
      };
      let recoveryRegionalYield = null;
      let recoveryFirstLocalYield = null;
      let recoveryRegionalFamilies = {};
      let recoveryPreviousFamilies = {};

      for (let scopeIndex = 0; scopeIndex < recoveryScopes.length; scopeIndex++) {
        await assertNotCancelled();
        if (
          scopeIndex >= 2 &&
          recoveryFirstLocalYield &&
          !discoveryGeoExpansionWorthwhile(recoveryFirstLocalYield) &&
          !discoveryGeoExpansionWorthwhile(recoveryRegionalYield)
        ) {
          console.log("[DISCOVERY_GEO_EXPANSION_SKIP] " + JSON.stringify({
            stage: i + 1,
            recovery: recoveryIndex + 1,
            anchor_branch: recoveryBranch.branchIndex + 1,
            reason: "regional_and_first_local_scope_not_productive_enough",
            regional_quality_yield: recoveryRegionalYield,
            first_local_quality_yield: recoveryFirstLocalYield,
            skipped_scopes: recoveryScopes.length - scopeIndex
          }));
          break;
        }

        const scope = recoveryScopes[scopeIndex];
        const knownBeforeScope = [...recoveryKnown];

        try {
          const value = normalize(
            await askResearch(
              client,
              compactRecoveryPrompt({
                region,
                stageIndex: i,
                theme,
                scope,
                alreadyFound: recoveryKnown,
                uniqueCount: before,
                anchorBranch,
                sourceFamilyGaps,
                saturatedSourceFamilies
              }),
              RESEARCH_MICRO_MAX_OUTPUT_TOKENS,
              `этап ${i + 1} | recovery ${recoveryIndex + 1} | ветка ${recoveryBranch.branchIndex + 1} | ${theme} | ${scope}`,
              3
            )
          );

          const scopeYield = discoveryYieldStats(value, knownBeforeScope);
          const scopeFamilies = discoverySourceFamilyStats(value);
          scopeYield.sourceFamilyNovelty = discoverySourceFamilyNovelty(
            scopeFamilies,
            scopeIndex === 0 ? {} : recoveryPreviousFamilies
          );
          const addedInScope = scopeYield.newOrganizations;
          if (scopeIndex === 0) {
            recoveryRegionalYield = scopeYield;
            recoveryRegionalFamilies = scopeFamilies;
          }
          if (scopeIndex === 1) {
            scopeYield.sourceFamilyNovelty = discoverySourceFamilyNovelty(
              scopeFamilies,
              recoveryRegionalFamilies
            );
            recoveryFirstLocalYield = scopeYield;
          }
          recoveryPreviousFamilies = scopeFamilies;
          recoveryYieldAggregate.newOrganizations += scopeYield.newOrganizations;
          recoveryYieldAggregate.a += scopeYield.a;
          recoveryYieldAggregate.b += scopeYield.b;
          recoveryYieldAggregate.c += scopeYield.c;
          recoveryYieldAggregate.ungraded += scopeYield.ungraded;
          recoveryYieldAggregate.strongNew += scopeYield.strongNew;
          recoveryYieldAggregate.qualityScore = Number(
            (recoveryYieldAggregate.qualityScore + scopeYield.qualityScore).toFixed(2)
          );
          recoveryYieldAggregate.sourceFamilyNovelty += Number(
            scopeYield.sourceFamilyNovelty || 0
          );
          console.log("[DISCOVERY_RECOVERY_RESULT] " + JSON.stringify({
            stage: i + 1,
            recovery: recoveryIndex + 1,
            anchor_branch: recoveryBranch.branchIndex + 1,
            anchor_branch_name: anchorBranch,
            theme,
            source_family_gaps: sourceFamilyGaps,
            saturated_source_families: saturatedSourceFamilies,
            scope_index: scopeIndex + 1,
            scope,
            rows: diagnosticRowCount(value),
            new_organizations: addedInScope,
            quality_yield: scopeYield,
            source_families: scopeFamilies,
            source_family_novelty: scopeYield.sourceFamilyNovelty,
            token_usage_cumulative: tokenUsageSnapshot(client)
          }));
          console.log("[DISCOVERY_RECOVERY_COMPANIES_SAMPLE] " + JSON.stringify({
            stage: i + 1,
            recovery: recoveryIndex + 1,
            anchor_branch: recoveryBranch.branchIndex + 1,
            scope_index: scopeIndex + 1,
            sample: diagnosticDiscoveryRows(value).slice(0, 10)
          }));
          appendResearchResult(
            combined,
            value,
            `recovery-${recoveryIndex + 1}-scope-${scopeIndex + 1}`
          );
          mergeKnownOrganizationNames(recoveryKnown, value);
          successes++;

          if (scopeIndex > 0) {
            const threshold = adaptiveDiscoveryLowYieldThreshold(recoveryKnown.length);
            const streakLimit = adaptiveDiscoveryLowYieldStreak(recoveryScopes.length);
            recoveryScopeLowYield =
              addedInScope <= threshold || discoveryQualityIsLow(scopeYield)
                ? recoveryScopeLowYield + 1
                : 0;

            if (
              recoveryScopeLowYield >= streakLimit &&
              scopeIndex + 1 < recoveryScopes.length
            ) {
              console.log("[DISCOVERY_SCOPE_STOP] " + JSON.stringify({
                stage: i + 1,
                recovery: recoveryIndex + 1,
                processed_scopes: scopeIndex + 1,
                total_scopes: recoveryScopes.length,
                last_added: addedInScope,
                threshold,
                streak_limit: streakLimit
              }));
              break;
            }
          }
        } catch (error) {
          if (isWebBudgetStop(error)) throw error;
          console.error("[DISCOVERY_RECOVERY_SCOPE_ERROR] " + JSON.stringify({
            stage: i + 1,
            recovery: recoveryIndex + 1,
            scope,
            error: error?.message || String(error)
          }));
        }
      }

      if (!successes) throw new Error(`Все микро-поиски добора этапа ${i + 1} завершились ошибкой`);

      const after = uniqueResearchCount(combined);
      const added = Math.max(0, after - before);
      const recoveryThreshold = adaptiveDiscoveryLowYieldThreshold(before);
      const recoveryLowQuality =
        added <= recoveryThreshold || discoveryQualityIsLow(recoveryYieldAggregate);
      lowYieldStreak = recoveryLowQuality ? lowYieldStreak + 1 : 0;
      const recoveryWebCalls = Math.max(0, webUsageSnapshot(client) - recoveryWebStart);
      console.log("[DISCOVERY_RECOVERY_SUMMARY] " + JSON.stringify({
        stage: i + 1,
        recovery: recoveryIndex + 1,
        anchor_branch: recoveryBranch.branchIndex + 1,
        strategy: recoveryStrategy,
        rows_added: added,
        quality_yield: recoveryYieldAggregate,
        ...webYieldMetrics(recoveryWebCalls, added, recoveryYieldAggregate.strongNew),
        low_yield: recoveryLowQuality,
        threshold: recoveryThreshold
      }));

      previousRecovery = {
        branch: recoveryBranch,
        qualityYield: { ...recoveryYieldAggregate }
      };

      if (lowYieldStreak >= 2) {
        statuses[i].detail = `разумные поисковые направления исчерпаны · ${after} уникальных`;
        break;
      }
    }

    parts[i] = combined;
    finishStep(statuses[i]);
    const stageTokenEnd = tokenUsageSnapshot(client);
    const stageTokenUsage = tokenUsageDelta(stageTokenEnd, stageTokenStart);
    const stageWebCalls = Math.max(0, webUsageSnapshot(client) - stageWebStart);
    const stageStrong = branchDiagnostics.reduce(
      (sum, item) => sum + Number(item.strongNew || 0), 0
    );
    console.log("[DISCOVERY_STAGE_SUMMARY] " + JSON.stringify({
      stage: i + 1,
      region,
      rows: rowCount(combined),
      unique: uniqueResearchCount(combined),
      branches: branches.length,
      branch_coverage: branchDiagnostics,
      ...webYieldMetrics(stageWebCalls, uniqueResearchCount(combined), stageStrong),
      token_usage: stageTokenUsage,
      token_usage_cumulative: stageTokenEnd
    }));
    console.log("[DISCOVERY_STAGE_COMPANIES_SAMPLE] " + JSON.stringify({
      stage: i + 1,
      region,
      sample: diagnosticDiscoveryRows(combined).slice(0, 20)
    }));
    statuses[i].detail =
      `выполнен · ${rowCount(combined)} записей · ${uniqueResearchCount(combined)} уникальных · ${branches.length} веток · tokens: ${stageTokenUsage.total_tokens} · adaptive geo-scope`;
    await progress({ phase: "research", step: i + 1, percent: (i + 1) * 9 });
    await persistCheckpoint("discovery", {
      completed_stage: i + 1,
      parts,
      research_scopes: researchScopes,
      web_usage_total: webUsageSnapshot(client)
    });
  }

  if (diagnosticMode) {
    const totalRows = parts.reduce((sum, part) => sum + rowCount(part), 0);
    const combinedTest = emptyResearchResult();
    for (const part of parts) appendResearchResult(combinedTest, part, "test-summary");
    const discoveryUnique = uniqueResearchCount(combinedTest);

    await assertNotCancelled();
    await progress({ phase: "qualification", step: diagnosticStep, percent: 92 });

    const candidatePool = flattenCandidates(parts);
    const replayCheckpoint = replayMode && Array.isArray(job.data?.snapshot?.identity_checkpoint?.candidates)
      ? job.data.snapshot.identity_checkpoint
      : null;

    let identityResolution;
    let reviewCandidates = [];
    if (replayCheckpoint) {
      identityResolution = {
        candidates: replayCheckpoint.candidates,
        clusters: Number(replayCheckpoint.clusters || 0),
        confirmedInnMentions: Number(replayCheckpoint.confirmedInnMentions || 0),
        failedClusters: Number(replayCheckpoint.failedClusters || 0),
        skippedWebClusters: Number(replayCheckpoint.skippedWebClusters || replayCheckpoint.clusters || 0),
        searchedWebClusters: 0
      };
      console.log("[REPLAY_IDENTITY_CHECKPOINT] " + JSON.stringify({
        candidates: identityResolution.candidates.length,
        clusters: identityResolution.clusters,
        source_searched_web_clusters: Number(replayCheckpoint.searchedWebClusters || 0)
      }));
      await progress({
        phase: "qualification",
        step: diagnosticStep,
        percent: 94,
        qualificationDetail:
          `identity checkpoint · ${identityResolution.candidates.length} resolved mentions · без повторного identity`
      });
    } else {
      const preIdentity = prefilterCandidatesForIdentity(candidatePool, region);
      reviewCandidates = preIdentity.reviewCandidates;
      identityResolution = await resolveCandidateIdentities({
        client,
        candidates: preIdentity.candidates,
        region,
        prompt: prompts[9],
        assertNotCancelled,
        onProgress: async ({ completed, total, confirmedInnMentions, failedClusters, skippedWebClusters, searchedWebClusters }) => {
          await progress({
            phase: "qualification",
            step: diagnosticStep,
            percent: 92 + Math.floor((completed / Math.max(1, total)) * 2),
            qualificationDetail:
              `identity ${completed}/${total}; ИНН: ${confirmedInnMentions}; без web: ${skippedWebClusters || 0}; с web: ${searchedWebClusters || 0}` +
              (failedClusters ? `; ошибок: ${failedClusters}` : "")
          });
        },
        allowWebSearch: testProfile?.identityWebSearch !== false
      });
    }

    identityResolution.candidates = appendReviewCandidates(
      identityResolution.candidates, reviewCandidates, region, "diagnostic"
    );
    const canonicalPool = canonicalizeCandidates(identityResolution.candidates, region);
    const canonicalMap = new Map(canonicalPool.map((x) => [x.canonical_id, x]));
    const stagedTest = { direct_buyers: [], intermediaries: [], leasing: [] };

    for (const canonical of canonicalPool) {
      const row = baselineRowFromCanonical(canonical);
      const sheet = preferredSheetForCanonical(canonical);
      stagedTest[sheet].push(row);
    }

    let qaRecords;
    // Replay must preserve the exact post-dedupe input captured by the source run.
    // The checkpoint version describes the algorithm that produced the snapshot;
    // it must not force a re-dedupe when we are measuring qualification stability.
    const replayDedupeCheckpoint =
      replayMode && Array.isArray(job.data?.snapshot?.dedupe_checkpoint?.records)
        ? job.data.snapshot.dedupe_checkpoint
        : null;

    if (replayDedupeCheckpoint) {
      qaRecords = replayDedupeCheckpoint.records;
      console.log("[REPLAY_DEDUPE_CHECKPOINT] " + JSON.stringify({
        records: qaRecords.length,
        checkpoint_version: Number(replayDedupeCheckpoint.version || 0),
        current_dedupe_version: DEDUPE_CHECKPOINT_VERSION,
        version_mismatch:
          Number(replayDedupeCheckpoint.version || 0) !== DEDUPE_CHECKPOINT_VERSION,
        source_mode: job.data?.snapshot?.source_mode || ""
      }));
    } else {
      const beforeDedupe = makeQaRecords(stagedTest);
      qaRecords = deterministicGlobalDedupe(beforeDedupe, null, region);
      if (replayMode) {
        console.log("[REPLAY_DEDUPE_CHECKPOINT_MISSING] " + JSON.stringify({
          before: beforeDedupe.length,
          after: qaRecords.length,
          current_dedupe_version: DEDUPE_CHECKPOINT_VERSION
        }));
      }
      console.log("[DETERMINISTIC_GLOBAL_DEDUPE] " + JSON.stringify({
        before: beforeDedupe.length,
        after: qaRecords.length,
        removed: beforeDedupe.length - qaRecords.length
      }));
    }

    await progress({
      phase: "qualification",
      step: diagnosticStep,
      percent: 95,
      qualificationDetail: replayDedupeCheckpoint
        ? `global dedupe checkpoint: ${qaRecords.length} canonical-строк · frozen replay input`
        : `global dedupe: ${qaRecords.length} canonical-строк · deterministic`
    });

    await progress({
      phase: "qualification",
      step: diagnosticStep,
      percent: 97,
      qualificationDetail: `финальная A/B/C: ${qaRecords.length} уникальных строк`
    });

    const decisions = await runFinalQualification({
      client,
      records: qaRecords,
      region,
      assertNotCancelled,
      diagnosticPrefix: "test12 final qualification"
    });
    const qualified = applyFinalQualification(qaRecords, decisions);
    let excludedAuditCount = 0;
    for (const record of qaRecords) {
      const decision = decisions.get(record.id);
      if (decision?.grade && decision?.decision === "include") continue;
      const row = record.row || {};
      console.log("[FINAL_EXCLUDED_COMPANY] " + JSON.stringify({
        id: record.id,
        organization: row["Организация"] || "",
        city: row["Город/район"] || "",
        sheet: record.sheet,
        reason: decision?.reason || "",
        segment: row["Техника/сегмент"] || "",
        basis: row["Основание"] || "",
        evidence_notes: (row.__evidence?.notes || []).slice(0, 5),
        source_urls: (row.__evidence?.source_urls || []).slice(0, 5)
      }));
      excludedAuditCount++;
    }
    console.log("[FINAL_EXCLUDED_AUDIT_SUMMARY] " + JSON.stringify({
      region,
      excluded: excludedAuditCount,
      no_additional_search: true
    }));
    const currentQualificationCheckpoint = buildQualificationCheckpoint(qaRecords, decisions);
    const replayQualificationComparison =
      replayMode && Array.isArray(job.data?.snapshot?.qualification_checkpoint?.records)
        ? compareQualificationCheckpoints(
            job.data.snapshot.qualification_checkpoint,
            currentQualificationCheckpoint
          )
        : null;

    if (replayQualificationComparison) {
      console.log("[REPLAY_QUALIFICATION_DIFF] " + JSON.stringify(replayQualificationComparison));
    }

    const qualifiedCompanies = [];
    for (const sheet of ["direct_buyers", "intermediaries", "leasing"]) {
      for (const row of qualified.result[sheet]) {
        const canonical = canonicalMap.get(row.__canonical_id);
        qualifiedCompanies.push({
          id: row.__canonical_id || "",
          organization: row["Организация"] || "",
          city: row["Город/район"] || "",
          grade: row.__final_grade || "",
          reason: row.__decision_reason || "",
          a_evidence: row.__a_evidence || "",
          a_rule: row.__a_rule || "",
          stages: canonical?.source_steps || [],
          segments: String(row["Техника/сегмент"] || "")
            .split("|")
            .map((x) => x.trim())
            .filter(Boolean)
            .slice(0, 8),
          source_urls: (row?.__evidence?.source_urls || []).slice(0, 3),
          sheet
        });
      }
    }

    qualifiedCompanies.sort((a, b) => {
      const rank = { A: 0, B: 1, C: 2 };
      const gradeDiff = (rank[a.grade] ?? 9) - (rank[b.grade] ?? 9);
      return gradeDiff || a.organization.localeCompare(b.organization, "ru");
    });

    for (const company of qualifiedCompanies) {
      console.log("[TEST12_QUALIFIED_COMPANY] " + JSON.stringify(company));
    }

    console.log("[TEST12_QUALIFICATION] " + JSON.stringify({
      mode,
      stage: mode === "stage_test" ? requestedStage : null,
      raw_mentions: candidatePool.length,
      identity_clusters: identityResolution.clusters,
      identity_skipped_web: identityResolution.skippedWebClusters,
      identity_searched_web: identityResolution.searchedWebClusters,
      web_budget: publicWebBudgetState(client.__webBudget),
      canonical_after_inn: canonicalPool.length,
      after_global_dedupe: qaRecords.length,
      A: qualified.counts.A,
      B: qualified.counts.B,
      C: qualified.counts.C,
      excluded: qualified.counts.excluded,
      qualified: qualifiedCompanies.length
    }));

    await progress({ phase: "completed", step: diagnosticStep, percent: 100 });
    return {
      mode,
      result: qualified.result,
      region,
      stage: mode === "stage_test" ? requestedStage : null,
      counts: {
        total_rows: totalRows,
        unique: discoveryUnique,
        stage: mode === "stage_test" ? requestedStage : null,
        stage_rows: mode === "stage_test"
          ? rowCount(parts[requestedStage - 1] || emptyResearchResult())
          : null,
        stage_unique: mode === "stage_test"
          ? uniqueResearchCount(parts[requestedStage - 1] || emptyResearchResult())
          : null,
        stage1_rows: rowCount(parts[0] || emptyResearchResult()),
        stage1_unique: uniqueResearchCount(parts[0] || emptyResearchResult()),
        stage2_rows: rowCount(parts[1] || emptyResearchResult()),
        stage2_unique: uniqueResearchCount(parts[1] || emptyResearchResult()),
        raw_mentions: candidatePool.length,
        identity_clusters: identityResolution.clusters,
        identity_skipped_web: identityResolution.skippedWebClusters,
        identity_searched_web: identityResolution.searchedWebClusters,
        web_budget: publicWebBudgetState(client.__webBudget),
        canonical_after_inn: canonicalPool.length,
        after_global_dedupe: qaRecords.length,
        A: qualified.counts.A,
        B: qualified.counts.B,
        C: qualified.counts.C,
        qualified: qualifiedCompanies.length,
        excluded_after_qualification: qualified.counts.excluded,
        qualification_changes: replayQualificationComparison?.changed_count ?? null,
        token_usage: tokenUsageSnapshot(client)
      },
      qualified_companies: qualifiedCompanies,
      replay_comparison: replayQualificationComparison,
      discovery_snapshot: discoverySnapshot(
        region,
        parts,
        mode,
        {
          candidates: identityResolution.candidates,
          clusters: identityResolution.clusters,
          confirmedInnMentions: identityResolution.confirmedInnMentions,
          failedClusters: identityResolution.failedClusters,
          skippedWebClusters: identityResolution.skippedWebClusters,
          searchedWebClusters: identityResolution.searchedWebClusters
        },
        {
          version: DEDUPE_CHECKPOINT_VERSION,
          records: qaRecords
        },
        currentQualificationCheckpoint
      ),
      contacts: { total: 0, checked: 0, skipped: 0, ok: 0, unavailable: 0, notFound: 0 }
    };
  }

  const censusCompatibleWithResume =
    !resumeCheckpoint || !checkpointPhaseAtLeast(resumeCheckpoint, "pre_identity");
  if (
    !diagnosticMode &&
    !replayMode &&
    CENSUS_ENABLED &&
    censusCompatibleWithResume &&
    !resumeCheckpoint?.census_completed
  ) {
    await assertNotCancelled();
    statuses[8].detail = "entity census · проверка полноты отраслей и географии";
    await progress({ phase: "research", step: 9, percent: 81 });
    const census = await runEntityCensusAndGapSearch({
      client,
      region,
      parts,
      researchScopes,
      assertNotCancelled
    });
    if (!parts[8]) parts[8] = emptyResearchResult();
    appendResearchResult(parts[8], census.additions, "entity-census");
    await persistCheckpoint("discovery", {
      completed_stage: 9,
      parts,
      research_scopes: researchScopes,
      census_completed: true,
      coverage_snapshot: census.coverage,
      coverage_gap_buckets: census.gapBuckets,
      web_usage_total: webUsageSnapshot(client)
    });
    statuses[8].detail =
      `выполнен · entity census добавил ${uniqueResearchCount(census.additions)} уникальных · coverage сохранён`;
  } else if (resumeCheckpoint && checkpointPhaseAtLeast(resumeCheckpoint, "pre_identity")) {
    console.log("[ENTITY_CENSUS_RESUME_SKIP] " + JSON.stringify({
      reason: "identity_or_later_checkpoint_must_keep_frozen_candidate_pool",
      phase: resumeCheckpoint.phase || ""
    }));
  }

  await assertNotCancelled();
  const stage10StartedAt = Date.now();
  const stage10DeadlineAt = stage10StartedAt + STAGE10_MAX_MS;
  startStep(statuses[9]);
  const candidatePool = flattenCandidates(parts);

  let preIdentity = null;
  let identityResolution = null;

  if (
    resumeCheckpoint &&
    checkpointPhaseAtLeast(resumeCheckpoint, "identity") &&
    Array.isArray(resumeCheckpoint?.identity_resolution?.candidates)
  ) {
    identityResolution = cloneJson(resumeCheckpoint.identity_resolution);
    statuses[9].detail =
      `identity восстановлен из checkpoint · ${identityResolution.candidates.length} упоминаний`;
    await progress({ phase: "dedupe", step: 10, percent: 84 });
    console.log("[RESUME_IDENTITY_CHECKPOINT] " + JSON.stringify({
      candidates: identityResolution.candidates.length,
      clusters: Number(identityResolution.clusters || 0),
      searched_web_clusters: Number(identityResolution.searchedWebClusters || 0)
    }));
  } else {
    statuses[9].detail = `identity resolution · подготовка ${candidatePool.length} упоминаний`;
    await progress({ phase: "dedupe", step: 10, percent: 81 });

    preIdentity = prefilterCandidatesForIdentity(candidatePool, region);
    statuses[9].detail =
      `pre-identity filter · ${candidatePool.length} → ${preIdentity.candidates.length + preIdentity.reviewCandidates.length} упоминаний`;
    await progress({ phase: "dedupe", step: 10, percent: 82 });
    await persistCheckpoint("pre_identity", {
      completed_stage: 9,
      parts,
      research_scopes: researchScopes,
      pre_identity_summary: {
        input_mentions: candidatePool.length,
        keep_mentions: preIdentity.candidates.length,
        review_mentions: preIdentity.reviewCandidates.length,
        excluded_mentions: preIdentity.excludedCandidates.length
      }
    });

    identityResolution = await resolveCandidateIdentities({
      client,
      candidates: preIdentity.candidates,
      region,
      prompt: prompts[9],
      assertNotCancelled,
      onProgress: async ({ completed, total, confirmedInnMentions, failedClusters, skippedWebClusters, searchedWebClusters }) => {
        statuses[9].detail =
          `identity resolution · ${completed} / ${total} кластеров · ИНН: ${confirmedInnMentions} · без web: ${skippedWebClusters || 0} · с web: ${searchedWebClusters || 0}` +
          (failedClusters ? ` · ошибок: ${failedClusters}` : "");
        await progress({
          phase: "dedupe",
          step: 10,
          percent: 81 + Math.floor((completed / Math.max(1, total)) * 3)
        });
      }
    });

    identityResolution.candidates = appendReviewCandidates(
      identityResolution.candidates,
      preIdentity.reviewCandidates,
      region,
      "full"
    );
    await persistCheckpoint("identity", {
      completed_stage: 9,
      parts,
      research_scopes: researchScopes,
      identity_resolution: identityResolution
    });
  }

  const canonicalPool = canonicalizeCandidates(identityResolution.candidates, region);
  console.log("[IDENTITY_SUMMARY] " + JSON.stringify({
    region,
    mentions: candidatePool.length,
    probable_clusters: identityResolution.clusters,
    confirmed_inn_mentions: identityResolution.confirmedInnMentions,
    failed_clusters: identityResolution.failedClusters,
    skipped_web_clusters: identityResolution.skippedWebClusters,
    searched_web_clusters: identityResolution.searchedWebClusters,
    canonical_after_inn: canonicalPool.length
  }));

  const batchCount = Math.max(1, Math.ceil(canonicalPool.length / FINAL_BATCH_SIZE));
  let stagedResult;

  if (
    resumeCheckpoint &&
    checkpointPhaseAtLeast(resumeCheckpoint, "final_batches") &&
    resumeCheckpoint.staged_result
  ) {
    stagedResult = cloneJson(resumeCheckpoint.staged_result);
    console.log("[DETERMINISTIC_STAGING_RESUME] " + JSON.stringify({
      rows: rowCount(stagedResult),
      completed_final_batches: Number(resumeCheckpoint.completed_final_batches || 0)
    }));
  } else {
    stagedResult = { direct_buyers: [], intermediaries: [], leasing: [] };
    for (const canonical of canonicalPool) {
      const row = baselineRowFromCanonical(canonical);
      const sheet = preferredSheetForCanonical(canonical);
      stagedResult[sheet].push(row);
    }

    console.log("[DETERMINISTIC_STAGING] " + JSON.stringify({
      canonical_companies: canonicalPool.length,
      staged_rows: rowCount(stagedResult),
      skipped_mass_llm_batches: batchCount
    }));
    statuses[9].detail =
      `deterministic staging · ${rowCount(stagedResult)} компаний · массовые LLM-batch отключены`;
    await progress({ phase: "dedupe", step: 10, percent: 87 });
    await persistCheckpoint("final_batches", {
      completed_stage: 9,
      parts,
      research_scopes: researchScopes,
      identity_resolution: identityResolution,
      completed_final_batches: batchCount,
      staged_result: stagedResult,
      deterministic_staging: true
    });
  }

  await assertNotCancelled();
  let dedupedRecords = null;
  if (
    resumeCheckpoint &&
    checkpointPhaseAtLeast(resumeCheckpoint, "dedupe") &&
    Array.isArray(resumeCheckpoint.deduped_records)
  ) {
    dedupedRecords = cloneJson(resumeCheckpoint.deduped_records);
    statuses[9].detail = `global dedupe восстановлен · ${dedupedRecords.length} организаций`;
    await progress({ phase: "dedupe", step: 10, percent: 89 });
  } else {
  const beforeDeterministicDedupe = makeQaRecords(stagedResult);
  let qaRecords = deterministicGlobalDedupe(beforeDeterministicDedupe, null, region);
  console.log("[DETERMINISTIC_GLOBAL_DEDUPE] " + JSON.stringify({
    before: beforeDeterministicDedupe.length,
    after: qaRecords.length,
    removed: beforeDeterministicDedupe.length - qaRecords.length
  }));

  const conflictGroups = buildConflictGroups(qaRecords);
  if (conflictGroups.length) {
    statuses[9].detail = `разрешение неоднозначных конфликтов · ${conflictGroups.length} групп`;
    await progress({ phase: "dedupe", step: 10, percent: 88 });

    for (let offset = 0; offset < conflictGroups.length; offset += FINAL_CONFLICT_GROUP_BATCH_SIZE) {
      await assertNotCancelled();
      const groupBatch = conflictGroups.slice(offset, offset + FINAL_CONFLICT_GROUP_BATCH_SIZE);
      const conflictQa = await askJson(client, {
        input:
          prompts[9] +
          conflictContract() +
          `\n\nКОНФЛИКТНЫЕ ГРУППЫ:
${JSON.stringify(groupBatch)}`,
        model: CONFLICT_MODEL,
        maxOutputTokens: FINAL_QA_MAX_OUTPUT_TOKENS,
        webSearch: false,
        responseSchema: FINAL_QA_DELTA_SCHEMA,
        schemaName: "final_conflict_delta",
        diagnosticLabel: `final conflict qa | batch ${Math.floor(offset / FINAL_CONFLICT_GROUP_BATCH_SIZE) + 1}`
      });
      const resolved = applyFinalQa(qaRecords, conflictQa);
      qaRecords = makeQaRecords(resolved);
    }
  }

  dedupedRecords = qaRecords;
  statuses[9].detail = `глобальный QA · ${dedupedRecords.length} организаций · deterministic-first`;
  await progress({ phase: "dedupe", step: 10, percent: 89 });
  await persistCheckpoint("dedupe", {
    completed_stage: 9,
    parts,
    research_scopes: researchScopes,
    identity_resolution: identityResolution,
    completed_final_batches: batchCount,
    staged_result: stagedResult,
    deduped_records: dedupedRecords
  });
  }

  statuses[9].detail = `финальная A/B/C qualification · ${dedupedRecords.length} уникальных строк`;
  await progress({ phase: "dedupe", step: 10, percent: 89 });

  let qualifiedFinal;
  let finalResult;
  if (
    resumeCheckpoint &&
    checkpointPhaseAtLeast(resumeCheckpoint, "qualification") &&
    resumeCheckpoint.final_result &&
    resumeCheckpoint.qualification_counts
  ) {
    finalResult = cloneJson(resumeCheckpoint.final_result);
    qualifiedFinal = {
      result: finalResult,
      counts: cloneJson(resumeCheckpoint.qualification_counts)
    };
    console.log("[RESUME_QUALIFICATION_CHECKPOINT] " + JSON.stringify({
      input_rows: dedupedRecords.length,
      counts: qualifiedFinal.counts,
      output_rows: rowCount(finalResult)
    }));
  } else {
    const finalDecisions = await runFinalQualification({
      client,
      records: dedupedRecords,
      region,
      assertNotCancelled,
      diagnosticPrefix: "full final qualification"
    });
    qualifiedFinal = applyFinalQualification(dedupedRecords, finalDecisions);
    finalResult = qualifiedFinal.result;

    console.log("[FINAL_QUALIFICATION_SUMMARY] " + JSON.stringify({
      region,
      input_rows: dedupedRecords.length,
      A: qualifiedFinal.counts.A,
      B: qualifiedFinal.counts.B,
      C: qualifiedFinal.counts.C,
      excluded: qualifiedFinal.counts.excluded,
      output_rows: rowCount(finalResult)
    }));
    await persistCheckpoint("qualification", {
      completed_stage: 9,
      parts,
      research_scopes: researchScopes,
      identity_resolution: identityResolution,
      completed_final_batches: batchCount,
      staged_result: stagedResult,
      deduped_records: dedupedRecords,
      qualification_counts: qualifiedFinal.counts,
      final_result: finalResult,
      enrichment_completed_ids: []
    });
  }

  await assertNotCancelled();
  const finalInnCompleted = new Set(
    Array.isArray(resumeCheckpoint?.final_inn_completed_ids)
      ? resumeCheckpoint.final_inn_completed_ids.map(String)
      : []
  );
  statuses[9].detail = `финальный поиск ИНН · уже обработано ${finalInnCompleted.size}`;
  await progress({ phase: "dedupe", step: 10, percent: 89 });

  let latestFinalInnProgress = {
    completedIds: finalInnCompleted,
    attempted: 0,
    recovered: 0,
    retried: 0,
    pendingTotal: rowCount(finalResult)
  };
  let finalInnProgressEvents = 0;
  const finalInnCheckpointBatcher = createCheckpointBatcher(async () => {
    await persistCheckpoint("final_inn", {
      completed_stage: 9,
      parts,
      research_scopes: researchScopes,
      identity_resolution: identityResolution,
      completed_final_batches: batchCount,
      staged_result: stagedResult,
      deduped_records: dedupedRecords,
      qualification_counts: qualifiedFinal.counts,
      final_result: finalResult,
      final_inn_completed_ids: [...latestFinalInnProgress.completedIds],
      final_inn_attempted: latestFinalInnProgress.attempted,
      final_inn_recovered: latestFinalInnProgress.recovered,
      final_inn_retried: latestFinalInnProgress.retried,
      final_inn_pending_total: latestFinalInnProgress.pendingTotal,
      enrichment_completed_ids: []
    });
  });

  const finalInnStats = await resolveFinalMissingInns({
    client,
    finalResult,
    region,
    assertNotCancelled,
    completedIds: finalInnCompleted,
    onBatch: async (progressState) => {
      latestFinalInnProgress = progressState;
      finalInnProgressEvents++;
      statuses[9].detail =
        `финальный поиск ИНН · ${Math.min(progressState.completedIds.size, rowCount(finalResult))} / ${rowCount(finalResult)} · найдено: ${progressState.recovered} · retry: ${progressState.retried || 0}`;
      if (finalInnProgressEvents % 4 === 0) {
        await progress({ phase: "dedupe", step: 10, percent: 89 });
      }
      await finalInnCheckpointBatcher.request();
    }
  });
  await finalInnCheckpointBatcher.flush();

  const preservedStatistics = Array.isArray(finalResult.statistics)
    ? cloneJson(finalResult.statistics)
    : [];

  const postInnDiagnostics = { merges: [] };
  let postInn = postInnDedupe(finalResult, region, postInnDiagnostics);
  dedupedRecords = postInn.records;
  qualifiedFinal = postInn.qualified;
  finalResult = qualifiedFinal.result;
  if (preservedStatistics.length) finalResult.statistics = preservedStatistics;

  let innConflictGroups = duplicateInnConflictGroups(finalResult);
  let innConflictRechecks = 0;
  if (innConflictGroups.length) {
    console.log("[POST_INN_CONFLICT_PLAN] " + JSON.stringify({
      groups: innConflictGroups.length,
      inns: innConflictGroups.map((group) => group.inn)
    }));
    await mapWithConcurrency(
      innConflictGroups,
      Math.min(FINAL_INN_CONCURRENCY, 3),
      async (group, groupIndex) => {
        await assertNotCancelled();
        const rowsById = new Map(
          group.rows.map((row) => [checkpointRowId(row), row]).filter(([id]) => id)
        );
        const result = await lookupFinalInnBatch({
          client,
          rows: group.rows,
          region,
          assertNotCancelled,
          label: `post-inn-conflict-${groupIndex + 1}/${innConflictGroups.length}`
        });
        innConflictRechecks += group.rows.length;
        finalInnStats.recovered += applyFinalInnItems(rowsById, result);
      }
    );

    postInn = postInnDedupe(finalResult, region, postInnDiagnostics);
    dedupedRecords = postInn.records;
    qualifiedFinal = postInn.qualified;
    finalResult = qualifiedFinal.result;
    if (preservedStatistics.length) finalResult.statistics = preservedStatistics;
    innConflictGroups = duplicateInnConflictGroups(finalResult);
  }

  const unresolvedInnConflictClear = innConflictGroups.length
    ? clearUnresolvedInnConflicts(finalResult)
    : { groups: 0, clearedRows: 0 };
  if (unresolvedInnConflictClear.groups) {
    const afterConflictClear = postInnDedupe(finalResult, region, postInnDiagnostics);
    dedupedRecords = afterConflictClear.records;
    qualifiedFinal = afterConflictClear.qualified;
    finalResult = qualifiedFinal.result;
    if (preservedStatistics.length) finalResult.statistics = preservedStatistics;
    innConflictGroups = duplicateInnConflictGroups(finalResult);
  }

  // Legal status may become known only after final identity search.
  const eligibleSheets = { direct_buyers: [], intermediaries: [], leasing: [] };
  const excludedLegal = [];
  for (const sheet of ["direct_buyers", "intermediaries", "leasing"]) {
    for (const row of finalResult[sheet] || []) {
      const eligibility = commercialEligibility(row);
      row.__evidence = { ...(row.__evidence || {}), commercial_eligibility: eligibility };
      if (eligibility.blocked) excludedLegal.push({
        canonical_id: row.__canonical_id, organization: row["Организация"],
        inn: row["ИНН"], kind: eligibility.kind, reason: eligibility.reason,
        source_url: eligibility.source_url
      });
      else eligibleSheets[sheet].push(row);
    }
  }
  finalResult = {
    ...finalResult,
    ...eligibleSheets,
    qualification_review: mergedQualificationReviews(
      Array.isArray(finalResult.qualification_review) ? finalResult.qualification_review : []
    )
  };
  // Discovery candidates may be lost during identity or global dedupe even
  // when the eventual A/B/C qualifier is correct. Never silently drop sourced
  // transport leads; preserve the ORIGINAL evidence in the checkpoint only.
  const stagedRetention = stagedRetentionReview(stagedResult, finalResult, {
    isActionable: actionableUnqualifiedLead,
    isExcluded: (row) => commercialEligibility(row).blocked
  });
  finalResult.qualification_review = mergedQualificationReviews(
    finalResult.qualification_review, stagedRetention.rows
  );
  console.log("[FINAL_STAGED_RETENTION_AUDIT] " + JSON.stringify({
    ...stagedRetention.diagnostics,
    total_review: finalResult.qualification_review.length
  }));
  if (finalResult.qualification_review.length) {
    console.log("[FINAL_UNQUALIFIED_REVIEW_PRESERVED] " + JSON.stringify({
      count: finalResult.qualification_review.length,
      candidates: finalResult.qualification_review.map((row) => ({
        canonical_id: row.__canonical_id || "",
        organization: row["Организация"],
        inn: row["ИНН"] || "",
        origin_sheet: row.__qualification_origin_sheet || ""
      }))
    }));
  }
  qualifiedFinal.result = finalResult;
  qualifiedFinal.counts = {
    ...qualifiedFinal.counts,
    A: allResearchRows(finalResult).filter((row) => row.__final_grade === "A").length,
    B: allResearchRows(finalResult).filter((row) => row.__final_grade === "B").length,
    C: allResearchRows(finalResult).filter((row) => row.__final_grade === "C").length,
    excluded: Number(qualifiedFinal.counts?.excluded || 0) + excludedLegal.length
  };
  if (excludedLegal.length) console.log("[FINAL_LEGAL_EXCLUSIONS] " + JSON.stringify(excludedLegal));
  for (const row of allResearchRows(finalResult)) mergeResearchComment(row);

  finalInnStats.missing = allResearchRows(finalResult)
    .filter((row) => !normalizeInn(row?.["ИНН"])).length;
  finalInnStats.innConflictRechecks = innConflictRechecks;
  finalInnStats.remainingInnConflicts = innConflictGroups.length;

  console.log("[POST_INN_DEDUPE_SUMMARY] " + JSON.stringify({
    merges: postInnDiagnostics.merges.length,
    output_rows: rowCount(finalResult),
    qualification_counts: qualifiedFinal.counts,
    conflict_rechecks: innConflictRechecks,
    unresolved_conflict_groups_cleared: unresolvedInnConflictClear.groups,
    unresolved_conflict_rows_cleared: unresolvedInnConflictClear.clearedRows,
    remaining_inn_conflicts: innConflictGroups.length,
    missing_inn: finalInnStats.missing
  }));

  const finalInnRemoved = enforceFinalInnRequirement(finalResult);
  finalInnStats.removedWithoutInn = finalInnRemoved.length;

  await persistCheckpoint("final_inn", {
    completed_stage: 9,
    parts,
    research_scopes: researchScopes,
    identity_resolution: identityResolution,
    completed_final_batches: batchCount,
    staged_result: stagedResult,
    deduped_records: dedupedRecords,
    qualification_counts: qualifiedFinal.counts,
    final_result: finalResult,
    final_inn_completed_ids: [...finalInnStats.completedIds],
    final_inn_attempted: finalInnStats.attempted,
    final_inn_retried: finalInnStats.retried,
    final_inn_recovered: finalInnStats.recovered,
    final_inn_missing: finalInnStats.missing,
    final_inn_conflict_rechecks: finalInnStats.innConflictRechecks,
    final_inn_remaining_conflicts: finalInnStats.remainingInnConflicts,
    final_inn_removed_without_inn: finalInnStats.removedWithoutInn,
    enrichment_completed_ids: Array.isArray(resumeCheckpoint?.enrichment_completed_ids)
      ? resumeCheckpoint.enrichment_completed_ids
      : []
  });

  await assertNotCancelled();
  const finalCompaniesForEnrichment = allResearchRows(finalResult)
    .sort((a, b) => safeSearchPriority(b) - safeSearchPriority(a));
  let targetedSearches = Number(resumeCheckpoint?.targeted_searches || 0);
  const enrichmentCompleted = new Set(
    Array.isArray(resumeCheckpoint?.enrichment_completed_ids)
      ? resumeCheckpoint.enrichment_completed_ids.map(String)
      : []
  );
  let enrichmentProcessed = 0;
  let enrichmentErrors = 0;
  let enrichmentDeadlineSkipped = 0;
  let enrichmentBatchAccepted = 0;
  let enrichmentBatchBlank = 0;
  let enrichmentFallbackCalls = 0;
  let enrichmentBatchDeferred = 0;
  let enrichmentSingleCalls = 0;

  for (const row of finalCompaniesForEnrichment) mergeResearchComment(row);

  const statisticsPromise =
    resumeCheckpoint &&
    checkpointPhaseAtLeast(resumeCheckpoint, "statistics") &&
    Array.isArray(resumeCheckpoint?.final_result?.statistics)
      ? Promise.resolve(cloneJson(resumeCheckpoint.final_result.statistics))
      : askJson(client, {
          input:
            statisticsContract() +
            `\n\nРЕГИОН: ${region}\nСобери только 8 обязательных показателей статистики по региону.`,
          model: TARGETED_SEARCH_MODEL,
          maxOutputTokens: STATISTICS_MAX_OUTPUT_TOKENS,
          webSearch: true,
          maxToolCalls: 3,
          diagnosticLabel: "regional statistics",
          timeoutMs: Math.min(45000, Math.max(8000, deadlineRemaining(stage10DeadlineAt) - 3000))
        })
          .then((result) => Array.isArray(result?.statistics) ? result.statistics : [])
          .catch((error) => {
            if (jobSignal?.aborted) throw error;
            console.error("[STATISTICS_ERROR] " + JSON.stringify({
              error: error?.message || String(error)
            }));
            return [];
          });

  const enrichmentCheckpointBatcher = createCheckpointBatcher(async () => {
    await persistCheckpoint("enrichment", {
      completed_stage: 9,
      parts,
      research_scopes: researchScopes,
      identity_resolution: identityResolution,
      completed_final_batches: batchCount,
      staged_result: stagedResult,
      deduped_records: dedupedRecords,
      qualification_counts: qualifiedFinal.counts,
      final_result: finalResult,
      final_inn_completed_ids: [...finalInnStats.completedIds],
      final_inn_attempted: finalInnStats.attempted,
      final_inn_retried: finalInnStats.retried,
      final_inn_recovered: finalInnStats.recovered,
      final_inn_missing: finalInnStats.missing,
      final_inn_removed_without_inn: finalInnStats.removedWithoutInn,
      targeted_searches: targetedSearches,
      enrichment_completed_ids: [...enrichmentCompleted],
      enrichment_errors: enrichmentErrors,
      enrichment_deadline_skipped: enrichmentDeadlineSkipped
    });
  });

  const enrichmentPending = finalCompaniesForEnrichment.filter((row) => {
    const id = checkpointRowId(row);
    return !id || !enrichmentCompleted.has(id);
  });

  console.log("[ENRICHMENT_PLAN] " + JSON.stringify({
    total: finalCompaniesForEnrichment.length,
    already_completed: enrichmentCompleted.size,
    pending: enrichmentPending.length,
    concurrency: ENRICHMENT_CONCURRENCY,
    stage_deadline_ms: STAGE10_MAX_MS
  }));

  const enrichmentGroups = [];
  for (let i = 0; i < enrichmentPending.length; i += ENRICHMENT_BATCH_SIZE) {
    enrichmentGroups.push(enrichmentPending.slice(i, i + ENRICHMENT_BATCH_SIZE));
  }

  await mapWithConcurrency(
    enrichmentGroups,
    ENRICHMENT_CONCURRENCY,
    async (batch) => {
      await assertNotCancelled();
      const targets = batch.map((row) => ({
        ...compactEnrichmentTarget(row),
        missing: prioritizedResearchGaps(row)
      })).filter((row) => row.missing.length > 0);

      let groupedResults = new Map();
      let batchAttempted = false;
      let batchFallbackRemaining = ENRICHMENT_MAX_FALLBACKS_PER_BATCH;
      if (targets.length > 1 && deadlineRemaining(stage10DeadlineAt) > 9000) {
        batchAttempted = true;
        try {
          targetedSearches++;
          const result = await askJson(client, {
            input: `ПАКЕТНОЕ ОБОГАЩЕНИЕ КОМПАНИЙ. РЕГИОН: ${region}. Компании уже проверены по ИНН. Для каждого id верни объект с id, fields (только УК, выручка целым числом рублей, численность целым числом сотрудников) и __comment. Не ищи ИНН, телефон и ЛПР. Не смешивай юрлица. Если достоверное значение НЕ найдено, оставь его пустым: это завершённая проверка, а не ошибка, и повторного поиска не будет. Выполни не более ${ENRICHMENT_BATCH_MAX_TOOL_CALLS} web_search на весь пакет, верни JSON. КОМПАНИИ: ${JSON.stringify(targets)}`,
            model: TARGETED_SEARCH_MODEL,
            maxOutputTokens: Math.max(TARGETED_SEARCH_MAX_OUTPUT_TOKENS, 4000),
            webSearch: true,
            responseSchema: ENRICHMENT_BATCH_SCHEMA,
            schemaName: "batch_company_enrichment",
            maxToolCalls: ENRICHMENT_BATCH_MAX_TOOL_CALLS,
            diagnosticLabel: `enrichment batch | ${targets.length} companies`,
            timeoutMs: Math.min(ENRICHMENT_SEARCH_TIMEOUT_MS * 2, Math.max(5000, deadlineRemaining(stage10DeadlineAt) - 3000)),
            allowJsonRepair: false
          });
          const valid = new Set(targets.map((item) => String(item.id || "")));
          groupedResults = new Map(
            (Array.isArray(result?.items) ? result.items : [])
              .filter((item) => valid.has(String(item?.id || "")))
              .map((item) => [String(item.id), item])
          );
          console.log("[ENRICHMENT_BATCH_RESULT] " + JSON.stringify({
            requested: targets.length,
            returned: groupedResults.size,
            missing: targets.length - groupedResults.size,
            max_tool_calls: ENRICHMENT_BATCH_MAX_TOOL_CALLS
          }));
        } catch (error) {
          if (jobSignal?.aborted || error?.message === "JOB_CANCELLED") throw error;
          console.warn("[ENRICHMENT_BATCH_FALLBACK] " + JSON.stringify({
            size: targets.length,
            error: error?.message || String(error)
          }));
        }
      }

      for (const row of batch) {
        await assertNotCancelled();
        const rowId = checkpointRowId(row);
        const gaps = prioritizedResearchGaps(row);
        if (!gaps.length) {
          if (rowId) enrichmentCompleted.add(rowId);
          enrichmentProcessed++;
          await enrichmentCheckpointBatcher.request();
          continue;
        }

        const remaining = deadlineRemaining(stage10DeadlineAt);
        if (remaining <= 7000) {
          enrichmentDeadlineSkipped++;
          enrichmentProcessed++;
          console.log("[ENRICHMENT_DEADLINE_SKIP] " + JSON.stringify({
            id: rowId,
            organization: row?.["Организация"] || "",
            gaps
          }));
          await enrichmentCheckpointBatcher.request();
          continue;
        }

        const action = decideEnrichmentAction({
          batchAttempted,
          batchItem: groupedResults.get(rowId),
          rowId,
          priority: safeSearchPriority(row),
          globalFallbackRemaining: ENRICHMENT_MAX_FALLBACKS_TOTAL - enrichmentFallbackCalls,
          batchFallbackRemaining,
          deadlineRemainingMs: remaining
        });

        if (action.action === "defer") {
          // A missing ROW is a technical omission, not an excuse for an
          // unlimited second paid search across low-priority C companies.
          enrichmentBatchDeferred++;
          if (rowId) enrichmentCompleted.add(rowId);
          enrichmentProcessed++;
          console.log("[ENRICHMENT_BATCH_DEFERRED] " + JSON.stringify({
            id: rowId, grade: row.__final_grade || "", reason: action.reason, gaps
          }));
          await enrichmentCheckpointBatcher.request();
          continue;
        }

        if (action.consumesFallback) {
          batchFallbackRemaining--;
          enrichmentFallbackCalls++;
          console.log("[ENRICHMENT_BATCH_FALLBACK] " + JSON.stringify({
            id: rowId, reason: action.reason,
            fallback_used: enrichmentFallbackCalls,
            fallback_limit: ENRICHMENT_MAX_FALLBACKS_TOTAL
          }));
        }

        try {
          let enriched;
          if (action.action === "use_batch") {
            enriched = groupedResults.get(rowId);
            enrichmentBatchAccepted++;
            if (!Object.values(enriched.fields || {}).some((value) => String(value ?? "").trim()) &&
                !String(enriched.__comment || "").trim()) enrichmentBatchBlank++;
          } else {
            // Individual lookup is for single-item groups or one bounded
            // structural recovery, NEVER because a researched value is blank.
            targetedSearches++;
            if (action.action === "single") enrichmentSingleCalls++;
            enriched = await askTargetedSearch(
              client,
              targetedSearchContract() +
                `\n\nРЕГИОН: ${region}
КОМПАНИЯ:
${JSON.stringify(compactEnrichmentTarget(row))}
НЕДОСТАЮЩИЕ СВЕДЕНИЯ:
${JSON.stringify(gaps)}
Компания уже прошла identity, global dedupe, финальную A/B/C qualification и отдельную проверку ИНН.
Используй web_search только для этой компании. Не ищи телефон/ЛПР/ИНН и не перепроверяй заполненные поля. Пустой результат допустим.`,
              Math.min(ENRICHMENT_SEARCH_TIMEOUT_MS, Math.max(5000, remaining - 3000)),
              action.action === "fallback" ? 1 : 2
            );
          }
          applyTargetedPatch(row, enriched);
          if (rowId) enrichmentCompleted.add(rowId);
        } catch (error) {
          if (jobSignal?.aborted || error?.message === "JOB_CANCELLED") throw error;
          enrichmentErrors++;
          console.error("[ENRICHMENT_ERROR] " + JSON.stringify({
            id: rowId,
            organization: row?.["Организация"] || "",
            error: error?.message || String(error)
          }));
        }

        enrichmentProcessed++;
        if (enrichmentProcessed % 10 === 0 || enrichmentProcessed === enrichmentPending.length) {
          statuses[9].detail =
            `enrichment ${enrichmentProcessed} / ${enrichmentPending.length} · search: ${targetedSearches} · errors: ${enrichmentErrors}`;
          await progress({ phase: "dedupe", step: 10, percent: 89 });
        }
        await enrichmentCheckpointBatcher.request();
      }
    }
  );
  console.log("[ENRICHMENT_EFFICIENCY] " + JSON.stringify({
    planned_companies: enrichmentPending.length,
    batch_answered: enrichmentBatchAccepted,
    batch_empty_answers: enrichmentBatchBlank,
    individual_searches: enrichmentSingleCalls,
    structural_fallback_searches: enrichmentFallbackCalls,
    batch_omissions_deferred: enrichmentBatchDeferred,
    errors: enrichmentErrors,
    targeted_model_calls: targetedSearches
  }));
    await enrichmentCheckpointBatcher.flush();

  statuses[9].detail = "региональная статистика";
  await progress({ phase: "dedupe", step: 10, percent: 89 });
  finalResult.statistics = await statisticsPromise;

  await persistCheckpoint("statistics", {
    completed_stage: 9,
    parts,
    research_scopes: researchScopes,
    identity_resolution: identityResolution,
    completed_final_batches: batchCount,
    staged_result: stagedResult,
    deduped_records: dedupedRecords,
    qualification_counts: qualifiedFinal.counts,
    final_result: finalResult,
    final_inn_completed_ids: [...finalInnStats.completedIds],
    final_inn_attempted: finalInnStats.attempted,
    final_inn_retried: finalInnStats.retried,
    final_inn_recovered: finalInnStats.recovered,
    final_inn_missing: finalInnStats.missing,
    final_inn_removed_without_inn: finalInnStats.removedWithoutInn,
    targeted_searches: targetedSearches,
    enrichment_completed_ids: [...enrichmentCompleted],
    enrichment_errors: enrichmentErrors,
    enrichment_deadline_skipped: enrichmentDeadlineSkipped,
    stage10_duration_ms: Date.now() - stage10StartedAt
  });

  finishStep(statuses[9]);
  statuses[9].detail =
    `выполнен · ${rowCount(finalResult)} организаций · identity-кластеров: ${identityResolution.clusters} · точечных поисков: ${targetedSearches}`;
  await progress({ phase: "dedupe", step: 10, percent: 90 });

  const companies = allResearchRows(finalResult);
  if (String(process.env.OPENAI_PREVIOUS_CONTACT_CACHE || "true").toLowerCase() !== "false") {
    try {
      const prior = await loadLatestCompletedResearch(region);
      const byInn = new Map();
      for (const historical of allResearchRows(prior || {})) {
        const inn = normalizeInn(historical?.["ИНН"]);
        const proof = historical?.__evidence?.contact_verification;
        const age = Date.now() - Date.parse(String(proof?.verified_at || ""));
        if (!inn || proof?.inn !== inn || !/^https?:\/\//i.test(String(proof?.source_url || "")) ||
            !Number.isFinite(age) || age < 0 || age > 90 * 24 * 3600 * 1000) continue;
        const phone = normalizePhoneDigits(proof?.phone);
        if (phone && splitPhoneEntries(historical["Телефон"]).some((item) => normalizePhoneDigits(item) === phone)) {
          byInn.set(inn, { phone, source_url: proof.source_url });
        }
      }
      let recovered = 0;
      for (const row of companies) {
        if (hasConfirmedPhone(row)) continue;
        const inn = normalizeInn(row["ИНН"]);
        const priorPhone = byInn.get(inn);
        if (!inn || !priorPhone) continue;
        row["Телефон"] = priorPhone.phone;
        recovered++;
        row.__evidence = { ...(row.__evidence || {}), notes: [ ...(row.__evidence?.notes || []), `Контакт восстановлен по подтверждённому ИНН из исследования этого региона за последние 90 дней: ${priorPhone.source_url}` ] };
      }
      console.log("[PREVIOUS_CONTACT_CACHE] " + JSON.stringify({ recovered, eligible: byInn.size }));
    } catch (error) {
      console.warn("[PREVIOUS_CONTACT_CACHE_ERROR] " + JSON.stringify({ error: error?.message || String(error) }));
    }
  }
  const phoneOwners = buildPhoneOwnerMap(companies);
  const googleCompanies = companies.filter(needsGoogleResearch);
  const skippedGoogle = companies.length - googleCompanies.length;
  const stage11StartedAt = Date.now();
  const stage11DeadlineAt = stage11StartedAt + STAGE11_MAX_MS;

  startStep(statuses[10]);
  statuses[10].detail = googleCompanies.length
    ? `web-first контакты · 0 / ${googleCompanies.length} · готовых: ${skippedGoogle}`
    : `контакты уже заполнены · пропущено: ${skippedGoogle}`;
  await progress({
    phase: "google_ai",
    step: 11,
    percent: 90,
    contactCurrent: 0,
    contactTotal: googleCompanies.length
  });

  const resumedContactStats = resumeCheckpoint?.contact_stats || {};
  const contactCheckpointVersion = Number(resumedContactStats.version || 0);
  const contactCompleted = new Set(
    contactCheckpointVersion >= 2 && Array.isArray(resumeCheckpoint?.contact_completed_ids)
      ? resumeCheckpoint.contact_completed_ids.map(String)
      : []
  );

  let webOk = Number(resumedContactStats.webOk || 0);
  let webNotFound = Number(resumedContactStats.webNotFound || 0);
  let webUnavailable = Number(resumedContactStats.webUnavailable || 0);
  let browserFallbacks = Number(resumedContactStats.browserFallbacks || 0);
  let browserRecovered = Number(resumedContactStats.browserRecovered || 0);
  let browserUnavailable = Number(resumedContactStats.browserUnavailable || 0);
  let phoneConflicts = Number(resumedContactStats.phoneConflicts || 0);
  let phoneVerified = Number(resumedContactStats.phoneVerified || 0);
  let deadlineSkipped = Number(resumedContactStats.deadlineSkipped || 0);
  let solRetries = 0;
  let solRecovered = 0;

  const primaryResults = new Map(
    contactCheckpointVersion >= 2 &&
    resumeCheckpoint?.contact_primary_results &&
    typeof resumeCheckpoint.contact_primary_results === "object"
      ? Object.entries(resumeCheckpoint.contact_primary_results)
      : []
  );
  const contactOutcomes = new Map();
  const resumedOk = contactCheckpointVersion >= 2 ? Number(resumedContactStats.ok || 0) : 0;
  const resumedUnavailable = contactCheckpointVersion >= 2 ? Number(resumedContactStats.unavailable || 0) : 0;
  const resumedNotFound = contactCheckpointVersion >= 2 ? Number(resumedContactStats.notFound || 0) : 0;
  let primaryProcessed =
    contactCheckpointVersion >= 2
      ? Number(resumedContactStats.primaryProcessed || primaryResults.size || 0)
      : 0;

  const contactStatsSnapshot = () => ({
    version: 2,
    ok: resumedOk + [...contactOutcomes.values()].filter((value) => value === "ok").length,
    unavailable: resumedUnavailable + [...contactOutcomes.values()].filter((value) => value === "unavailable").length,
    notFound: resumedNotFound + [...contactOutcomes.values()].filter((value) => value === "not_found").length,
    solRetries,
    solRecovered,
    webOk,
    webNotFound,
    webUnavailable,
    browserFallbacks,
    browserRecovered,
    browserUnavailable,
    phoneConflicts,
    phoneVerified,
    deadlineSkipped,
    primaryProcessed,
    browserCircuitOpen: false
  });

  let browserCircuitOpen = false;
  const persistContactsCheckpoint = async () => {
    const stats = contactStatsSnapshot();
    stats.browserCircuitOpen = browserCircuitOpen;
    await persistCheckpoint("contacts", {
      completed_stage: 9,
      parts,
      research_scopes: researchScopes,
      identity_resolution: identityResolution,
      completed_final_batches: batchCount,
      staged_result: stagedResult,
      deduped_records: dedupedRecords,
      qualification_counts: qualifiedFinal.counts,
      final_result: finalResult,
      targeted_searches: targetedSearches,
      enrichment_completed_ids: [...enrichmentCompleted],
      contact_completed_ids: [...contactCompleted],
      contact_primary_results: Object.fromEntries(primaryResults),
      contact_stats: stats,
      stage10_duration_ms: Date.now() - stage10StartedAt,
      stage11_duration_ms: Date.now() - stage11StartedAt
    });
  };
  const contactCheckpointBatcher = createCheckpointBatcher(persistContactsCheckpoint);

  googleCompanies.sort((a, b) => safeSearchPriority(b) - safeSearchPriority(a));
  const contactPending = googleCompanies.filter((row) => {
    const id = checkpointRowId(row);
    return !id || (!contactCompleted.has(id) && !primaryResults.has(id));
  });

  console.log("[CONTACT_WEB_PLAN] " + JSON.stringify({
    total_companies: companies.length,
    target_companies: googleCompanies.length,
    already_completed: contactCompleted.size,
    pending: contactPending.length,
    concurrency: CONTACT_CONCURRENCY,
    stage_deadline_ms: STAGE11_MAX_MS
  }));

  await mapWithConcurrency(
    contactPending,
    CONTACT_CONCURRENCY,
    async (row) => {
      await assertNotCancelled();
      const rowId = checkpointRowId(row);
      if (deadlineRemaining(stage11DeadlineAt) <= 6000) {
        deadlineSkipped++;
        webUnavailable++;
        if (rowId) {
          contactOutcomes.set(rowId, "unavailable");
          contactCompleted.add(rowId);
        }
        primaryProcessed++;
        await contactCheckpointBatcher.request();
        return;
      }

      try {
        const needPhoneBefore = !hasConfirmedPhone(row);
        const needLeaderBefore = !hasConfirmedLeader(row);
        const result = await searchContactsWithWeb({
          client,
          row,
          region,
          deadlineAt: stage11DeadlineAt
        });
        primaryResults.set(rowId, {
          ...result,
          __needPhone: needPhoneBefore,
          __needLeader: needLeaderBefore
        });
        if (result.status === "ok") webOk++;
        else webNotFound++;
      } catch (error) {
        if (jobSignal?.aborted || error?.message === "JOB_CANCELLED") throw error;
        webUnavailable++;
        primaryResults.set(rowId, {
          status: "unavailable",
          phones: [],
          leader: "",
          note: error?.message || "contact web search unavailable",
          __needPhone: !hasConfirmedPhone(row),
          __needLeader: !hasConfirmedLeader(row)
        });
      }

      primaryProcessed++;
      if (primaryProcessed % 10 === 0 || primaryResults.size >= googleCompanies.length - contactCompleted.size) {
        statuses[10].detail =
          `web-first контакты · ${primaryProcessed} / ${googleCompanies.length} · ok: ${webOk} · unavailable: ${webUnavailable}`;
        await progress({
          phase: "google_ai",
          step: 11,
          percent: 90 + Math.floor((primaryProcessed / Math.max(1, googleCompanies.length)) * 5),
          contactCurrent: primaryProcessed,
          contactTotal: googleCompanies.length,
          contactCompany: "",
          contactStats: contactStatsSnapshot()
        });
      }
      await contactCheckpointBatcher.request();
    }
  );

  // Build a global claim map BEFORE accepting newly found phones. This catches
  // both conflicts with existing cells and the same new phone returned for
  // several legal entities in the concurrent primary pass.
  const phoneClaims = new Map();
  const addPhoneClaim = (phone, row, source) => {
    const normalized = normalizePhoneDigits(phone);
    if (!normalized) return;
    if (!phoneClaims.has(normalized)) phoneClaims.set(normalized, []);
    const claims = phoneClaims.get(normalized);
    if (!claims.some((item) => item.row === row && item.source === source)) {
      claims.push({ row, source });
    }
  };

  for (const row of companies) {
    for (const phone of splitPhoneEntries(row["Телефон"])) {
      addPhoneClaim(phone, row, "existing");
    }
  }
  for (const row of googleCompanies) {
    if (contactCompleted.has(checkpointRowId(row))) continue;
    const result = primaryResults.get(checkpointRowId(row));
    for (const phone of result?.phones || []) addPhoneClaim(phone, row, "web");
  }

  const conflictChecks = [];
  const primaryRowsToApply = googleCompanies.filter((row) => {
    const id = checkpointRowId(row);
    return id && !contactCompleted.has(id) && primaryResults.has(id);
  });

  for (const row of primaryRowsToApply) {
    const rowId = checkpointRowId(row);
    const result = primaryResults.get(rowId);
    if (!result) continue;

    if (result.leader && !hasConfirmedLeader(row)) {
      row["Руководитель / ЛПР"] = String(result.leader).trim();
    }

    for (const phone of result.phones || []) {
      const normalized = normalizePhoneDigits(phone);
      if (!normalized) continue;
      const claims = phoneClaims.get(normalized) || [];
      const otherRows = claims.some((claim) => claim.row !== row);

      if (!otherRows) {
        row["Телефон"] = mergePhone(row["Телефон"], normalized);
        if (!phoneOwners.has(normalized)) phoneOwners.set(normalized, []);
        if (!phoneOwners.get(normalized).includes(row)) phoneOwners.get(normalized).push(row);
        continue;
      }

      phoneConflicts++;
      conflictChecks.push({ row, rowId, phone: normalized });
    }
  }

  const verifiedConflictPhones = new Set();
  await mapWithConcurrency(
    conflictChecks,
    CONTACT_CONCURRENCY,
    async ({ row, rowId, phone }) => {
      await assertNotCancelled();
      if (deadlineRemaining(stage11DeadlineAt) <= 6000) return;
      try {
        const verification = await verifyPhoneWithWebSearch({
          client,
          row,
          region,
          phone,
          deadlineAt: stage11DeadlineAt
        });
        if (verification?.confirmed) {
          verifiedConflictPhones.add(`${rowId}|${phone}`);
          phoneVerified++;
        }
      } catch (error) {
        if (jobSignal?.aborted || error?.message === "JOB_CANCELLED") throw error;
        console.error("[PHONE_CONFLICT_VERIFY_ERROR] " + JSON.stringify({
          id: rowId,
          phone,
          error: error?.message || String(error)
        }));
      }
    }
  );

  for (const { row, rowId, phone } of conflictChecks) {
    if (!verifiedConflictPhones.has(`${rowId}|${phone}`)) continue;
    row["Телефон"] = mergePhone(row["Телефон"], phone);
    if (!phoneOwners.has(phone)) phoneOwners.set(phone, []);
    if (!phoneOwners.get(phone).includes(row)) phoneOwners.get(phone).push(row);
  }

  for (const row of primaryRowsToApply) {
    const rowId = checkpointRowId(row);
    const result = primaryResults.get(rowId);
    if (!result) continue;
    const verifiedSource = String(result.official_site || "").trim();
    const inn = normalizeInn(row["ИНН"]);
    if (inn && /^https?:\/\//i.test(verifiedSource)) {
      const accepted = (result.phones || []).map(normalizePhoneDigits).filter(Boolean)
        .find((phone) => splitPhoneEntries(row["Телефон"]).some((entry) => normalizePhoneDigits(entry) === phone));
      if (accepted) row.__evidence = {
        ...(row.__evidence || {}),
        contact_verification: { inn, phone: accepted, source_url: verifiedSource, verified_at: new Date().toISOString() }
      };
    }
    const gainedPhone = Boolean(result.__needPhone && hasConfirmedPhone(row));
    const gainedLeader = Boolean(
      result.__needLeader &&
      result?.leader &&
      hasConfirmedLeader(row)
    );
    if (rowId) contactOutcomes.set(
      rowId,
      gainedPhone || gainedLeader
        ? "ok"
        : result.status === "unavailable"
          ? "unavailable"
          : "not_found"
    );
  }

  // Google AI Mode is now a small fallback for unresolved A/B rows only.
  // It is never the primary path and never triggers a full automatic Sol retry.
  // Disabled by default after repeated computer-turn-limit failures; explicit opt-in only.
  const browserFallbackEnabled = String(process.env.GOOGLE_AI_FALLBACK_ENABLED || "false").toLowerCase() === "true";
  const browserFallbackCandidates = (browserFallbackEnabled ? primaryRowsToApply : []).filter((row) => {
    if (!isPriorityAB(row)) return false;
    if (!needsGoogleResearch(row)) return false;
    return deadlineRemaining(stage11DeadlineAt) > 45000;
  });

  let browser = null;
  const browserSessions = [];
  let browserAttemptsThisRun = 0;
  let browserUnavailableThisRun = 0;

  if (browserFallbackCandidates.length && deadlineRemaining(stage11DeadlineAt) > 45000) {
    try {
      browser = await launchResearchBrowser();
      const sessionCount = Math.min(
        GOOGLE_FALLBACK_CONCURRENCY,
        browserFallbackCandidates.length
      );
      for (let index = 0; index < sessionCount; index++) {
        browserSessions.push(await createResearchSession(browser));
      }
      if (jobSignal) {
        jobSignal.addEventListener(
          "abort",
          () => browser?.close().catch(() => {}),
          { once: true }
        );
      }

      await mapWithConcurrency(
        browserFallbackCandidates,
        browserSessions.length,
        async (row, _index, workerIndex) => {
          await assertNotCancelled();
          if (browserCircuitOpen || deadlineRemaining(stage11DeadlineAt) <= 15000) return;

          const rowId = checkpointRowId(row);
          const timeoutMs = Math.min(
            GOOGLE_AI_COMPANY_TIMEOUT_MS,
            Math.max(10000, deadlineRemaining(stage11DeadlineAt) - 5000)
          );
          const timeoutSignal = AbortSignal.timeout(timeoutMs);
          const attemptSignal = jobSignal
            ? AbortSignal.any([jobSignal, timeoutSignal])
            : timeoutSignal;

          browserAttemptsThisRun++;
          browserFallbacks++;
          let contact;
          try {
            contact = await enrichCompanyWithGoogleAI({
              client,
              session: browserSessions[workerIndex],
              row,
              region,
              needPhone: !hasConfirmedPhone(row),
              needLeader: !hasConfirmedLeader(row),
              forceFallback: false,
              isCancelled: () => Boolean(job.cancelled || jobSignal?.aborted),
              signal: attemptSignal
            });
          } catch (error) {
            if (jobSignal?.aborted || error?.message === "JOB_CANCELLED") throw error;
            contact = {
              status: "unavailable",
              phone: "",
              leader: "",
              note: error?.message || "browser fallback unavailable"
            };
          }

          if (contact?.status === "unavailable") {
            browserUnavailable++;
            browserUnavailableThisRun++;
          }

          if (
            browserAttemptsThisRun >= 10 &&
            browserUnavailableThisRun / browserAttemptsThisRun >= 0.7
          ) {
            browserCircuitOpen = true;
            console.log("[GOOGLE_AI_CIRCUIT_OPEN] " + JSON.stringify({
              attempts: browserAttemptsThisRun,
              unavailable: browserUnavailableThisRun,
              unavailable_share: Number(
                (browserUnavailableThisRun / browserAttemptsThisRun).toFixed(3)
              )
            }));
          }

          let applied = false;
          if (contact?.status === "ok") {
            if (contact.leader && !hasConfirmedLeader(row)) {
              row["Руководитель / ЛПР"] = String(contact.leader).trim();
              applied = true;
            }

            for (const entry of splitPhoneEntries(contact.phone)) {
              const normalized = normalizePhoneDigits(entry);
              if (!normalized) continue;
              const owners = phoneOwners.get(normalized) || [];
              const belongsElsewhere = owners.some((owner) => owner !== row);
              let accept = !belongsElsewhere;

              if (belongsElsewhere && deadlineRemaining(stage11DeadlineAt) > 6000) {
                phoneConflicts++;
                try {
                  const verification = await verifyPhoneWithWebSearch({
                    client,
                    row,
                    region,
                    phone: normalized,
                    deadlineAt: stage11DeadlineAt
                  });
                  accept = Boolean(verification?.confirmed);
                  if (accept) phoneVerified++;
                } catch (error) {
                  if (jobSignal?.aborted || error?.message === "JOB_CANCELLED") throw error;
                  accept = false;
                }
              }

              if (!accept) continue;
              row["Телефон"] = mergePhone(row["Телефон"], normalized);
              if (!phoneOwners.has(normalized)) phoneOwners.set(normalized, []);
              if (!phoneOwners.get(normalized).includes(row)) {
                phoneOwners.get(normalized).push(row);
              }
              applied = true;
            }
          }

          if (applied) {
            browserRecovered++;
            if (rowId) contactOutcomes.set(rowId, "ok");
          }
        }
      );
    } catch (error) {
      if (jobSignal?.aborted || error?.message === "JOB_CANCELLED") throw error;
      browserCircuitOpen = true;
      console.error("[GOOGLE_AI_FALLBACK_STAGE_ERROR] " + JSON.stringify({
        error: error?.message || String(error)
      }));
    } finally {
      for (const session of browserSessions) {
        await closeResearchSession(session);
      }
      if (browser) await browser.close().catch(() => {});
    }
  }

  for (const row of primaryRowsToApply) {
    const rowId = checkpointRowId(row);
    if (!rowId) continue;
    if (!contactOutcomes.has(rowId)) {
      contactOutcomes.set(
        rowId,
        needsGoogleResearch(row) ? "not_found" : "ok"
      );
    }
    contactCompleted.add(rowId);
    await contactCheckpointBatcher.request();
  }
  await contactCheckpointBatcher.flush();

  const contactStats = contactStatsSnapshot();
  contactStats.browserCircuitOpen = browserCircuitOpen;
  const ok = contactStats.ok;
  const unavailable = contactStats.unavailable;
  const notFound = contactStats.notFound;

  finishStep(statuses[10]);
  statuses[10].detail =
    `выполнен · web-first проверено ${googleCompanies.length} · browser fallback ${browserFallbacks} · conflicts ${phoneConflicts}`;
  await progress({
    phase: "completed",
    step: 11,
    percent: 100,
    contactCurrent: googleCompanies.length,
    contactTotal: googleCompanies.length,
    contactStats
  });
  await persistCheckpoint("completed", {
    completed_stage: 9,
    parts,
    research_scopes: researchScopes,
    identity_resolution: identityResolution,
    completed_final_batches: batchCount,
    staged_result: stagedResult,
    deduped_records: dedupedRecords,
    qualification_counts: qualifiedFinal.counts,
    final_result: finalResult,
    targeted_searches: targetedSearches,
    enrichment_completed_ids: [...enrichmentCompleted],
    contact_completed_ids: [...contactCompleted],
    contact_primary_results: {},
    contact_stats: contactStats,
    stage10_duration_ms: Date.now() - stage10StartedAt,
    stage11_duration_ms: Date.now() - stage11StartedAt
  });

  return {
    mode: mode === "resume" ? "resume" : "full",
    result: finalResult,
    region,
    counts: {
      direct_buyers: finalResult.direct_buyers.length,
      intermediaries: finalResult.intermediaries.length,
      leasing: finalResult.leasing.length,
      statistics: finalResult.statistics.length
    },
    contacts: {
      total: companies.length,
      checked: googleCompanies.length,
      skipped: skippedGoogle,
      ok,
      unavailable,
      notFound,
      solRetries,
      solRecovered,
      webOk,
      webNotFound,
      webUnavailable,
      browserFallbacks,
      browserRecovered,
      browserUnavailable,
      phoneConflicts,
      phoneVerified,
      deadlineSkipped,
      browserCircuitOpen,
      stage11DurationMs: Date.now() - stage11StartedAt
    }
  };
}

export {
  prefilterCandidatesForIdentity,
  deterministicQualificationDecision,
  appendReviewCandidates,
  discoveryYieldStats,
  classifyEntityType,
  postInnDedupe,
  duplicateInnConflictGroups,
  clearUnresolvedInnConflicts,
  actionableUnqualifiedLead
};
